import { createRoute, z } from '@hono/zod-openapi'

const ExpressionSchema: z.ZodType<ExpressionType> = z
  .lazy(() =>
    z
      .discriminatedUnion('type', [
        ComparisonExpressionSchema,
        BooleanOpExpressionSchema,
        ArithmeticExpressionSchema,
        DynamicVariableExpressionSchema,
        StringLiteralExpressionSchema,
        NumberLiteralExpressionSchema,
        BooleanLiteralExpressionSchema,
      ])
      .openapi({
        title: 'Expression',
        description:
          'A node in a deterministic expression AST. Exactly one variant is selected by the `type` discriminator. Terminal variants (`number_literal`, `string_literal`, `bool_literal`, `variable`) bottom out the recursion; `arithmetic`, `bool_op`, and `comparison` nest further sub-expressions.\n\nExtracted into a single named schema so the recursive union is defined once (was previously inlined at every operand site).',
        discriminator: {
          mapping: {
            arithmetic: '#/components/schemas/ArithmeticExpression',
            bool_literal: '#/components/schemas/BooleanLiteralExpression',
            bool_op: '#/components/schemas/BooleanOpExpression',
            comparison: '#/components/schemas/ComparisonExpression',
            number_literal: '#/components/schemas/NumberLiteralExpression',
            string_literal: '#/components/schemas/StringLiteralExpression',
            variable: '#/components/schemas/DynamicVariableExpression',
          },
          propertyName: 'type',
        },
      }),
  )
  .openapi('Expression')

type ArithmeticExpressionType = {
  left: z.infer<typeof ExpressionSchema>
  op: '+' | '-' | '*' | '/' | '%'
  right: z.infer<typeof ExpressionSchema>
  type: 'arithmetic'
}

const FunctionDefinitionSchema = z
  .object({
    name: z.string(),
    description: z.string().exactOptional(),
    parameters: z.looseObject({}).exactOptional(),
  })
  .openapi({ required: ['name'], title: 'FunctionDefinition' })
  .openapi('FunctionDefinition')

const FunctionToolSchema = z
  .object({
    type: z.literal('function'),
    shared: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'Whether this tool comes from the shared Tools Library. Responses merge shared tools into `tools` with `shared: true`; inline tools carry `shared: false`. Read-only: set by the server, not accepted in requests. When updating an assistant, omit `shared: true` tools from the request `tools` array and manage them through `tool_ids` instead — re-sending their definitions creates an inline duplicate (rejected with error code 10015 when the type allows only one instance per assistant).',
        readOnly: true,
      }),
    function: FunctionDefinitionSchema,
  })
  .openapi({ required: ['type', 'function'], title: 'FunctionTool' })
  .openapi('FunctionTool')

const WebhookToolParamsSchema = z
  .object({
    name: z.string().openapi({ description: 'The name of the tool.' }),
    description: z.string().openapi({ description: 'The description of the tool.' }),
    url: z
      .string()
      .openapi({
        description:
          'The URL of the external tool to be called. This URL is going to be used by the assistant. The URL can be templated like: `https://example.com/api/v1/{id}`, where `{id}` is a placeholder for a value that will be provided by the assistant if `path_parameters` are provided with the `id` attribute.',
        example: 'https://example.com/api/v1/function',
      }),
    method: z
      .enum(['GET', 'POST', 'PUT', 'DELETE', 'PATCH'])
      .default('POST')
      .exactOptional()
      .openapi({ description: 'The HTTP method to be used when calling the external tool.' }),
    headers: z
      .array(
        z
          .object({
            name: z.string().exactOptional(),
            value: z
              .string()
              .exactOptional()
              .openapi({
                description:
                  'The value of the header. Note that we support mustache templating for the value. For example you can use `Bearer {{#integration_secret}}test-secret{{/integration_secret}}` to pass the value of the integration secret as the bearer token. [Telnyx signature headers](https://developers.telnyx.com/docs/voice/programmable-voice/voice-api-webhooks) will be automatically added to the request.',
              }),
          })
          .openapi({ required: [] }),
      )
      .exactOptional()
      .openapi({ description: 'The headers to be sent to the external tool.' }),
    body_parameters: z
      .object({
        properties: z
          .looseObject({})
          .exactOptional()
          .openapi({ description: 'The properties of the body parameters.' }),
        required: z
          .array(z.string())
          .exactOptional()
          .openapi({ description: 'The required properties of the body parameters.' }),
        type: z.literal('object').exactOptional(),
      })
      .exactOptional()
      .openapi({
        description:
          'The body parameters the webhook tool accepts, described as a JSON Schema object. These parameters will be passed to the webhook as the body of the request. See the [JSON Schema reference](https://json-schema.org/understanding-json-schema) for documentation about the format',
        example: {
          properties: {
            age: { description: 'The age of the customer.', type: 'integer' },
            location: { description: 'The location of the customer.', type: 'string' },
          },
          required: ['age', 'location'],
          type: 'object',
        },
        required: [],
      }),
    path_parameters: z
      .object({
        properties: z
          .looseObject({})
          .exactOptional()
          .openapi({ description: 'The properties of the path parameters.' }),
        required: z
          .array(z.string())
          .exactOptional()
          .openapi({ description: 'The required properties of the path parameters.' }),
        type: z.literal('object').exactOptional(),
      })
      .exactOptional()
      .openapi({
        description:
          'The path parameters the webhook tool accepts, described as a JSON Schema object. These parameters will be passed to the webhook as the path of the request if the URL contains a placeholder for a value. See the [JSON Schema reference](https://json-schema.org/understanding-json-schema) for documentation about the format',
        example: {
          properties: { id: { description: 'The id of the customer.', type: 'string' } },
          required: ['id'],
          type: 'object',
        },
        required: [],
      }),
    query_parameters: z
      .object({
        properties: z
          .looseObject({})
          .exactOptional()
          .openapi({ description: 'The properties of the query parameters.' }),
        required: z
          .array(z.string())
          .exactOptional()
          .openapi({ description: 'The required properties of the query parameters.' }),
        type: z.literal('object').exactOptional(),
      })
      .exactOptional()
      .openapi({
        description:
          'The query parameters the webhook tool accepts, described as a JSON Schema object. These parameters will be passed to the webhook as the query of the request. See the [JSON Schema reference](https://json-schema.org/understanding-json-schema) for documentation about the format',
        example: {
          properties: { page: { description: 'The page number.', type: 'integer' } },
          required: ['page'],
          type: 'object',
        },
        required: [],
      }),
    preset_body_fields: z
      .looseObject({})
      .exactOptional()
      .openapi({
        description:
          'Body fields supplied by the assistant configuration rather than by the model. They are never advertised in the tool definition, so the LLM can neither see nor set them, and they take precedence over a `body_parameters` value of the same name. Values support mustache templating, so they can hold dynamic variables (`{{customer_id}}`) and integration secrets (`{{#integration_secret}}my-secret{{/integration_secret}}`). Not sent on `GET` requests, which carry no body.',
        example: { account_id: '{{customer_id}}', source: 'telnyx-assistant' },
      }),
    preset_query_params: z
      .looseObject({})
      .exactOptional()
      .openapi({
        description:
          'Query string parameters supplied by the assistant configuration rather than by the model. They are never advertised in the tool definition, so the LLM can neither see nor set them, and they take precedence over a `query_parameters` value of the same name. Values support mustache templating, so they can hold dynamic variables (`{{telnyx_end_user_target}}`) and integration secrets (`{{#integration_secret}}my-secret{{/integration_secret}}`). Unlike values templated directly into the `url`, these are percent-encoded, so a value such as `+15551234567` survives the round trip.',
        example: { caller: '{{telnyx_end_user_target}}', channel: 'voice' },
      }),
    async: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        description:
          'If async, the assistant will move forward without waiting for your server to respond.',
      }),
    async_timeout_ms: z
      .int()
      .min(1)
      .max(15000)
      .exactOptional()
      .openapi({
        description:
          'Maximum time in milliseconds that the conversation worker waits for an async webhook response before returning "Submitted" to the LLM. If unset, the platform default (currently 300ms) is used.',
      }),
    store_fields_as_variables: z
      .array(
        z
          .strictObject({
            name: z
              .string()
              .min(1)
              .openapi({
                description: 'The name of the dynamic variable to store the extracted value in.',
              }),
            value_path: z
              .string()
              .min(1)
              .openapi({
                description:
                  "A dot-notation path to the value in the webhook response body (e.g. 'customer.name' or 'id').",
              }),
          })
          .openapi({ required: ['name', 'value_path'] }),
      )
      .exactOptional()
      .openapi({
        description:
          'A list of mappings that extract values from the webhook response and store them as dynamic variables. Each mapping specifies a dynamic variable name and a dot-notation path to the value in the response body.',
      }),
    messages: z
      .array(
        z.xor([
          z
            .strictObject({
              type: z
                .literal('request_start')
                .openapi({
                  description:
                    'Speak the filler message immediately when the webhook request begins.',
                }),
              content: z.string().min(1).openapi({ description: 'The text the assistant speaks.' }),
              timing_ms: z
                .int()
                .min(100)
                .max(120000)
                .exactOptional()
                .openapi({
                  description:
                    'An optional delay value. This value is ignored for `request_start` messages.',
                }),
            })
            .openapi({ title: 'WebhookToolRequestStartMessage', required: ['type', 'content'] }),
          z
            .strictObject({
              type: z
                .literal('request_response_delayed')
                .openapi({
                  description:
                    'Speak the filler message after the configured delay if the webhook response is still pending.',
                }),
              content: z.string().min(1).openapi({ description: 'The text the assistant speaks.' }),
              timing_ms: z
                .int()
                .min(100)
                .max(120000)
                .openapi({
                  description: 'The delay in milliseconds from the start of the webhook request.',
                }),
            })
            .openapi({
              title: 'WebhookToolRequestResponseDelayedMessage',
              required: ['type', 'content', 'timing_ms'],
            }),
        ]),
      )
      .exactOptional()
      .openapi({
        description:
          'Filler messages spoken while a synchronous webhook request is in progress. `request_start` messages are spoken immediately when the request begins. `request_response_delayed` messages are spoken after `timing_ms` has elapsed only if the webhook response is still pending. Filler messages are not used for asynchronous webhooks.',
        example: [
          { type: 'request_start', content: 'Let me look that up for you.' },
          { type: 'request_response_delayed', content: 'Still working on that.', timing_ms: 5000 },
        ],
      }),
  })
  .openapi({ required: ['url', 'name', 'description'], title: 'WebhookToolParams' })
  .openapi('WebhookToolParams')

const InferenceEmbeddingWebhookToolSchema = z
  .object({
    type: z.literal('webhook'),
    timeout_ms: z
      .int()
      .max(60000)
      .default(5000)
      .exactOptional()
      .openapi({
        description:
          'The maximum number of milliseconds to wait for the webhook to respond before the tool call is aborted. Set this at the tool level, as a sibling of `type` — a `timeout_ms` nested inside the `webhook` object is stored but not applied, and the tool runs at this default instead. Applies when `webhook.async` is false.',
      }),
    shared: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'Whether this tool comes from the shared Tools Library. Responses merge shared tools into `tools` with `shared: true`; inline tools carry `shared: false`. Read-only: set by the server, not accepted in requests. When updating an assistant, omit `shared: true` tools from the request `tools` array and manage them through `tool_ids` instead — re-sending their definitions creates an inline duplicate (rejected with error code 10015 when the type allows only one instance per assistant).',
        readOnly: true,
      }),
    webhook: WebhookToolParamsSchema,
  })
  .openapi({ required: ['type', 'webhook'], title: 'WebhookTool' })
  .openapi('InferenceEmbeddingWebhookTool')

