const TranscriptionEndpointingPlanSchema = z
  .object({
    on_punctuation_seconds: z
      .float32()
      .default(0.1)
      .exactOptional()
      .openapi({ description: 'Seconds to wait after the transcript ends with punctuation.' }),
    on_no_punctuation_seconds: z
      .float32()
      .default(1.5)
      .exactOptional()
      .openapi({ description: 'Seconds to wait after the transcript ends without punctuation.' }),
    on_number_seconds: z
      .float32()
      .default(0.5)
      .exactOptional()
      .openapi({ description: 'Seconds to wait after the transcript ends with a number.' }),
  })
  .openapi({
    title: 'TranscriptionEndpointingPlan',
    description:
      'Endpointing thresholds used to decide when the user has finished speaking. Applies to non turn-taking transcription models. For `deepgram/flux`, use `transcription.settings.eot_threshold` / `eot_timeout_ms` / `eager_eot_threshold`. Evaluated per turn, on each caller transcript, only while `start_speaking_plan` is present: the tier whose suffix matches the transcript tail is applied (a transcript with no terminal punctuation or number falls through to `on_no_punctuation_seconds`); with no tiers configured (or a null nested plan), the per-turn wait stays on `start_speaking_plan.wait_seconds`.',
    required: [],
  })
  .openapi('TranscriptionEndpointingPlan')

const StartSpeakingPlanSchema = z
  .object({
    wait_seconds: z
      .float32()
      .min(0)
      .default(0.4)
      .exactOptional()
      .openapi({
        description:
          'Wait used when per-turn endpointing does not select a tier. While the plan is present this applies on every turn without a matching tier (including when `transcription_endpointing_plan` is unset); a matching tier replaces it for that turn, and a tier may be shorter or longer than this value.',
      }),
    transcription_endpointing_plan: z
      .union([TranscriptionEndpointingPlanSchema, z.null().nullable()])
      .exactOptional()
      .openapi({
        description:
          'Omit (stay null) when unset: the per-turn wait stays on `wait_seconds`. Setting `null` on an update clears a previously configured plan.',
      }),
  })
  .openapi({
    title: 'StartSpeakingPlan',
    description:
      "Controls when the assistant starts speaking after the user stops. These thresholds primarily apply to non turn-taking transcription models. For turn-taking models like `deepgram/flux`, end-of-turn detection is driven by the transcription end-of-turn settings under `transcription.settings` instead.\n\nSending any `start_speaking_plan` object — an empty `{}` included (the stored config fills in field defaults) — engages per-turn transcript matching: on each turn the transcript tail is evaluated against the configured `transcription_endpointing_plan` tiers, and the wait is set to the matching tier's seconds. When the transcript ends without terminal punctuation or a number and `transcription_endpointing_plan` is set, its `on_no_punctuation_seconds` tier applies. Only when no tier matches (`transcription_endpointing_plan` unset or null) does the wait stay on `wait_seconds`. Setting `start_speaking_plan` to `null` (or omitting it) turns per-turn matching off entirely, and the assistant starts speaking as soon as silence is detected.",
    required: [],
  })
  .openapi('StartSpeakingPlan')

const InferenceEmbeddingInterruptionSettingsSchema = z
  .object({
    enable: z
      .boolean()
      .default(true)
      .exactOptional()
      .openapi({ description: 'Whether users can interrupt the assistant while it is speaking.' }),
    disable_greeting_interruption: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'When true, disables user interruptions while the assistant greeting is playing.',
      }),
    start_speaking_plan: z
      .union([StartSpeakingPlanSchema, z.null().nullable()])
      .exactOptional()
      .openapi({
        description:
          'Presence of this object (even `{}`) enables per-turn transcript endpointing while it is set; setting it to `null` clears the plan and disables per-turn matching entirely. Omitting it from an update leaves the existing plan in place (updates are validated against the merged configuration).',
      }),
    interrupt_prediction_threshold: z
      .number()
      .min(0)
      .max(1)
      .nullable()
      .default(0)
      .exactOptional()
      .openapi({
        description:
          'Interrupt-prediction sensitivity, from 0.0 to 1.0. Set to null or 0.0 to disable interrupt prediction.',
      }),
  })
  .openapi({
    title: 'InterruptionSettings',
    description:
      'Settings for interruptions and how the assistant decides the user has finished speaking. These timings are most relevant when using non turn-taking transcription models. For turn-taking models like `deepgram/flux`, end-of-turn behavior is controlled by the transcription end-of-turn settings under `transcription.settings` (`eot_threshold`, `eot_timeout_ms`, `eager_eot_threshold`).',
    required: [],
  })
  .openapi('InferenceEmbeddingInterruptionSettings')

const AssistantIntegrationSchema = z
  .object({
    integration_id: z
      .string()
      .openapi({
        description:
          'Catalog integration ID to attach. This is the `id` from the integrations catalog at `/ai/integrations` (the same value also appears as `integration_id` on entries returned by `/ai/integrations/connections`). It is **not** the connection-level `id` from `/ai/integrations/connections`.',
      }),
    allowed_list: z
      .array(z.string())
      .exactOptional()
      .openapi({
        description:
          'Optional per-assistant allowlist of integration tool names. When omitted or empty, all tools allowed by the connected integration are available to the assistant.',
      }),
  })
  .openapi({
    title: 'AssistantIntegration',
    description:
      'Reference to a connected integration attached to an assistant. Discover available integrations with `/ai/integrations` and connected integrations with `/ai/integrations/connections`.',
    required: ['integration_id'],
  })
  .openapi('AssistantIntegration')

const ObservabilityStatusSchema = z
  .enum(['enabled', 'disabled'])
  .openapi({ title: 'ObservabilityStatus' })
  .openapi('ObservabilityStatus')

const PromptSyncStatusSchema = z
  .enum(['enabled', 'disabled'])
  .openapi({
    title: 'PromptSyncStatus',
    description:
      "Whether to auto-publish the assistant's instructions as a Langfuse prompt.\n\nWhen ENABLED + prompt_name set, every assistant create/update pushes\n`instructions` to Langfuse via create_prompt and stores the returned\nversion in prompt_version.",
  })
  .openapi('PromptSyncStatus')

const ObservabilitySchema = z
  .object({
    status: ObservabilityStatusSchema.default('disabled').exactOptional(),
    secret_key_ref: z.string().exactOptional().openapi({ title: 'Secret Key Ref' }),
    public_key_ref: z.string().exactOptional().openapi({ title: 'Public Key Ref' }),
    host: z.string().exactOptional().openapi({ title: 'Host' }),
    prompt_name: z.string().exactOptional().openapi({ title: 'Prompt Name' }),
    prompt_version: z.int().min(1).exactOptional().openapi({ title: 'Prompt Version' }),
    prompt_label: z.string().exactOptional().openapi({ title: 'Prompt Label' }),
    prompt_sync: PromptSyncStatusSchema.default('disabled').exactOptional(),
  })
  .openapi({ title: 'Observability', required: [] })
  .openapi('Observability')

const PostConversationSettingsSchema = z
  .object({
    enabled: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        description:
          'Whether post-conversation processing is enabled. When true, the assistant will be invoked after the conversation ends to perform any final tool calls. Defaults to false.',
      }),
  })
  .openapi({
    description:
      'Configuration for post-conversation processing. When enabled, the assistant receives one additional LLM turn after the conversation ends, allowing it to execute final tool calls such as sending a summary or updating a record via webhook or function tools. Integration and MCP server tools are not available post-conversation; call-control tools (e.g. hangup, transfer) are also unavailable. Beta feature.',
    required: [],
  })
  .openapi('PostConversationSettings')

const DelegationSettingsSchema = z
  .object({
    enabled: z
      .boolean()
      .default(true)
      .exactOptional()
      .openapi({
        description:
          'Whether the assistant delegates work to a backend model. Defaults to `true`: a GPT-Live assistant with delegation disabled can hold a conversation but can never look anything up or run a tool.',
      }),
    mode: z
      .enum(['telnyx', 'client'])
      .default('telnyx')
      .exactOptional()
      .openapi({
        description:
          "Who answers a delegation. `telnyx` runs the backend model on Telnyx with the assistant's own tools, MCP servers and observability. `client` relays the delegation to a server you host over the WebSocket configured in `websocket_settings`: Telnyx sends a `session.delegation.created` frame and waits for your `session.delegation.completed` answer. That answer is text only, since the socket offers no tool vocabulary. If no socket is connected the delegation is refused and the assistant tells the caller it cannot look things up right now. Defaults to `telnyx`.",
      }),
    model: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The backend model that answers delegations. Must be a model available for AI Assistants. When enabling `telnyx` delegation, explicitly set this field or `external_llm.model`; a configuration without either backend model is rejected. Only applies when `mode` is `telnyx`.',
      }),
    llm_api_key_ref: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "Integration secret identifier for the backend model's API key. Required for models from providers other than Telnyx, OpenAI and Anthropic. A raw `api_key` is rejected rather than ignored, so that no plaintext credential is stored on the assistant.",
      }),
    instructions: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "Extra instructions for the backend model, in addition to the assistant's own. Use this for the business rules the backend needs and the talking model does not.",
      }),
    speak_results: z
      .boolean()
      .default(true)
      .exactOptional()
      .openapi({
        description:
          "Whether the backend's answer is spoken to the caller. When `true` the result is appended as commentary and paraphrased aloud; when `false` it is kept as silent context that informs later answers without being read out. Defaults to `true`.",
      }),
    external_llm: ExternalLLMSchema.exactOptional().openapi({
      description:
        'Run the backend on your own OpenAI-compatible endpoint instead of a Telnyx-hosted model. As above, a raw `api_key` here is rejected — reference an integration secret with `external_llm.llm_api_key_ref` instead.',
    }),
  })
  .openapi({
    title: 'DelegationSettings',
    description:
      "Splits the conversation between a frontend model that talks to the caller and a backend model that does the work. On the GPT-Live route the frontend model cannot call tools at all — when it needs something done it raises a delegation and waits. On the chat completion route the frontend keeps a single `delegate` tool that returns immediately, so the conversation carries on while the backend works. Either way the backend's answer is spoken as commentary or kept as silent context, depending on `speak_results`. Beta feature.",
    required: [],
  })
  .openapi('DelegationSettings')

const WebsocketSettingsSchema = z
  .object({
    enabled: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        description:
          "Whether Telnyx opens a WebSocket to `url` for each of this assistant's conversations. Defaults to `false`.",
      }),
    url: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The `ws://` or `wss://` endpoint Telnyx connects to. Required when `enabled` is `true`. Must be externally reachable — localhost, private IP ranges and `.local` domains are rejected.',
      }),
    auth_ref: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Integration secret identifier whose value Telnyx sends as an `Authorization: Bearer <value>` header on the upgrade request. Resolved on every connection attempt, so a rotated secret is picked up by the next reconnect.',
      }),
  })
  .openapi({
    title: 'WebsocketSettings',
    description:
      'Streams conversation and telephony events to a WebSocket server you host, and accepts messages injected back into the conversation. Telnyx opens the connection as a client, once per conversation. Delivery is best effort throughout: while the connection is down events are dropped rather than queued, and no socket failure is ever allowed to affect the call. Beta feature.',
    required: [],
  })
  .openapi('WebsocketSettings')

const LLMConditionSchema = z
  .object({
    prompt: z
      .string()
      .openapi({
        description:
          "Natural-language criterion the model routes on. On calls this is offered to the model as the transition tool's description; on chat channels it is judged as a statement in the post-reply evaluation call.",
        example: 'The user has confirmed their booking details.',
        title: 'Prompt',
      }),
    type: z.literal('llm').openapi({ title: 'Type' }),
  })
  .openapi({
    description:
      "Edge condition routed by the assistant's LLM from a natural-language\nprompt.\n\nHow the edge is decided depends on the channel. On calls, each outgoing\n`llm` condition is offered to the assistant's model as a transition tool\nalongside the assistant's tools, and the edge fires when the model\nselects it; the platform does not evaluate the prompt itself, and\ninstructions that forbid or discourage tool calls can stop these edges\nfrom firing. On chat channels, the edge prompts are evaluated in a\nseparate model call after the reply, which does not use the assistant's\ninstructions. Use this for fuzzy intents that aren't expressible as a\ndeterministic expression (e.g. 'user wants to escalate to a human').",
    example: { prompt: 'The user has confirmed their booking details.', type: 'llm' },
    required: ['type', 'prompt'],
    title: 'LLMCondition',
  })
  .openapi('LLMCondition')

const ExpressionConditionSchema = z
  .object({
    expression: ExpressionSchema,
    type: z.literal('expression').openapi({ title: 'Type' }),
  })
  .openapi({
    description:
      "Edge condition evaluated as a deterministic expression AST.\n\nThe expression is computed against runtime dynamic variables and must\nevaluate to a boolean. Prefer this over `LLMCondition` when the rule is\na clean function of known variables — it's cheaper and predictable.",
    example: {
      expression: {
        left: { name: 'user_age', type: 'variable' },
        op: '>=',
        right: { type: 'number_literal', value: 18 },
        type: 'comparison',
      },
      type: 'expression',
    },
    required: ['type', 'expression'],
    title: 'ExpressionCondition',
  })
  .openapi('ExpressionCondition')

const DefaultConditionSchema = z
  .object({ type: z.literal('default').openapi({ title: 'Type' }) })
  .openapi({
    required: ['type'],
    title: 'DefaultCondition',
    description:
      "Fallback edge condition: fires only when no other edge's condition is true.\n\nEvaluated after every conditioned (`llm` / `expression`) edge regardless\nof declaration order, so it routes the flow whenever none of the node's\nother outgoing edges match. Valid **only** on edges leaving a `tool` or\n`speak` node, where the deterministic step auto-advances and must always\nhave somewhere to go. A tool/speak node with any outgoing edge is required\nto carry exactly one `default` edge so it never dead-ends; a tool/speak\nnode with no outgoing edges is a valid terminal step. Carries no parameters.",
    example: { type: 'default' },
  })
  .openapi('DefaultCondition')

const NodeTargetSchema = z
  .object({
    node_id: z
      .string()
      .openapi({
        description: 'ID of the node this edge transitions into.',
        example: 'n_billing',
        title: 'Node Id',
      }),
    type: z.literal('node').openapi({ title: 'Type' }),
  })
  .openapi({
    description:
      "Edge target referencing another node within the same flow.\n\nThe runtime transitions the active node to `node_id` and continues\nprocessing within the current assistant's flow.",
    required: ['type', 'node_id'],
    title: 'NodeTarget',
  })
  .openapi('NodeTarget')

const NodePositionSchema = z
  .object({
    x: z
      .number()
      .openapi({ description: 'Horizontal coordinate in the authoring canvas.', title: 'X' }),
    y: z
      .number()
      .openapi({ description: 'Vertical coordinate in the authoring canvas.', title: 'Y' }),
  })
  .openapi({
    description:
      '2D coordinates for a node, used by authoring UIs to lay out the graph.\n\nPurely a presentation aid. The runtime ignores `position`; it round-trips\nthrough the API so frontends can persist the graph layout customers\narrange in the editor.',
    required: ['x', 'y'],
    title: 'NodePosition',
  })
  .openapi('NodePosition')

const AssistantTargetSchema = z
  .object({
    assistant_id: z
      .string()
      .openapi({
        description: 'ID of the assistant the conversation transitions to.',
        example: 'assistant-billing',
        title: 'Assistant Id',
      }),
    position: NodePositionSchema.exactOptional().openapi({
      description:
        "Optional canvas coordinates for rendering the target assistant as a node in authoring UIs. Pure presentation — the runtime ignores it; round-trips so frontends can persist graph layout across reloads. When multiple edges target the same assistant, each edge's `position` is independent (frontends typically use the first non-null one).",
      example: { x: 600, y: 80 },
    }),
    type: z.literal('assistant').openapi({ title: 'Type' }),
    voice_mode: z
      .enum(['unified', 'distinct'])
      .default('unified')
      .exactOptional()
      .openapi({
        description:
          "Voice behavior when handing off to the target assistant, mirroring the handoff tool's `voice_mode`. `unified` (default) keeps the current voice across the handoff; `distinct` lets the target assistant speak with its own configured voice. Only applies to assistant targets — node targets override voice via the node's own `voice_settings`.",
        title: 'Voice Mode',
      }),
  })
  .openapi({
    description:
      "Edge target referencing a different assistant.\n\nWhen the edge fires, the conversation hands off to `assistant_id`: the\nactive assistant on the conversation row is rewritten and the new\nassistant's flow starts at its own `start_node_id`. The current turn's\nLLM response is delivered to the user as-is; subsequent turns route\nto the new assistant.",
    required: ['type', 'assistant_id'],
    title: 'AssistantTarget',
  })
  .openapi('AssistantTarget')

const FlowEdgeSchema = z
  .object({
    condition: z
      .discriminatedUnion('type', [
        LLMConditionSchema,
        ExpressionConditionSchema,
        DefaultConditionSchema,
      ])
      .openapi({
        description:
          'Condition that gates the transition. Discriminated by `type`: `llm`, `expression`.',
        discriminator: {
          mapping: {
            expression: '#/components/schemas/ExpressionCondition',
            llm: '#/components/schemas/LLMCondition',
            default: '#/components/schemas/DefaultCondition',
          },
          propertyName: 'type',
        },
        title: 'Condition',
      }),
    id: z
      .string()
      .openapi({
        description: 'Caller-supplied unique identifier for this edge within the flow.',
        example: 'e_age_gate',
        title: 'Id',
      }),
    start_node_id: z
      .string()
      .openapi({
        description: 'ID of the node this edge transitions away from.',
        title: 'Start Node Id',
      }),
    target: z
      .discriminatedUnion('type', [NodeTargetSchema, AssistantTargetSchema])
      .openapi({
        description:
          'Destination of the transition. Discriminated by `type`: `node` (jump to another node in this flow) or `assistant` (hand off to a different assistant).',
        discriminator: {
          mapping: {
            assistant: '#/components/schemas/AssistantTarget',
            node: '#/components/schemas/NodeTarget',
          },
          propertyName: 'type',
        },
        title: 'Target',
      }),
  })
  .openapi({
    description:
      "Directed transition from one node to a target, gated by a condition.\n\nThe target is either another node in the same flow (`NodeTarget`) or a\ndifferent assistant (`AssistantTarget`). Multiple edges may share a\n`start_node_id`. On calls, `expression` conditions are evaluated before\nthe model turn and take precedence over `llm` conditions regardless of\ndeclaration order, while `llm` conditions are offered to the assistant's\nmodel as transition tools and fire when the model selects one. On chat\nchannels, an `expression` condition that is true when the turn begins\nroutes before the reply is generated; all conditioned edges that remain\nare considered together in declaration order after the reply, and the\nfirst true one wins.",
    required: ['id', 'start_node_id', 'target', 'condition'],
    title: 'FlowEdge',
  })
  .openapi('FlowEdge')

type FlowNodeType = {
  external_llm?: z.infer<typeof ExternalLLMSchema>
  id: string
  instructions: string
  instructions_mode?: 'replace' | 'append'
  llm_api_key_ref?: string
  model?: string
  name?: string
  position?: z.infer<typeof NodePositionSchema>
  shared_tool_ids?: string[]
  tools?: z.infer<typeof AssistantToolsSchema>[]
  tools_mode?: 'replace' | 'append'
  transcription?: z.infer<typeof TranscriptionSettingsSchema>
  type?: 'prompt'
  voice_settings?: z.infer<typeof InferenceEmbeddingVoiceSettingsSchema>
}

const FlowNodeSchema: z.ZodType<FlowNodeType> = z
  .object({
    external_llm: ExternalLLMSchema.exactOptional().openapi({
      description:
        "Override for `Assistant.external_llm` while this node is active. Use this to route a node's turns to a different external LLM (different `model`, `base_url`, credentials). Part of the LLM bundle — see `model` for cascade semantics. Mutually exclusive with `model` on the node (a single LLM identity per node).",
    }),
    id: z
      .string()
      .openapi({
        description: 'Caller-supplied unique identifier for this node within the flow.',
        title: 'Id',
      }),
    instructions: z
      .string()
      .openapi({
        description: 'Prompt that drives the LLM while this node is active. Required.',
        title: 'Instructions',
      }),
    instructions_mode: z
      .enum(['replace', 'append'])
      .default('replace')
      .exactOptional()
      .openapi({
        description:
          "How `instructions` combine with the assistant-level instructions. `replace` (default): the node's instructions are used alone. `append`: the node's instructions are concatenated after the assistant's instructions.",
        title: 'Instructions Mode',
      }),
    llm_api_key_ref: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Override for `Assistant.llm_api_key_ref` while this node is active. Part of the LLM bundle — see `model` for cascade semantics.',
        title: 'Llm Api Key Ref',
      }),
    model: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "Override for `Assistant.model` while this node is active. Part of the LLM bundle (`model` + `llm_api_key_ref` + `external_llm`): when any of the three is set on the node, all three are taken from the node and the assistant-level LLM identity is not consulted. When none of the three is set, the assistant's bundle cascades unchanged.",
        title: 'Model',
      }),
    name: z
      .string()
      .exactOptional()
      .openapi({
        description: 'Optional human-readable label, displayed in authoring UIs.',
        title: 'Name',
      }),
    position: NodePositionSchema.exactOptional().openapi({
      description:
        'Optional canvas coordinates used by authoring UIs to lay out the graph. Ignored by the runtime; round-trips so frontends can persist graph layout across reloads.',
    }),
    shared_tool_ids: z
      .array(z.string())
      .exactOptional()
      .openapi({
        description:
          'IDs of shared (org-level) tools available at this node. Knowledge bases are attached the same way — via a shared retrieval tool. Tools not listed here are not callable while this node is active.',
        title: 'Shared Tool Ids',
      }),
    tools: z
      .array(AssistantToolsSchema)
      .exactOptional()
      .openapi({
        description:
          "Full tool definitions for this node, resolved from `shared_tool_ids` server-side. Populated on responses so clients can render the flow without a follow-up fetch per shared tool. Ignored on input — set `shared_tool_ids` to configure a node's tools.",
        title: 'Tools',
      }),
    tools_mode: z
      .enum(['replace', 'append'])
      .default('replace')
      .exactOptional()
      .openapi({
        description:
          "How `shared_tool_ids` combine with the assistant-level tool set. `replace` (default): only the node's tools are callable. `append`: the node's tools are added to the assistant's tools. Ignored when `shared_tool_ids` is null.",
        title: 'Tools Mode',
      }),
    transcription: TranscriptionSettingsSchema.exactOptional().openapi({
      description: 'Per-node transcription override (response form).',
    }),
    type: z
      .literal('prompt')
      .default('prompt')
      .exactOptional()
      .openapi({
        description: 'Node kind discriminator. `prompt` is an LLM-driven step.',
        title: 'Type',
      }),
    voice_settings: InferenceEmbeddingVoiceSettingsSchema.exactOptional().openapi({
      description: 'Per-node voice override (response form).',
    }),
  })
  .openapi({
    description: 'One step in a conversation flow, as returned by the API.',
    required: ['id', 'instructions'],
    title: 'FlowNode',
  })
  .openapi('FlowNode')

const ToolNodeSchema = z
  .object({
    id: z
      .string()
      .openapi({
        description: 'Caller-supplied unique identifier for this node within the flow.',
        title: 'Id',
      }),
    name: z
      .string()
      .exactOptional()
      .openapi({
        description: 'Optional human-readable label, displayed in authoring UIs.',
        title: 'Name',
      }),
    position: NodePositionSchema.exactOptional().openapi({
      description:
        'Optional canvas coordinates used by authoring UIs to lay out the graph. Ignored by the runtime; round-trips so frontends can persist graph layout across reloads.',
    }),
    shared_tool_id: z
      .string()
      .openapi({
        description:
          "ID of the single shared (org-level) tool this node executes. When the flow reaches this node the tool runs as a deliberate step (no LLM turn); its outgoing `llm` / `expression` edges route the flow on the tool's outcome. Arguments are filled from the conversation's dynamic variables by name — a dynamic variable whose name matches one of the tool's parameters supplies that argument. Cross-validated against the org's shared tools on write.",
        title: 'Shared Tool Id',
      }),
    tool: AssistantToolsSchema.exactOptional().openapi({
      description:
        'Full tool definition resolved from `shared_tool_id` server-side. Populated on responses so clients can render the node without a follow-up fetch. Ignored on input — set `shared_tool_id`.',
    }),
    type: z
      .literal('tool')
      .default('tool')
      .exactOptional()
      .openapi({
        description: 'Node kind discriminator. Always `tool` for a tool node.',
        title: 'Type',
      }),
    message: z
      .string()
      .regex(/\S/)
      .min(1)
      .exactOptional()
      .openapi({
        description:
          "Optional message delivered to the user verbatim immediately before the tool executes — an announcement such as 'One moment while I look that up.' No LLM turn and no customer turn: the message is spoken/sent, then the tool runs, in the same deterministic step. `{{variable}}` placeholders are interpolated from the conversation's dynamic variables (unresolved → empty string); the tool's own result is not yet available when the message is rendered. Omit for a silent tool step.",
        example: 'One moment while I process your payment.',
        title: 'Message',
      }),
  })
  .openapi({
    description: 'A standalone tool step in a conversation flow, as returned by the API.',
    required: ['id', 'shared_tool_id'],
    title: 'ToolNode',
  })
  .openapi('ToolNode')

const SpeakNodeSchema = z
  .object({
    type: z
      .literal('speak')
      .default('speak')
      .exactOptional()
      .openapi({
        title: 'Type',
        description: 'Node kind discriminator. Always `speak` for a speak node.',
      }),
    id: z
      .string()
      .openapi({
        title: 'Id',
        description: 'Caller-supplied unique identifier for this node within the flow.',
      }),
    name: z
      .string()
      .exactOptional()
      .openapi({
        title: 'Name',
        description: 'Optional human-readable label, displayed in authoring UIs.',
      }),
    message: z
      .string()
      .openapi({
        title: 'Message',
        description:
          "Message delivered to the user verbatim when the flow reaches this node. No LLM turn — the text is spoken/sent exactly as written. `{{variable}}` placeholders are interpolated from the conversation's dynamic variables; an unresolved placeholder renders as an empty string. After delivering, the flow routes via the node's outgoing `llm` / `expression` edges (commonly a single unconditional edge).",
      }),
    position: NodePositionSchema.exactOptional().openapi({
      description:
        'Optional canvas coordinates used by authoring UIs to lay out the graph. Ignored by the runtime; round-trips so frontends can persist graph layout across reloads.',
    }),
  })
  .openapi({
    required: ['id', 'message'],
    title: 'SpeakNode',
    description: 'A standalone scripted-message step in a flow, as returned by the API.',
  })
  .openapi('SpeakNode')

type ConversationFlowType = {
  edges?: z.infer<typeof FlowEdgeSchema>[]
  nodes: (
    | z.infer<typeof FlowNodeSchema>
    | z.infer<typeof ToolNodeSchema>
    | z.infer<typeof SpeakNodeSchema>
  )[]
  start_node_id: string
}

const ConversationFlowSchema: z.ZodType<ConversationFlowType> = z
  .object({
    edges: z
      .array(FlowEdgeSchema)
      .exactOptional()
      .openapi({ description: 'Directed transitions between nodes.', title: 'Edges' }),
    nodes: z
      .array(
        z
          .xor([FlowNodeSchema, ToolNodeSchema, SpeakNodeSchema])
          .openapi({
            discriminator: {
              mapping: {
                prompt: '#/components/schemas/FlowNode',
                speak: '#/components/schemas/SpeakNode',
                tool: '#/components/schemas/ToolNode',
              },
              propertyName: 'type',
            },
          }),
      )
      .openapi({ description: 'All nodes in the flow.', title: 'Nodes' }),
    start_node_id: z
      .string()
      .openapi({
        description: 'ID of the node where the conversation begins.',
        title: 'Start Node Id',
      }),
  })
  .openapi({
    description: 'Conversation flow as returned by the API.',
    example: {
      edges: [
        {
          condition: { prompt: 'The caller is asking about a bill or charge.', type: 'llm' },
          id: 'e_intake_to_billing',
          start_node_id: 'n_intake',
          target: { node_id: 'n_billing', type: 'node' },
        },
        {
          condition: { prompt: 'The caller has explicitly asked for a human.', type: 'llm' },
          id: 'e_intake_to_escalation_assistant',
          start_node_id: 'n_intake',
          target: {
            assistant_id: 'assistant-human-handoff',
            position: { x: 600, y: 80 },
            type: 'assistant',
            voice_mode: 'distinct',
          },
        },
      ],
      nodes: [
        {
          type: 'prompt',
          id: 'n_intake',
          instructions: "Greet the caller and ask what they're calling about.",
          name: 'Intake',
          position: { x: 120, y: 80 },
          shared_tool_ids: ['tool-faq-kb'],
        },
        {
          type: 'prompt',
          id: 'n_billing',
          instructions:
            "Focus on billing questions. Look up the caller's latest invoice with the billing tool before answering.",
          instructions_mode: 'append',
          model: 'moonshotai/Kimi-K2.6',
          name: 'Billing',
          position: { x: 420, y: 80 },
          shared_tool_ids: ['tool-billing-lookup'],
          tools_mode: 'append',
        },
      ],
      start_node_id: 'n_intake',
    },
    required: ['start_node_id', 'nodes'],
    title: 'ConversationFlow',
  })
  .openapi('ConversationFlow')

type InferenceEmbeddingAssistantType = {
  id: string
  name: string
  created_at: string
  version_id?: string
  version_created_at?: string
  description?: string
  model: string
  instructions: string
  tools?: z.infer<typeof AssistantToolsSchema>
  mcp_servers?: z.infer<typeof AssistantMCPServerSchema>[]
  a2a_agents?: z.infer<typeof AssistantA2AAgentSchema>[]
  greeting?: string
  llm_api_key_ref?: string
  external_llm?: z.infer<typeof ExternalLLMSchema>
  fallback_config?: z.infer<typeof FallbackConfigSchema>
  voice_settings?: z.infer<typeof InferenceEmbeddingVoiceSettingsSchema>
  avatar_settings?: z.infer<typeof AvatarSettingsSchema> | null
  transcription?: z.infer<typeof TranscriptionSettingsSchema>
  telephony_settings?: z.infer<typeof TelephonySettingsSchema>
  messaging_settings?: z.infer<typeof MessagingSettingsSchema>
  enabled_features?: z.infer<typeof EnabledFeaturesSchema>[]
  insight_settings?: z.infer<typeof InsightSettingsSchema>
  privacy_settings?: z.infer<typeof PrivacySettingsSchema>
  dynamic_variables_webhook_url?: string
  dynamic_variables_webhook_timeout_ms?: number
  dynamic_variables?: { [key: string]: unknown }
  import_metadata?: z.infer<typeof ImportMetadataSchema>
  widget_settings?: z.infer<typeof WidgetSettingsSchema>
  interruption_settings?: z.infer<typeof InferenceEmbeddingInterruptionSettingsSchema>
  integrations?: z.infer<typeof AssistantIntegrationSchema>[]
  observability_settings?: z.infer<typeof ObservabilitySchema>
  version_name?: string
  related_mission_ids?: string[]
  tags?: string[]
  post_conversation_settings?: z.infer<typeof PostConversationSettingsSchema>
  delegation_settings?: z.infer<typeof DelegationSettingsSchema>
  websocket_settings?: z.infer<typeof WebsocketSettingsSchema>
  conversation_flow?: z.infer<typeof ConversationFlowSchema>
}

const InferenceEmbeddingAssistantSchema: z.ZodType<InferenceEmbeddingAssistantType> = z
  .object({
    id: z.string(),
    name: z.string(),
    created_at: z.iso.datetime({ offset: true }),
    version_id: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Identifier for the assistant version returned by version-aware assistant endpoints.',
      }),
    version_created_at: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({ description: 'Timestamp when this assistant version was created.' }),
    description: z.string().exactOptional(),
    model: z
      .string()
      .openapi({
        description:
          'ID of the model to use when `external_llm` is not set. You can use the [Get models API](https://developers.telnyx.com/api-reference/openai-chat/get-available-models-openai-compatible) to see available models. If `external_llm` is provided, the assistant uses `external_llm` instead of this field. If neither `model` nor `external_llm` is provided, Telnyx applies the default model.',
      }),
    instructions: z
      .string()
      .openapi({
        description:
          'System instructions for the assistant. These may be templated with [dynamic variables](https://developers.telnyx.com/docs/inference/ai-assistants/dynamic-variables)',
      }),
    tools: AssistantToolsSchema.exactOptional().openapi({
      description:
        "The assistant's tools. Responses merge the assistant's shared Tools Library tools into this array alongside inline tools, each flagged `shared: true`; inline tools carry `shared: false`. On update, a sent `tools` array fully replaces the inline tools only — shared tools stay attached unless `tool_ids` changes. Each tool type except `function`, `webhook`, and `client_side_tool` allows at most one instance per assistant across both sources.",
    }),
    mcp_servers: z
      .array(AssistantMCPServerSchema)
      .default([])
      .exactOptional()
      .openapi({
        description:
          'MCP servers attached to the assistant. Create MCP servers with `/ai/mcp_servers`, then reference them by `id` here.',
      }),
    a2a_agents: z
      .array(AssistantA2AAgentSchema)
      .default([])
      .exactOptional()
      .openapi({
        description:
          "A2A agents this assistant can delegate to. Tools are not stored here: at the start of every conversation each agent's card is fetched and one tool is derived per skill the card advertises, named `a2a_<name>_<skill_id>`. The following limits are not enforced when the assistant is saved, and anything past them is dropped when the conversation starts: 64 agents per assistant, 64 skills per card, 128 derived tools per assistant, and a 6 second budget for all card fetches combined. An agent whose card cannot be fetched costs the assistant that capability for the conversation; it does not fail the call.",
      }),
    greeting: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Text that the assistant will use to start the conversation. This may be templated with [dynamic variables](https://developers.telnyx.com/docs/inference/ai-assistants/dynamic-variables). Use an empty string to have the assistant wait for the user to speak first. Use the special value `<assistant-speaks-first-with-model-generated-message>` to have the assistant generate the greeting based on the system instructions.',
      }),
    llm_api_key_ref: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "This is only needed when using third-party inference providers selected by `model`. The `identifier` for an integration secret [/v2/integration_secrets](https://developers.telnyx.com/api-reference/integration-secrets/create-a-secret) that refers to your LLM provider's API key. For bring-your-own endpoint authentication, use `external_llm.llm_api_key_ref` instead. Warning: Free plans are unlikely to work with this integration.",
      }),
    external_llm: ExternalLLMSchema.exactOptional(),
    fallback_config: FallbackConfigSchema.exactOptional(),
    voice_settings: InferenceEmbeddingVoiceSettingsSchema.exactOptional(),
    avatar_settings: z
      .union([AvatarSettingsSchema, z.null().nullable()])
      .exactOptional()
      .openapi({
        description:
          '**Beta:** Saved avatar configuration for supported realtime browser conversations. `null` means that no avatar is configured.',
      }),
    transcription: TranscriptionSettingsSchema.exactOptional(),
    telephony_settings: TelephonySettingsSchema.exactOptional(),
    messaging_settings: MessagingSettingsSchema.exactOptional(),
    enabled_features: z
      .array(EnabledFeaturesSchema)
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .exactOptional()
      .openapi({ title: 'Enabled Features' }),
    insight_settings: InsightSettingsSchema.exactOptional(),
    privacy_settings: PrivacySettingsSchema.exactOptional(),
    dynamic_variables_webhook_url: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'If `dynamic_variables_webhook_url` is set, Telnyx sends a POST request to this URL at the start of the conversation to resolve dynamic variables. **Gotcha:** the webhook response must wrap variables under a top-level `dynamic_variables` object, e.g. `{"dynamic_variables": {"customer_name": "Jane"}}`. Returning a flat object will be ignored and variables will fall back to their defaults. See the [dynamic variables guide](https://developers.telnyx.com/docs/inference/ai-assistants/dynamic-variables) for the full request/response format and timeout behavior.',
      }),
    dynamic_variables_webhook_timeout_ms: z
      .int()
      .min(1)
      .max(10000)
      .default(1500)
      .exactOptional()
      .openapi({
        description:
          'Timeout in milliseconds for the dynamic variables webhook. Must be between 1 and 10000 ms. If the webhook does not respond within this timeout, the call proceeds with default values. See the [dynamic variables guide](https://developers.telnyx.com/docs/inference/ai-assistants/dynamic-variables).',
      }),
    dynamic_variables: z
      .looseObject({})
      .exactOptional()
      .openapi({ description: 'Map of dynamic variables and their values' }),
    import_metadata: ImportMetadataSchema.exactOptional(),
    widget_settings: WidgetSettingsSchema.exactOptional(),
    interruption_settings: InferenceEmbeddingInterruptionSettingsSchema.exactOptional(),
    integrations: z
      .array(AssistantIntegrationSchema)
      .default([])
      .exactOptional()
      .openapi({
        description:
          "Connected integrations attached to the assistant. The catalog of available integrations is at `/ai/integrations`; the user's connected integrations are at `/ai/integrations/connections`. Each item references a catalog integration by `integration_id`.",
      }),
    observability_settings: ObservabilitySchema.exactOptional(),
    version_name: z
      .string()
      .max(50)
      .default('New assistant')
      .exactOptional()
      .openapi({ description: 'Human-readable name for the assistant version.' }),
    related_mission_ids: z
      .array(z.string())
      .default([])
      .exactOptional()
      .openapi({ description: 'IDs of missions related to this assistant.' }),
    tags: z
      .array(z.string())
      .default([])
      .exactOptional()
      .openapi({
        description:
          'Tags associated with the assistant. Tags can also be managed with the assistant tag endpoints.',
      }),
    post_conversation_settings: PostConversationSettingsSchema.exactOptional(),
    delegation_settings: DelegationSettingsSchema.exactOptional(),
    websocket_settings: WebsocketSettingsSchema.exactOptional(),
    conversation_flow: ConversationFlowSchema.exactOptional(),
  })
  .openapi({ required: ['id', 'name', 'created_at', 'model', 'instructions'] })
  .openapi('InferenceEmbeddingAssistant')

type AssistantsListDataType = { data: z.infer<typeof InferenceEmbeddingAssistantSchema>[] }

type BooleanLiteralExpressionType = { type: 'bool_literal'; value: boolean }

type BooleanOpExpressionType = {
  op: 'and' | 'or' | 'not'
  operands: z.infer<typeof ExpressionSchema>[]
  type: 'bool_op'
}

type ComparisonExpressionType = {
  left: z.infer<typeof ExpressionSchema>
  op: '==' | '!=' | '<' | '<=' | '>' | '>=' | 'contains' | 'not_contains'
  right: z.infer<typeof ExpressionSchema>
  type: 'comparison'
}

const ExternalLLMReqSchema = z
  .object({
    model: z
      .string()
      .openapi({ description: 'Model identifier to use with the external LLM endpoint.' }),
    base_url: z.string().openapi({ description: 'Base URL for the external LLM endpoint.' }),
    llm_api_key_ref: z
      .string()
      .exactOptional()
      .openapi({ description: 'Integration secret identifier for the external LLM API key.' }),
    authentication_method: AuthenticationMethodSchema.exactOptional(),
    certificate_ref: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Integration secret identifier for the client certificate used with certificate authentication.',
      }),
    token_retrieval_url: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'URL used to retrieve an access token when certificate authentication is enabled.',
      }),
    forward_metadata: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        description:
          'When `true`, Telnyx forwards the assistant\'s dynamic variables to the external LLM endpoint as a top-level `extra_metadata` object on the chat completion request body. Defaults to `false`. Example payload sent to the external endpoint: `{"extra_metadata": {"customer_name": "Jane", "account_id": "acct_789", "telnyx_agent_target": "+13125550100", "telnyx_end_user_target": "+13125550123"}}`. Distinct from OpenAI\'s native `metadata` field, which has its own size and type limits.',
      }),
    extra_headers: z
      .record(
        z.string(),
        z
          .string()
          .regex(/^(?:[!-~]|[!-~][ -~]*[!-~])?$/)
          .max(4096),
      )
      .refine((val) => Object.keys(val).length <= 32)
      .superRefine((o, ctx) => {
        const regex = new RegExp(
          "^(?!(?:[Aa][Cc][Cc][Ee][Pp][Tt][-_][Ee][Nn][Cc][Oo][Dd][Ii][Nn][Gg]|[Aa][Uu][Tt][Hh][Oo][Rr][Ii][Zz][Aa][Tt][Ii][Oo][Nn]|[Cc][Oo][Nn][Nn][Ee][Cc][Tt][Ii][Oo][Nn]|[Cc][Oo][Nn][Tt][Ee][Nn][Tt][-_][Ee][Nn][Cc][Oo][Dd][Ii][Nn][Gg]|[Cc][Oo][Nn][Tt][Ee][Nn][Tt][-_][Ll][Ee][Nn][Gg][Tt][Hh]|[Cc][Oo][Nn][Tt][Ee][Nn][Tt][-_][Tt][Yy][Pp][Ee]|[Cc][Oo][Oo][Kk][Ii][Ee]|[Ee][Xx][Pp][Ee][Cc][Tt]|[Hh][Oo][Ss][Tt]|[Kk][Ee][Ee][Pp][-_][Aa][Ll][Ii][Vv][Ee]|[Pp][Rr][Oo][Xx][Yy][-_][Aa][Uu][Tt][Hh][Ee][Nn][Tt][Ii][Cc][Aa][Tt][Ee]|[Pp][Rr][Oo][Xx][Yy][-_][Aa][Uu][Tt][Hh][Oo][Rr][Ii][Zz][Aa][Tt][Ii][Oo][Nn]|[Pp][Rr][Oo][Xx][Yy][-_][Cc][Oo][Nn][Nn][Ee][Cc][Tt][Ii][Oo][Nn]|[Ss][Ee][Tt][-_][Cc][Oo][Oo][Kk][Ii][Ee]|[Tt][Ee]|[Tt][Rr][Aa][Ii][Ll][Ee][Rr]|[Tt][Rr][Aa][Nn][Ss][Ff][Ee][Rr][-_][Ee][Nn][Cc][Oo][Dd][Ii][Nn][Gg]|[Uu][Pp][Gg][Rr][Aa][Dd][Ee]|[Xx][-_][Hh][Oo][Ss][Tt][-_][Rr][Ee][Ww][Rr][Ii][Tt][Ee]|[Xx][-_][Rr][Ee][Qq][Uu][Ee][Ss][Tt][-_][Ii][Dd]|[Xx][-_][Tt][Rr][Aa][Cc][Ee][-_][Ii][Dd])$|[Xx][-_][Tt][Ee][Ll][Nn][Yy][Xx][-_]|[Xx][-_][Ss][Tt][Aa][Ii][Nn][Ll][Ee][Ss][Ss][-_]|[-_]{4}[Ss][Tt][Aa][Ii][Nn][Ll][Ee][Ss][Ss])[!#$%&'*+.^_`|~0-9A-Za-z-]{1,128}$",
        )
        for (const k of Object.keys(o)) {
          if (!regex.test(k)) {
            ctx.addIssue({ code: 'custom', path: [k] })
          }
        }
      })
      .nullable()
      .exactOptional()
      .openapi({
        description:
          "Custom HTTP headers Telnyx sets on every request to the external LLM endpoint, in addition to the authentication header. Keys are header names, values are static strings. At most 32 headers. Reserved names are rejected: accept-encoding, authorization, connection, content-encoding, content-length, content-type, cookie, expect, host, keep-alive, proxy-authenticate, proxy-authorization, proxy-connection, set-cookie, te, trailer, transfer-encoding, upgrade, x-host-rewrite, x-request-id, x-trace-id, and any x-telnyx-* or x-stainless-* header; '_' counts as '-' when names are compared. Names must be valid HTTP header names (RFC 7230 token, at most 128 characters) and must not repeat (case-insensitive). Values must be printable ASCII, at most 4096 characters, with no leading or trailing whitespace. Values are stored as plain text and returned when the assistant is retrieved.",
      }),
  })
  .openapi({ required: ['model', 'base_url'], title: 'ExternalLLMReq' })
  .openapi('ExternalLLMReq')

const FlowNodeReqSchema = z
  .object({
    external_llm: ExternalLLMReqSchema.exactOptional().openapi({
      description:
        "Override for `Assistant.external_llm` while this node is active. Use this to route a node's turns to a different external LLM (different `model`, `base_url`, credentials). Part of the LLM bundle — see `model` for cascade semantics. Mutually exclusive with `model` on the node (a single LLM identity per node).",
    }),
    id: z
      .string()
      .openapi({
        description: 'Caller-supplied unique identifier for this node within the flow.',
        example: 'n_intake',
        title: 'Id',
      }),
    instructions: z
      .string()
      .openapi({
        description: 'Prompt that drives the LLM while this node is active. Required.',
        example: "Greet the caller and ask what they're calling about.",
        title: 'Instructions',
      }),
    instructions_mode: z
      .enum(['replace', 'append'])
      .default('replace')
      .exactOptional()
      .openapi({
        description:
          "How `instructions` combine with the assistant-level instructions. `replace` (default): the node's instructions are used alone. `append`: the node's instructions are concatenated after the assistant's instructions.",
        title: 'Instructions Mode',
      }),
    llm_api_key_ref: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Override for `Assistant.llm_api_key_ref` while this node is active. Part of the LLM bundle — see `model` for cascade semantics.',
        example: 'my-key-ref',
        title: 'Llm Api Key Ref',
      }),
    model: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "Override for `Assistant.model` while this node is active. Part of the LLM bundle (`model` + `llm_api_key_ref` + `external_llm`): when any of the three is set on the node, all three are taken from the node and the assistant-level LLM identity is not consulted. When none of the three is set, the assistant's bundle cascades unchanged.",
        example: 'moonshotai/Kimi-K2.6',
        title: 'Model',
      }),
    name: z
      .string()
      .exactOptional()
      .openapi({
        description: 'Optional human-readable label, displayed in authoring UIs.',
        example: 'Intake',
        title: 'Name',
      }),
    position: NodePositionSchema.exactOptional().openapi({
      description:
        'Optional canvas coordinates used by authoring UIs to lay out the graph. Ignored by the runtime; round-trips so frontends can persist graph layout across reloads.',
      example: { x: 120, y: 80 },
    }),
    shared_tool_ids: z
      .array(z.string())
      .exactOptional()
      .openapi({
        description:
          'IDs of shared (org-level) tools available at this node. Knowledge bases are attached the same way — via a shared retrieval tool. Tools not listed here are not callable while this node is active.',
        example: ['tool-faq-kb', 'tool-billing-lookup'],
        title: 'Shared Tool Ids',
      }),
    tools_mode: z
      .enum(['replace', 'append'])
      .default('replace')
      .exactOptional()
      .openapi({
        description:
          "How `shared_tool_ids` combine with the assistant-level tool set. `replace` (default): only the node's tools are callable. `append`: the node's tools are added to the assistant's tools. Ignored when `shared_tool_ids` is null.",
        title: 'Tools Mode',
      }),
    transcription: TranscriptionSettingsSchema.exactOptional().openapi({
      description:
        "Per-node transcription override (model/language/region). Unset fields cascade from the assistant-level transcription. A node that sets `model`, `fallback_models`, or `challenger` doesn't inherit the assistant's `fallback_models` or `challenger`; it uses only the ones it sets. Otherwise it inherits them, and they must fit the model and language the node runs; a change they no longer fit is rejected.",
    }),
    type: z
      .literal('prompt')
      .default('prompt')
      .exactOptional()
      .openapi({
        description:
          'Node kind discriminator. `prompt` (default) is an LLM-driven step; `tool` is a standalone tool execution and `speak` a scripted message (see `ToolNodeReq` / `SpeakNodeReq`).',
        title: 'Type',
      }),
    voice_settings: InferenceEmbeddingVoiceSettingsSchema.exactOptional().openapi({
      description:
        'Per-node voice override. Only fields set here override the assistant-level voice settings; unset fields cascade.',
    }),
  })
  .openapi({
    description:
      'One step in a conversation flow, as supplied by API clients.\n\nEach node carries the prompt, tool scope, and optional overrides for\nmodel/voice/transcription. Unset overrides cascade from the assistant.',
    example: {
      id: 'n_intake',
      instructions: "Greet the caller and ask what they're calling about.",
      name: 'Intake',
      position: { x: 120, y: 80 },
      shared_tool_ids: ['tool-faq-kb'],
      type: 'prompt',
    },
    required: ['id', 'instructions'],
    title: 'FlowNodeReq',
  })
  .openapi('FlowNodeReq')

const ToolNodeReqSchema = z
  .object({
    id: z
      .string()
      .openapi({
        description: 'Caller-supplied unique identifier for this node within the flow.',
        example: 'n_charge',
        title: 'Id',
      }),
    message: z
      .string()
      .regex(/\S/)
      .min(1)
      .exactOptional()
      .openapi({
        description:
          "Optional message delivered to the user verbatim immediately before the tool executes — an announcement such as 'One moment while I look that up.' No LLM turn and no customer turn: the message is spoken/sent, then the tool runs, in the same deterministic step. `{{variable}}` placeholders are interpolated from the conversation's dynamic variables (unresolved → empty string); the tool's own result is not yet available when the message is rendered. Omit for a silent tool step.",
        example: 'One moment while I process your payment.',
        title: 'Message',
      }),
    name: z
      .string()
      .exactOptional()
      .openapi({
        description: 'Optional human-readable label, displayed in authoring UIs.',
        example: 'Charge card',
        title: 'Name',
      }),
    position: NodePositionSchema.exactOptional().openapi({
      description:
        'Optional canvas coordinates used by authoring UIs to lay out the graph. Ignored by the runtime; round-trips so frontends can persist graph layout across reloads.',
      example: { x: 300, y: 200 },
    }),
    shared_tool_id: z
      .string()
      .openapi({
        description:
          "ID of the single shared (org-level) tool this node executes. When the flow reaches this node the tool runs as a deliberate step (no LLM turn); its outgoing `llm` / `expression` edges route the flow on the tool's outcome. Arguments are filled from the conversation's dynamic variables by name — a dynamic variable whose name matches one of the tool's parameters supplies that argument. Cross-validated against the org's shared tools on write.",
        example: 'tool-charge-card',
        title: 'Shared Tool Id',
      }),
    type: z
      .literal('tool')
      .default('tool')
      .exactOptional()
      .openapi({
        description: 'Node kind discriminator. Always `tool` for a tool node.',
        title: 'Type',
      }),
  })
  .openapi({
    description:
      "A standalone tool step in a conversation flow, as supplied by clients.\n\nUnlike a prompt node, a tool node has no instructions or model — it\nisn't an LLM turn. Reaching it deterministically runs one shared tool\n(arguments filled from matching dynamic variables by name), then routes\nvia outgoing `llm` / `expression` edges, with exactly one `default`\nfallback edge required when the node has any outgoing edges (the\ntool's outcome is readable as `telnyx_last_tool_status_code` in\n`expression` conditions).",
    example: {
      id: 'n_charge',
      message: 'One moment while I process your payment.',
      name: 'Charge card',
      position: { x: 300, y: 200 },
      shared_tool_id: 'tool-charge-card',
      type: 'tool',
    },
    required: ['id', 'shared_tool_id'],
    title: 'ToolNodeReq',
  })
  .openapi('ToolNodeReq')

const SpeakNodeReqSchema = z
  .object({
    type: z
      .literal('speak')
      .default('speak')
      .exactOptional()
      .openapi({
        title: 'Type',
        description: 'Node kind discriminator. Always `speak` for a speak node.',
      }),
    id: z
      .string()
      .openapi({
        title: 'Id',
        description: 'Caller-supplied unique identifier for this node within the flow.',
        example: 'n_greeting',
      }),
    name: z
      .string()
      .exactOptional()
      .openapi({
        title: 'Name',
        description: 'Optional human-readable label, displayed in authoring UIs.',
        example: 'Greeting',
      }),
    message: z
      .string()
      .openapi({
        title: 'Message',
        description:
          "Message delivered to the user verbatim when the flow reaches this node. No LLM turn — the text is spoken/sent exactly as written. `{{variable}}` placeholders are interpolated from the conversation's dynamic variables; an unresolved placeholder renders as an empty string. After delivering, the flow routes via the node's outgoing `llm` / `expression` edges (commonly a single unconditional edge).",
        example: 'Thanks for calling, {{caller_name}}. Connecting you now.',
      }),
    position: NodePositionSchema.exactOptional().openapi({
      description:
        'Optional canvas coordinates used by authoring UIs to lay out the graph. Ignored by the runtime; round-trips so frontends can persist graph layout across reloads.',
      example: { x: 60, y: 80 },
    }),
  })
  .openapi({
    required: ['id', 'message'],
    title: 'SpeakNodeReq',
    description:
      "A standalone scripted-message step in a flow, as supplied by clients.\n\nUnlike a prompt node, a speak node has no instructions or model — it isn't\nan LLM turn. Reaching it delivers `message` to the user verbatim (with\n`{{variable}}` interpolation), then routes via outgoing `llm` /\n`expression` edges.",
    example: {
      id: 'n_greeting',
      message: 'Thanks for calling, {{caller_name}}. Connecting you now.',
      name: 'Greeting',
      position: { x: 60, y: 80 },
      type: 'speak',
    },
  })
  .openapi('SpeakNodeReq')

type ConversationFlowReqType = {
  edges?: z.infer<typeof FlowEdgeSchema>[]
  nodes: (
    | z.infer<typeof FlowNodeReqSchema>
    | z.infer<typeof ToolNodeReqSchema>
    | z.infer<typeof SpeakNodeReqSchema>
  )[]
  start_node_id: string
}

const FallbackConfigReqSchema = z
  .object({
    model: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Fallback Telnyx-hosted model to use when the primary LLM provider is unavailable.',
      }),
    llm_api_key_ref: z
      .string()
      .exactOptional()
      .openapi({ description: 'Integration secret identifier for the fallback model API key.' }),
    external_llm: ExternalLLMReqSchema.exactOptional(),
  })
  .openapi({ title: 'FallbackConfigReq', required: [] })
  .openapi('FallbackConfigReq')

const AvatarSettingsRequestSchema = z
  .xor([TelnyxAvatarSettingsSchema])
  .openapi({
    title: 'AvatarSettingsRequest',
    description:
      '**Beta:** Telnyx avatar configuration accepted when creating or updating an assistant. Set `provider` to `telnyx`.',
    discriminator: {
      propertyName: 'provider',
      mapping: { telnyx: '#/components/schemas/TelnyxAvatarSettings' },
    },
  })
  .openapi('AvatarSettingsRequest')

const ObservabilityReqSchema = z
  .object({
    status: ObservabilityStatusSchema.default('disabled').exactOptional(),
    secret_key_ref: z.string().exactOptional().openapi({ title: 'Secret Key Ref' }),
    public_key_ref: z.string().exactOptional().openapi({ title: 'Public Key Ref' }),
    host: z.string().exactOptional().openapi({ title: 'Host' }),
    prompt_name: z.string().exactOptional().openapi({ title: 'Prompt Name' }),
    prompt_version: z.int().min(1).exactOptional().openapi({ title: 'Prompt Version' }),
    prompt_label: z.string().exactOptional().openapi({ title: 'Prompt Label' }),
    prompt_sync: PromptSyncStatusSchema.default('disabled').exactOptional(),
  })
  .openapi({ title: 'ObservabilityReq', required: [] })
  .openapi('ObservabilityReq')

const PostConversationSettingsReqSchema = z
  .object({
    enabled: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        description:
          'Whether post-conversation processing is enabled. When true, the assistant will be invoked after the conversation ends to perform any final tool calls. Defaults to false.',
      }),
  })
  .openapi({
    description:
      'Configuration for post-conversation processing. When enabled, the assistant receives one additional LLM turn after the conversation ends, allowing it to execute final tool calls such as sending a summary or updating a record via webhook or function tools. Integration and MCP server tools are not available post-conversation; call-control tools (e.g. hangup, transfer) are also unavailable. Beta feature.',
    required: [],
  })
  .openapi('PostConversationSettingsReq')

const ConversationFlowReqSchema: z.ZodType<ConversationFlowReqType> = z
  .object({
    edges: z
      .array(FlowEdgeSchema)
      .exactOptional()
      .openapi({
        description: 'Directed transitions between nodes. May be empty for a single-node flow.',
        title: 'Edges',
      }),
    nodes: z
      .array(
        z
          .xor([FlowNodeReqSchema, ToolNodeReqSchema, SpeakNodeReqSchema])
          .openapi({
            discriminator: {
              mapping: {
                prompt: '#/components/schemas/FlowNodeReq',
                tool: '#/components/schemas/ToolNodeReq',
                speak: '#/components/schemas/SpeakNodeReq',
              },
              propertyName: 'type',
            },
          }),
      )
      .openapi({
        description:
          'All nodes in the flow. Must contain `start_node_id`. Each node is a prompt node (`type: prompt`), a tool node (`type: tool`), or a speak node (`type: speak`).',
        title: 'Nodes',
      }),
    start_node_id: z
      .string()
      .openapi({
        description: 'ID of the node where the conversation begins.',
        example: 'n_intake',
        title: 'Start Node Id',
      }),
  })
  .openapi({
    description:
      "Conversation flow as supplied by API clients (create / update).\n\nA directed graph of `FlowNodeReq` connected by `FlowEdge`s. Validation\nenforces unique node/edge IDs, that `start_node_id` references a real\nnode, and that every edge's endpoints reference real nodes.",
    example: {
      edges: [
        {
          condition: { prompt: 'The caller is asking about a bill or charge.', type: 'llm' },
          id: 'e_intake_to_billing',
          start_node_id: 'n_intake',
          target: { node_id: 'n_billing', type: 'node' },
        },
        {
          condition: { prompt: 'The caller has explicitly asked for a human.', type: 'llm' },
          id: 'e_intake_to_escalation_assistant',
          start_node_id: 'n_intake',
          target: {
            assistant_id: 'assistant-human-handoff',
            position: { x: 600, y: 80 },
            type: 'assistant',
            voice_mode: 'distinct',
          },
        },
      ],
      nodes: [
        {
          type: 'prompt',
          id: 'n_intake',
          instructions: "Greet the caller and ask what they're calling about.",
          name: 'Intake',
          position: { x: 120, y: 80 },
          shared_tool_ids: ['tool-faq-kb'],
        },
        {
          type: 'prompt',
          id: 'n_billing',
          instructions:
            "Focus on billing questions. Look up the caller's latest invoice with the billing tool before answering.",
          instructions_mode: 'append',
          model: 'moonshotai/Kimi-K2.6',
          name: 'Billing',
          position: { x: 420, y: 80 },
          shared_tool_ids: ['tool-billing-lookup'],
          tools_mode: 'append',
        },
      ],
      start_node_id: 'n_intake',
    },
    required: ['start_node_id', 'nodes'],
    title: 'ConversationFlowReq',
  })
  .openapi('ConversationFlowReq')

