const ComparisonExpressionSchema: z.ZodType<ComparisonExpressionType> &
  z.core.$ZodTypeDiscriminable = z
  .lazy(() =>
    z
      .object({
        left: ExpressionSchema,
        op: z
          .enum(['==', '!=', '<', '<=', '>', '>=', 'contains', 'not_contains'])
          .openapi({
            description:
              'Relational/membership operator. `contains` / `not_contains` apply to strings (substring) and arrays (membership).',
            title: 'Op',
          }),
        right: ExpressionSchema,
        type: z.literal('comparison').openapi({ title: 'Type' }),
      })
      .openapi({
        description:
          'Compare two sub-expressions with a relational or membership operator.\n\nEvaluates to a boolean. Used in edge conditions to gate transitions on\nruntime values, e.g. `user_age >= 18` or `tier == "gold"`.',
        example: {
          left: { name: 'user_age', type: 'variable' },
          op: '>=',
          right: { type: 'number_literal', value: 18 },
          type: 'comparison',
        },
        required: ['type', 'op', 'left', 'right'],
        title: 'ComparisonExpression',
      }),
  )
  .openapi('ComparisonExpression')

const BooleanOpExpressionSchema: z.ZodType<BooleanOpExpressionType> & z.core.$ZodTypeDiscriminable =
  z
    .lazy(() =>
      z
        .object({
          op: z
            .enum(['and', 'or', 'not'])
            .openapi({
              description: 'Logical operator. `not` is unary; `and`/`or` are n-ary (>=2).',
              title: 'Op',
            }),
          operands: z
            .array(ExpressionSchema)
            .openapi({
              description:
                'Operand sub-expressions. Length must be exactly 1 for `not` and >= 2 for `and`/`or`.',
              title: 'Operands',
            }),
          type: z.literal('bool_op').openapi({ title: 'Type' }),
        })
        .openapi({
          description:
            'Combine sub-expressions with a logical operator (`and` / `or` / `not`).\n\n`and` and `or` accept two or more operands; `not` accepts exactly one.',
          example: {
            op: 'and',
            operands: [
              { name: 'is_premium', type: 'variable' },
              {
                left: { name: 'user_age', type: 'variable' },
                op: '>=',
                right: { type: 'number_literal', value: 18 },
                type: 'comparison',
              },
            ],
            type: 'bool_op',
          },
          required: ['type', 'op', 'operands'],
          title: 'BooleanOpExpression',
        }),
    )
    .openapi('BooleanOpExpression')

const ArithmeticExpressionSchema: z.ZodType<ArithmeticExpressionType> &
  z.core.$ZodTypeDiscriminable = z
  .lazy(() =>
    z
      .object({
        left: ExpressionSchema,
        op: z
          .enum(['+', '-', '*', '/', '%'])
          .openapi({
            description: 'Arithmetic operator applied to `left` and `right`.',
            title: 'Op',
          }),
        right: ExpressionSchema,
        type: z.literal('arithmetic').openapi({ title: 'Type' }),
      })
      .openapi({
        description:
          'Numeric expression: applies an arithmetic operator to two sub-expressions.\n\nUseful for derived numeric checks, e.g. `cart_total + shipping > 50`.\nBoth operands should resolve to numbers at runtime.',
        example: {
          left: { name: 'cart_total', type: 'variable' },
          op: '+',
          right: { name: 'shipping_cost', type: 'variable' },
          type: 'arithmetic',
        },
        required: ['type', 'op', 'left', 'right'],
        title: 'ArithmeticExpression',
      }),
  )
  .openapi('ArithmeticExpression')

const DynamicVariableExpressionSchema: z.ZodType<DynamicVariableExpressionType> &
  z.core.$ZodTypeDiscriminable = z
  .object({
    name: z
      .string()
      .openapi({
        description: 'Variable name to look up in the runtime context.',
        example: 'user_age',
        title: 'Name',
      }),
    type: z.literal('variable').openapi({ title: 'Type' }),
  })
  .openapi({
    description:
      "Reference a dynamic variable by name.\n\nResolved at runtime from the assistant's dynamic-variables context (see\n`Assistant.dynamic_variables` and the dynamic-variables webhook).",
    example: { name: 'user_age', type: 'variable' },
    required: ['type', 'name'],
    title: 'DynamicVariableExpression',
  })
  .openapi('DynamicVariableExpression')

type StringLiteralExpressionType = { type: 'string_literal'; value: string }

const StringLiteralExpressionSchema: z.ZodType<StringLiteralExpressionType> &
  z.core.$ZodTypeDiscriminable = z
  .object({
    type: z.literal('string_literal').openapi({ title: 'Type' }),
    value: z
      .string()
      .openapi({ description: 'Literal string value.', example: 'gold', title: 'Value' }),
  })
  .openapi({
    description: 'Constant string value.',
    example: { type: 'string_literal', value: 'gold' },
    required: ['type', 'value'],
    title: 'StringLiteralExpression',
  })
  .openapi('StringLiteralExpression')

type NumberLiteralExpressionType = { type: 'number_literal'; value: number }

const NumberLiteralExpressionSchema: z.ZodType<NumberLiteralExpressionType> &
  z.core.$ZodTypeDiscriminable = z
  .object({
    type: z.literal('number_literal').openapi({ title: 'Type' }),
    value: z
      .number()
      .openapi({ description: 'Literal numeric value.', example: 18, title: 'Value' }),
  })
  .openapi({
    description: 'Constant numeric value (float; integers are accepted and stored as float).',
    example: { type: 'number_literal', value: 18 },
    required: ['type', 'value'],
    title: 'NumberLiteralExpression',
  })
  .openapi('NumberLiteralExpression')

const BooleanLiteralExpressionSchema: z.ZodType<BooleanLiteralExpressionType> &
  z.core.$ZodTypeDiscriminable = z
  .object({
    type: z.literal('bool_literal').openapi({ title: 'Type' }),
    value: z.boolean().openapi({ description: 'Literal boolean value.', title: 'Value' }),
  })
  .openapi({
    description: "Constant boolean value. Useful for unconditional ('always') edges.",
    example: { type: 'bool_literal', value: true },
    required: ['type', 'value'],
    title: 'BooleanLiteralExpression',
  })
  .openapi('BooleanLiteralExpression')

type ExpressionType =
  | z.infer<typeof ComparisonExpressionSchema>
  | z.infer<typeof BooleanOpExpressionSchema>
  | z.infer<typeof ArithmeticExpressionSchema>
  | z.infer<typeof DynamicVariableExpressionSchema>
  | z.infer<typeof StringLiteralExpressionSchema>
  | z.infer<typeof NumberLiteralExpressionSchema>
  | z.infer<typeof BooleanLiteralExpressionSchema>

