type UpdateAssistantRequestType = {
  name?: string
  model?: string
  instructions?: string
  tools?: z.infer<typeof AssistantToolsSchema>
  mcp_servers?: z.infer<typeof AssistantMCPServerSchema>[]
  a2a_agents?: z.infer<typeof AssistantA2AAgentSchema>[]
  tool_ids?: string[]
  description?: string
  greeting?: string
  llm_api_key_ref?: string
  external_llm?: z.infer<typeof ExternalLLMReqSchema>
  fallback_config?: z.infer<typeof FallbackConfigReqSchema>
  voice_settings?: z.infer<typeof InferenceEmbeddingVoiceSettingsSchema>
  avatar_settings?: z.infer<typeof AvatarSettingsRequestSchema> | null
  transcription?: z.infer<typeof TranscriptionSettingsSchema>
  telephony_settings?: z.infer<typeof TelephonySettingsSchema>
  messaging_settings?: z.infer<typeof MessagingSettingsSchema>
  enabled_features?: z.infer<typeof EnabledFeaturesSchema>[]
  insight_settings?: z.infer<typeof InsightSettingsSchema>
  privacy_settings?: z.infer<typeof PrivacySettingsSchema>
  dynamic_variables_webhook_url?: string
  dynamic_variables_webhook_timeout_ms?: number
  dynamic_variables?: { [key: string]: unknown }
  widget_settings?: z.infer<typeof WidgetSettingsSchema>
  interruption_settings?: z.infer<typeof InferenceEmbeddingInterruptionSettingsSchema>
  integrations?: z.infer<typeof AssistantIntegrationSchema>[]
  observability_settings?: z.infer<typeof ObservabilityReqSchema>
  tags?: string[]
  version_name?: string
  post_conversation_settings?: z.infer<typeof PostConversationSettingsReqSchema>
  delegation_settings?: z.infer<typeof DelegationSettingsSchema>
  websocket_settings?: z.infer<typeof WebsocketSettingsSchema>
  conversation_flow?: z.infer<typeof ConversationFlowReqSchema>
}

const UpdateAssistantRequestSchema: z.ZodType<UpdateAssistantRequestType> = z
  .object({
    name: z.string().exactOptional(),
    model: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'ID of the model to use when `external_llm` is not set. You can use the [Get models API](https://developers.telnyx.com/api-reference/openai-chat/get-available-models-openai-compatible) to see available models. If `external_llm` is provided, the assistant uses `external_llm` instead of this field. If neither `model` nor `external_llm` is provided, Telnyx applies the default model.',
      }),
    instructions: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'System instructions for the assistant. These may be templated with [dynamic variables](https://developers.telnyx.com/docs/inference/ai-assistants/dynamic-variables)',
      }),
    tools: AssistantToolsSchema.exactOptional().openapi({
      description:
        "Deprecated for new integrations. Inline tool definitions available to the assistant. Prefer `tool_ids` to attach shared tools created with the AI Tools endpoints. On update, a sent `tools` array fully replaces the assistant's inline tools; omit the field to leave the inline tools unchanged. Each tool type except `function`, `webhook`, and `client_side_tool` allows at most one instance per assistant, counted across inline `tools` and shared `tool_ids` combined — sending a duplicate of such a type returns HTTP 400 with error code 10015. Responses merge shared tools into `tools` with `shared: true`; when updating, omit those tools from the `tools` array and manage them through `tool_ids` instead.",
    }),
    mcp_servers: z
      .array(AssistantMCPServerSchema)
      .default([])
      .exactOptional()
      .openapi({
        description:
          'MCP servers attached to the assistant. Create MCP servers with `/ai/mcp_servers`, then reference them by `id` here.',
      }),
    a2a_agents: z
      .array(AssistantA2AAgentSchema)
      .exactOptional()
      .openapi({
        description:
          "A2A agents this assistant can delegate to. Tools are not stored here: at the start of every conversation each agent's card is fetched and one tool is derived per skill the card advertises, named `a2a_<name>_<skill_id>`. The following limits are not enforced when the assistant is saved, and anything past them is dropped when the conversation starts: 64 agents per assistant, 64 skills per card, 128 derived tools per assistant, and a 6 second budget for all card fetches combined. An agent whose card cannot be fetched costs the assistant that capability for the conversation; it does not fail the call. Omit this field to leave the assistant's agents unchanged; send an empty array to remove them all.",
      }),
    tool_ids: z
      .array(z.string())
      .exactOptional()
      .openapi({
        title: 'Ids of shared tools',
        description:
          "IDs of shared tools to attach to the assistant. New integrations should prefer `tool_ids` over inline `tools`. On update, a sent `tool_ids` array fully replaces the assistant's attached shared tools; omit the field to leave them unchanged. Single-instance tool types are counted across inline `tools` and `tool_ids` combined, so attaching a shared tool of such a type when an instance already exists returns HTTP 400 with error code 10015.",
      }),
    description: z.string().exactOptional(),
    greeting: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Text that the assistant will use to start the conversation. This may be templated with [dynamic variables](https://developers.telnyx.com/docs/inference/ai-assistants/dynamic-variables). Use an empty string to have the assistant wait for the user to speak first. Use the special value `<assistant-speaks-first-with-model-generated-message>` to have the assistant generate the greeting based on the system instructions.',
      }),
    llm_api_key_ref: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "This is only needed when using third-party inference providers selected by `model`. The `identifier` for an integration secret [/v2/integration_secrets](https://developers.telnyx.com/api-reference/integration-secrets/create-a-secret) that refers to your LLM provider's API key. For bring-your-own endpoint authentication, use `external_llm.llm_api_key_ref` instead. Warning: Free plans are unlikely to work with this integration.",
      }),
    external_llm: ExternalLLMReqSchema.exactOptional(),
    fallback_config: FallbackConfigReqSchema.exactOptional(),
    voice_settings: InferenceEmbeddingVoiceSettingsSchema.exactOptional(),
    avatar_settings: z
      .union([AvatarSettingsRequestSchema, z.null().nullable()])
      .exactOptional()
      .openapi({
        description:
          "**Beta:** Replaces the assistant's avatar configuration. Omit this field to leave the current configuration unchanged, or set it to `null` to remove the configuration.",
      }),
    transcription: TranscriptionSettingsSchema.exactOptional(),
    telephony_settings: TelephonySettingsSchema.exactOptional(),
    messaging_settings: MessagingSettingsSchema.exactOptional(),
    enabled_features: z
      .array(EnabledFeaturesSchema)
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .exactOptional(),
    insight_settings: InsightSettingsSchema.exactOptional(),
    privacy_settings: PrivacySettingsSchema.exactOptional(),
    dynamic_variables_webhook_url: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'If `dynamic_variables_webhook_url` is set, Telnyx sends a POST request to this URL at the start of the conversation to resolve dynamic variables. **Gotcha:** the webhook response must wrap variables under a top-level `dynamic_variables` object, e.g. `{"dynamic_variables": {"customer_name": "Jane"}}`. Returning a flat object will be ignored and variables will fall back to their defaults. See the [dynamic variables guide](https://developers.telnyx.com/docs/inference/ai-assistants/dynamic-variables) for the full request/response format and timeout behavior.',
      }),
    dynamic_variables_webhook_timeout_ms: z
      .int()
      .min(1)
      .max(10000)
      .default(1500)
      .exactOptional()
      .openapi({
        description:
          'Timeout in milliseconds for the dynamic variables webhook. Must be between 1 and 10000 ms. If the webhook does not respond within this timeout, the call proceeds with default values. See the [dynamic variables guide](https://developers.telnyx.com/docs/inference/ai-assistants/dynamic-variables).',
      }),
    dynamic_variables: z
      .looseObject({})
      .exactOptional()
      .openapi({ description: 'Map of dynamic variables and their default values' }),
    widget_settings: WidgetSettingsSchema.exactOptional(),
    interruption_settings: InferenceEmbeddingInterruptionSettingsSchema.exactOptional(),
    integrations: z
      .array(AssistantIntegrationSchema)
      .default([])
      .exactOptional()
      .openapi({
        description:
          "Connected integrations attached to the assistant. The catalog of available integrations is at `/ai/integrations`; the user's connected integrations are at `/ai/integrations/connections`. Each item references a catalog integration by `integration_id`.",
      }),
    observability_settings: ObservabilityReqSchema.exactOptional(),
    tags: z
      .array(z.string())
      .default([])
      .exactOptional()
      .openapi({
        description:
          'Tags associated with the assistant. Tags can also be managed with the assistant tag endpoints.',
      }),
    version_name: z
      .string()
      .max(50)
      .default('New assistant')
      .exactOptional()
      .openapi({ description: 'Human-readable name for the assistant version.' }),
    post_conversation_settings: PostConversationSettingsReqSchema.exactOptional(),
    delegation_settings: DelegationSettingsSchema.exactOptional(),
    websocket_settings: WebsocketSettingsSchema.exactOptional(),
    conversation_flow: ConversationFlowReqSchema.exactOptional(),
  })
  .openapi({ title: 'UpdateAssistantRequest', required: [] })
  .openapi('UpdateAssistantRequest')

