const AIAssistantAddMessagesRequestSchema = z
  .object({
    client_state: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Use this field to add state to every subsequent webhook. It must be a valid Base-64 encoded string.',
        example: 'aGF2ZSBhIG5pY2UgZGF5ID1d',
      }),
    command_id: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Use this field to avoid duplicate commands. Telnyx will ignore any command with the same `command_id` for the same `call_control_id`.',
        example: '891510ac-f3e4-11e8-af5b-de00688a4901',
      }),
    messages: z
      .array(
        z
          .discriminatedUnion('role', [
            UserMessageSchema,
            AssistantMessageSchema,
            ToolMessageSchema,
            SystemMessageSchema,
            DeveloperMessageSchema,
          ])
          .openapi({
            discriminator: {
              propertyName: 'role',
              mapping: {
                user: '#/components/schemas/UserMessage',
                assistant: '#/components/schemas/AssistantMessage',
                tool: '#/components/schemas/ToolMessage',
                system: '#/components/schemas/SystemMessage',
                developer: '#/components/schemas/DeveloperMessage',
              },
            },
          }),
      )
      .exactOptional()
      .openapi({ description: 'The messages to add to the conversation.' }),
    trigger_response: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        description:
          'When `true`, the injected messages immediately trigger an assistant response/turn instead of waiting for the next natural turn or idle timeout. This may interrupt a user who is still speaking.',
      }),
  })
  .openapi({
    title: 'AI Assistant Add Messages Request',
    example: {
      client_state: 'aGF2ZSBhIG5pY2UgZGF5ID1d',
      command_id: '891510ac-f3e4-11e8-af5b-de00688a4901',
      messages: [{ role: 'system', content: "Get the user's favorite color" }],
      trigger_response: false,
    },
    required: [],
  })
  .openapi('AIAssistantAddMessagesRequest')

