const AdvancedOrderSchema = z
  .object({
    country_code: z
      .string()
      .length(2)
      .default('US')
      .exactOptional()
      .openapi({ title: 'Country Code' }),
    comments: z.string().max(255).default('').exactOptional().openapi({ title: 'Comments' }),
    quantity: z.int().min(1).max(10000).default(1).exactOptional().openapi({ title: 'Quantity' }),
    area_code: z.string().max(3).default('').exactOptional().openapi({ title: 'Area Code' }),
    phone_number_type: z
      .unknown()
      .superRefine((val, ctx) => {
        if (Array.isArray(val)) {
          {
            const Schema = z.enum([
              'local',
              'mobile',
              'toll_free',
              'shared_cost',
              'national',
              'landline',
            ])
            for (let i = 0; i < val.length; i++) {
              if (!Schema.safeParse(val[i]).success) {
                ctx.addIssue({ code: 'custom' })
              }
            }
          }
        }
      })
      .default('')
      .exactOptional(),
    features: z
      .array(z.enum(['sms', 'mms', 'voice', 'fax', 'emergency']))
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .exactOptional()
      .openapi({ title: 'Features' }),
    customer_reference: z
      .string()
      .default('')
      .exactOptional()
      .openapi({ title: 'Customer Reference' }),
    id: z.uuid().exactOptional().openapi({ title: 'Id' }),
    status: z
      .unknown()
      .superRefine((val, ctx) => {
        if (Array.isArray(val)) {
          {
            const Schema = z.enum(['pending', 'processing', 'ordered'])
            for (let i = 0; i < val.length; i++) {
              if (!Schema.safeParse(val[i]).success) {
                ctx.addIssue({ code: 'custom' })
              }
            }
          }
        }
      })
      .exactOptional(),
    orders: z
      .array(z.uuid())
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .exactOptional()
      .openapi({ title: 'Orders' }),
    requirement_group_id: z
      .uuid()
      .exactOptional()
      .openapi({
        title: 'Requirement Group ID',
        description: 'The ID of the requirement group associated with this advanced order',
        example: '3fa85f64-5717-4562-b3fc-2c963f66afa6',
      }),
  })
  .openapi({ title: 'Advanced Order', required: [] })
  .openapi('AdvancedOrder')

const AdvancedOrderRequestSchema = z
