const AutorespConfigSchemaSchema = z
  .object({
    op: z.enum(['start', 'stop', 'info']).openapi({ title: 'Op', example: 'start' }),
    keywords: z.array(z.string()).openapi({ title: 'Keywords', example: ['START', 'BEGIN'] }),
    resp_text: z
      .string()
      .exactOptional()
      .openapi({ title: 'Resp Text', example: 'Thank you for subscribing to our service.' }),
    country_code: z.string().openapi({ title: 'Country Code', example: '*' }),
    id: z.string().openapi({ title: 'Id', example: 'b8f9c1c0-5b5a-4b1e-8c1c-0b5a4b1e8c1c' }),
    created_at: z.iso.datetime({ offset: true }).openapi({ title: 'Created At' }),
    updated_at: z.iso.datetime({ offset: true }).openapi({ title: 'Updated At' }),
  })
  .openapi({
    title: 'AutorespConfigSchema',
    required: ['op', 'keywords', 'country_code', 'id', 'created_at', 'updated_at'],
  })
  .openapi('AutorespConfigSchema')

const AutorespConfigResponseSchemaSchema = z
  .object({ data: AutorespConfigSchemaSchema })
  .openapi({ title: 'AutorespConfigResponseSchema', required: ['data'] })
  .openapi('AutorespConfigResponseSchema')

const MessagingPaginationMetaSchema = z
  .object({
    total_pages: z.int().openapi({ example: 3 }),
    total_results: z.int().openapi({ example: 55 }),
    page_number: z.int().openapi({ example: 2 }),
    page_size: z.int().openapi({ example: 25 }),
  })
  .openapi({ required: ['total_pages', 'total_results', 'page_size', 'page_number'] })
  .openapi('MessagingPaginationMeta')

const AutorespConfigsResponseSchemaSchema = z
  .object({
    data: z.array(AutorespConfigSchemaSchema).openapi({ title: 'Data' }),
    meta: MessagingPaginationMetaSchema,
  })
  .openapi({
    title: 'AutorespConfigsResponseSchema',
    description: 'List of Auto-Response Settings',
    required: ['data', 'meta'],
  })
  .openapi('AutorespConfigsResponseSchema')

const RegionInformationSchema = z
  .object({
    region_type: z
      .enum(['country_code', 'rate_center', 'state', 'location'])
      .exactOptional()
      .openapi({ example: 'country_code' }),
    region_name: z.string().exactOptional().openapi({ example: 'US' }),
  })
  .openapi({ example: { region_type: 'country_code', region_name: 'US' }, required: [] })
  .openapi('RegionInformation')

const CostInformationSchema = z
  .object({
    upfront_cost: z.string().exactOptional().openapi({ example: '3.21' }),
    monthly_cost: z.string().exactOptional().openapi({ example: '6.54' }),
    currency: z
      .string()
      .exactOptional()
      .openapi({ description: 'The ISO 4217 code for the currency.', example: 'USD' }),
  })
  .openapi({
    example: { upfront_cost: '3.21', monthly_cost: '6.54', currency: 'USD' },
    required: [],
  })
  .openapi('CostInformation')

const FeatureSchema = z
  .object({ name: z.string().exactOptional().openapi({ example: 'sms' }) })
  .openapi({ example: { name: 'sms' }, required: [] })
  .openapi('Feature')

const AvailablePhoneNumberSchema = z
  .object({
    record_type: z
      .literal('available_phone_number')
      .exactOptional()
      .openapi({ example: 'available_phone_number' }),
    phone_number: z.string().exactOptional().openapi({ example: '+19705555098' }),
    vanity_format: z.string().exactOptional(),
    best_effort: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'Specifies whether the phone number is an exact match based on the search criteria or not.',
        example: false,
      }),
    quickship: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'Specifies whether the phone number can receive calls immediately after purchase or not.',
        example: true,
      }),
    reservable: z
      .boolean()
      .exactOptional()
      .openapi({
        description: 'Specifies whether the phone number can be reserved before purchase or not.',
        example: true,
      }),
    region_information: z.array(RegionInformationSchema).exactOptional(),
    cost_information: CostInformationSchema.exactOptional(),
    features: z.array(FeatureSchema).exactOptional(),
  })
  .openapi({
    example: {
      record_type: 'available_phone_number',
      phone_number: '+19705555098',
      vanity_format: '',
      best_effort: false,
      quickship: true,
      reservable: true,
      region_information: [{ region_type: 'country_code', region_name: 'US' }],
      cost_information: { upfront_cost: '3.21', monthly_cost: '6.54', currency: 'USD' },
      features: [{ name: 'sms' }, { name: 'voice' }],
    },
    required: [],
  })
  .openapi('AvailablePhoneNumber')

const AvailablePhoneNumberBlockSchema = z
  .object({
    record_type: z
      .literal('available_phone_number_block')
      .exactOptional()
      .openapi({ example: 'available_phone_number_block' }),
    phone_number: z.string().exactOptional().openapi({ example: '+19705555000' }),
    range: z.int().exactOptional().openapi({ example: 10 }),
    region_information: z.array(RegionInformationSchema).exactOptional(),
    cost_information: CostInformationSchema.exactOptional(),
    features: z.array(FeatureSchema).exactOptional(),
  })
  .openapi({
    example: {
      record_type: 'available_phone_number_block',
      phone_number: '+19705555000',
      range: 10,
      region_information: [{ region_type: 'country_code', region_name: 'US' }],
      cost_information: { upfront_cost: '3.21', monthly_cost: '6.54', currency: 'USD' },
      features: [{ name: 'sms' }, { name: 'voice' }],
    },
    required: [],
  })
  .openapi('AvailablePhoneNumberBlock')

const AvailablePhoneNumbersMetadataSchema = z
  .object({
    total_results: z.int().exactOptional().openapi({ example: 1 }),
    best_effort_results: z.int().exactOptional().openapi({ example: 0 }),
  })
  .openapi({ example: { total_results: 100, best_effort_results: 50 }, required: [] })
  .openapi('AvailablePhoneNumbersMetadata')

const AvailableServiceSchema = z
  .enum([
    'cloud_vpn',
    'private_wireless_gateway',
    'tailscale_subnet_router',
    'virtual_cross_connect',
  ])
  .openapi({ title: 'Available service' })
  .openapi('AvailableService')

const AvatarTypeSchema = z
  .enum(['stock', 'custom'])
  .openapi({
    description:
      'Whether the avatar is provided by Telnyx or was uploaded by the authenticated organization.',
  })
  .openapi('AvatarType')

const AvatarContentTypeSchema = z
  .enum(['image/jpeg', 'image/png', 'image/webp'])
  .openapi({ description: 'MIME type of a custom avatar image.' })
  .openapi('AvatarContentType')

const AvatarSchema = z
  .strictObject({
    id: AvatarIdSchema,
    name: z
      .string()
      .min(1)
      .max(255)
      .openapi({ description: 'Customer-facing avatar name.', example: 'Customer portrait' }),
    provider: z
      .literal('telnyx')
      .openapi({
        description: 'Avatar provider. The first release supports Telnyx avatars.',
        example: 'telnyx',
      }),
    avatar_type: AvatarTypeSchema,
    hosted: z
      .literal(true)
      .openapi({
        description: 'Indicates that avatar rendering runs on Telnyx-operated infrastructure.',
        example: true,
      }),
    image_url: z
      .url()
      .regex(/^https:\/\//)
      .openapi({
        description:
          'HTTPS image URL suitable for an avatar selection thumbnail. If the URL expires, list or retrieve the avatar again to refresh it.',
        example: 'https://example.com/avatar.png',
      }),
    image_url_expires_at: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description: 'Expiration time of `image_url`. Omitted when the URL does not expire.',
        example: '2026-10-13T15:00:00Z',
      }),
    suggested_voice_id: z
      .string()
      .min(0)
      .max(255)
      .exactOptional()
      .openapi({
        readOnly: true,
        description:
          "Optional recommended Telnyx text-to-speech voice for this avatar. An omitted field or empty string means no recommendation is available. Custom avatars have no suggested voice. It is informational and selecting the avatar does not automatically change the AI Assistant's configured voice.",
        example: 'Telnyx.Ultra.db6b0ed5-d5d3-463d-ae85-518a07d3c2b4',
      }),
    content_type: AvatarContentTypeSchema.exactOptional(),
    size_bytes: z
      .int()
      .min(1)
      .max(10485760)
      .exactOptional()
      .openapi({ description: 'Size of a custom avatar image in bytes.', example: 248512 }),
    width_px: z
      .int()
      .min(256)
      .max(8192)
      .exactOptional()
      .openapi({ description: 'Decoded width of a custom avatar image.', example: 1920 }),
    height_px: z
      .int()
      .min(256)
      .max(8192)
      .exactOptional()
      .openapi({ description: 'Decoded height of a custom avatar image.', example: 1080 }),
    created_at: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description: 'Time when the custom avatar was created.',
        example: '2026-10-13T14:00:00Z',
      }),
    updated_at: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description: 'Time when the custom avatar was last updated.',
        example: '2026-10-13T14:00:00Z',
      }),
  })
  .openapi({ required: ['id', 'name', 'provider', 'avatar_type', 'hosted', 'image_url'] })
  .openapi('Avatar')

const AvatarErrorSourceSchema = z
  .looseObject({
    pointer: z
      .string()
      .exactOptional()
      .openapi({ description: 'Location of the invalid request value.', example: '/image_file' }),
  })
  .openapi({ required: [] })
  .openapi('AvatarErrorSource')

const AvatarErrorMetaSchema = z
  .looseObject({
    url: z
      .url()
      .openapi({
        description: 'Link to the Telnyx error-code documentation.',
        example: 'https://developers.telnyx.com/docs/overview/errors/10027',
      }),
  })
  .openapi({ required: ['url'] })
  .openapi('AvatarErrorMeta')

const AvatarErrorSchema = z
  .looseObject({
    code: z.string().openapi({ description: 'Telnyx error code.', example: '10015' }),
    title: z
      .string()
      .openapi({ description: 'Short description of the error.', example: 'Bad Request' }),
    detail: z
      .string()
      .openapi({
        description: 'Human-readable details about the error.',
        example: 'The request failed because it was not well-formed.',
      }),
    source: AvatarErrorSourceSchema.exactOptional(),
    meta: AvatarErrorMetaSchema,
  })
  .openapi({ required: ['code', 'title', 'detail', 'meta'] })
  .openapi('AvatarError')

const AvatarErrorResponseSchema = z
  .object({ errors: z.array(AvatarErrorSchema).min(1) })
  .openapi({ required: ['errors'] })
  .openapi('AvatarErrorResponse')

const AvatarListMetaSchema = z
  .object({
    total_pages: z
      .int()
      .min(0)
      .openapi({ description: 'Total number of pages for the current filters.', example: 1 }),
    total_results: z
      .int()
      .min(0)
      .openapi({ description: 'Total number of matching avatars.', example: 1 }),
    page_number: z.int().min(1).openapi({ description: 'Current page number.', example: 1 }),
    page_size: z
      .int()
      .min(1)
      .max(100)
      .openapi({ description: 'Maximum number of avatars returned on each page.', example: 20 }),
  })
  .openapi({ required: ['total_pages', 'total_results', 'page_number', 'page_size'] })
  .openapi('AvatarListMeta')

const AvatarListResponseSchema = z
  .strictObject({ data: z.array(AvatarSchema), meta: AvatarListMetaSchema })
  .openapi({ required: ['data', 'meta'] })
  .openapi('AvatarListResponse')

const AvatarResponseSchema = z
  .strictObject({ data: AvatarSchema })
  .openapi({ required: ['data'] })
  .openapi('AvatarResponse')

