const AzureProviderParamsSchema = z
  .object({
    language_code: z
      .string()
      .default('en-US')
      .exactOptional()
      .openapi({ description: 'Language code (e.g. `en-US`).' }),
    output_format: z
      .string()
      .default('audio-24khz-160kbitrate-mono-mp3')
      .exactOptional()
      .openapi({ description: 'Azure audio output format.' }),
    text_type: z
      .enum(['text', 'ssml'])
      .default('text')
      .exactOptional()
      .openapi({ description: 'Input text type. Use `ssml` for SSML-formatted input.' }),
    api_key: z
      .string()
      .exactOptional()
      .openapi({
        description: 'Custom Azure API key. If not provided, the default Telnyx key is used.',
      }),
    region: z
      .string()
      .exactOptional()
      .openapi({ description: 'Azure region (e.g. `eastus`, `westeurope`).' }),
    deployment_id: z
      .string()
      .exactOptional()
      .openapi({ description: 'Custom Azure deployment ID.' }),
    effect: z.string().exactOptional().openapi({ description: 'Azure audio effect to apply.' }),
    gender: z.string().exactOptional().openapi({ description: 'Voice gender preference.' }),
  })
  .openapi({ description: 'Azure Cognitive Services provider-specific parameters.', required: [] })
  .openapi('AzureProviderParams')

const BackgroundTaskStatusSchema = z
  .enum(['queued', 'processing', 'success', 'failure', 'partial_success'])
