const BpoAuthorizationSchema = z
  .object({
    record_type: z
      .literal('bpo_authorization')
      .openapi({
        description: 'Always `bpo_authorization`.',
        example: 'bpo_authorization',
        readOnly: true,
      }),
    bpo_enterprise_id: z
      .uuid()
      .openapi({
        description: "The authorized BPO account's enterprise id.",
        example: '4a6192a4-573d-446d-b3ce-aff9117272a6',
      }),
    status: z
      .enum(['pending', 'approved', 'rejected'])
      .openapi({
        description:
          "Review state of this authorization. `pending` when the authorization is first added, or when you send a different `loa_document_id` for this BPO in `bpo_authorizations` (uploading a document alone changes nothing). Approving the DIR approves its pending authorizations; an admin can also approve or reject one on its own. Only an `approved` authorization adds the BPO to this DIR's authorized callers in the branded calling registry.",
        example: 'pending',
      }),
    loa_document_id: z
      .uuid()
      .openapi({
        description:
          'Id of the signed Letter of Authorization document submitted for this BPO. Send it back unchanged in `bpo_authorizations` when updating the DIR to keep this authorization and its review state.',
        example: '2a7e8337-e803-4057-a4ae-26c40eb0bc6c',
      }),
    rejection_reason: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description: 'Why the authorization was rejected. `null` unless `status` is `rejected`.',
        example: 'Letter of Authorization is unsigned',
      }),
  })
  .openapi({
    description: 'A single authorization of a BPO (Business Process Outsourcer) account on a DIR.',
    required: ['record_type', 'bpo_enterprise_id', 'status', 'loa_document_id'],
  })
  .openapi('BpoAuthorization')

const BpoAuthorizationInputSchema = z
  .object({
    bpo_enterprise_id: z
      .uuid()
      .openapi({
        description:
          'Enterprise id of an approved BPO (Business Process Outsourcer) account on your organization to authorize for this DIR.',
        example: '4a6192a4-573d-446d-b3ce-aff9117272a6',
      }),
    loa_document_id: z
      .uuid()
      .openapi({
        description:
          'Id of the signed Letter of Authorization document (uploaded via the Telnyx Documents API) in which the Brand Owner authorizes this BPO.',
        example: '2a7e8337-e803-4057-a4ae-26c40eb0bc6c',
      }),
  })
  .openapi({
    description:
      'One authorization to include when creating or updating a DIR: an approved BPO (Business Process Outsourcer) account plus the signed Letter of Authorization the Brand Owner granted it.',
    required: ['bpo_enterprise_id', 'loa_document_id'],
  })
  .openapi('BpoAuthorizationInput')

