const ClauseSchema = z
  .object({
    attribute: z
      .string()
      .openapi({ title: 'Attribute', description: 'Attribute name from the routing context' }),
    operator: OperatorSchema.openapi({ description: 'Match operator' }),
    values: z.array(z.string()).min(1).openapi({ title: 'Values' }),
  })
  .openapi({
    required: ['attribute', 'operator', 'values'],
    title: 'Clause',
    description:
      "A single attribute/operator/values check.\n\nA clause matches when the routing context's value for ``attribute``\nsatisfies ``operator`` against any of ``values``.",
  })
  .openapi('Clause')

