const CreateAssistantRequestSchema: z.ZodType<CreateAssistantRequestType> = z
  .object({
    name: z.string(),
    model: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'ID of the model to use when `external_llm` is not set. You can use the [Get models API](https://developers.telnyx.com/api-reference/openai-chat/get-available-models-openai-compatible) to see available models. If `external_llm` is provided, the assistant uses `external_llm` instead of this field. If neither `model` nor `external_llm` is provided, Telnyx applies the default model.',
      }),
    instructions: z
      .string()
      .openapi({
        description:
          'System instructions for the assistant. These may be templated with [dynamic variables](https://developers.telnyx.com/docs/inference/ai-assistants/dynamic-variables)',
      }),
    tools: AssistantToolsSchema.exactOptional().openapi({
      description:
        'Deprecated for new integrations. Inline tool definitions available to the assistant. Prefer `tool_ids` to attach shared tools created with the AI Tools endpoints.',
    }),
    mcp_servers: z
      .array(AssistantMCPServerSchema)
      .default([])
      .exactOptional()
      .openapi({
        description:
          'MCP servers attached to the assistant. Create MCP servers with `/ai/mcp_servers`, then reference them by `id` here.',
      }),
    a2a_agents: z
      .array(AssistantA2AAgentSchema)
      .default([])
      .exactOptional()
      .openapi({
        description:
          "A2A agents this assistant can delegate to. Tools are not stored here: at the start of every conversation each agent's card is fetched and one tool is derived per skill the card advertises, named `a2a_<name>_<skill_id>`. The following limits are not enforced when the assistant is saved, and anything past them is dropped when the conversation starts: 64 agents per assistant, 64 skills per card, 128 derived tools per assistant, and a 6 second budget for all card fetches combined. An agent whose card cannot be fetched costs the assistant that capability for the conversation; it does not fail the call.",
      }),
    tool_ids: z
      .array(z.string())
      .exactOptional()
      .openapi({
        title: 'Ids of shared tools',
        description:
          'IDs of shared tools to attach to the assistant. New integrations should prefer `tool_ids` over inline `tools`.',
      }),
    description: z.string().exactOptional(),
    greeting: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Text that the assistant will use to start the conversation. This may be templated with [dynamic variables](https://developers.telnyx.com/docs/inference/ai-assistants/dynamic-variables). Use an empty string to have the assistant wait for the user to speak first. Use the special value `<assistant-speaks-first-with-model-generated-message>` to have the assistant generate the greeting based on the system instructions.',
      }),
    llm_api_key_ref: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "This is only needed when using third-party inference providers selected by `model`. The `identifier` for an integration secret [/v2/integration_secrets](https://developers.telnyx.com/api-reference/integration-secrets/create-a-secret) that refers to your LLM provider's API key. For bring-your-own endpoint authentication, use `external_llm.llm_api_key_ref` instead. Warning: Free plans are unlikely to work with this integration.",
      }),
    external_llm: ExternalLLMReqSchema.exactOptional(),
    fallback_config: FallbackConfigReqSchema.exactOptional(),
    voice_settings: InferenceEmbeddingVoiceSettingsSchema.exactOptional(),
    avatar_settings: z
      .union([AvatarSettingsRequestSchema, z.null().nullable()])
      .exactOptional()
      .openapi({
        description:
          '**Beta:** Optional avatar configuration for supported realtime browser conversations. Omit or set to `null` to create the assistant without an avatar.',
      }),
    transcription: TranscriptionSettingsSchema.exactOptional(),
    telephony_settings: TelephonySettingsSchema.exactOptional(),
    messaging_settings: MessagingSettingsSchema.exactOptional(),
    enabled_features: z.array(EnabledFeaturesSchema).exactOptional(),
    insight_settings: InsightSettingsSchema.exactOptional(),
    privacy_settings: PrivacySettingsSchema.exactOptional(),
    dynamic_variables_webhook_url: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'If `dynamic_variables_webhook_url` is set, Telnyx sends a POST request to this URL at the start of the conversation to resolve dynamic variables. **Gotcha:** the webhook response must wrap variables under a top-level `dynamic_variables` object, e.g. `{"dynamic_variables": {"customer_name": "Jane"}}`. Returning a flat object will be ignored and variables will fall back to their defaults. See the [dynamic variables guide](https://developers.telnyx.com/docs/inference/ai-assistants/dynamic-variables) for the full request/response format and timeout behavior.',
      }),
    dynamic_variables_webhook_timeout_ms: z
      .int()
      .min(1)
      .max(10000)
      .default(1500)
      .exactOptional()
      .openapi({
        description:
          'Timeout in milliseconds for the dynamic variables webhook. Must be between 1 and 10000 ms. If the webhook does not respond within this timeout, the call proceeds with default values. See the [dynamic variables guide](https://developers.telnyx.com/docs/inference/ai-assistants/dynamic-variables).',
      }),
    dynamic_variables: z
      .looseObject({})
      .exactOptional()
      .openapi({ description: 'Map of dynamic variables and their default values' }),
    widget_settings: WidgetSettingsSchema.exactOptional(),
    interruption_settings: InferenceEmbeddingInterruptionSettingsSchema.exactOptional(),
    integrations: z
      .array(AssistantIntegrationSchema)
      .default([])
      .exactOptional()
      .openapi({
        description:
          "Connected integrations attached to the assistant. The catalog of available integrations is at `/ai/integrations`; the user's connected integrations are at `/ai/integrations/connections`. Each item references a catalog integration by `integration_id`.",
      }),
    observability_settings: ObservabilityReqSchema.exactOptional(),
    tags: z
      .array(z.string())
      .default([])
      .exactOptional()
      .openapi({
        description:
          'Tags associated with the assistant. Tags can also be managed with the assistant tag endpoints.',
      }),
    post_conversation_settings: PostConversationSettingsReqSchema.exactOptional(),
    delegation_settings: DelegationSettingsSchema.exactOptional(),
    websocket_settings: WebsocketSettingsSchema.exactOptional(),
    conversation_flow: ConversationFlowReqSchema.exactOptional(),
  })
  .openapi({ required: ['name', 'instructions'], title: 'CreateAssistantRequest' })
  .openapi('CreateAssistantRequest')

const CreateAssistantTestRequestSchema = z
  .object({
    name: z
      .string()
      .min(1)
      .max(255)
      .openapi({
        title: 'Name',
        description:
          'A descriptive name for the assistant test. This will be used to identify the test in the UI and reports.',
        example: 'Customer Support Bot Test',
      }),
    description: z
      .string()
      .max(1000)
      .exactOptional()
      .openapi({
        title: 'Description',
        description:
          "Optional detailed description of what this test evaluates and its purpose. Helps team members understand the test's objectives.",
      }),
    telnyx_conversation_channel: TelnyxConversationChannelSchema.default('web_chat')
      .exactOptional()
      .openapi({
        description:
          'The communication channel through which the test will be conducted. Determines how the assistant will receive and respond to test messages.',
        example: 'web_chat',
      }),
    destination: z
      .string()
      .min(1)
      .openapi({
        title: 'Destination',
        description:
          'The target destination for the test conversation. Format depends on the channel: phone number for SMS/voice, webhook URL for web chat, etc.',
        example: '+15551234567',
      }),
    max_duration_seconds: z
      .int()
      .min(1)
      .max(3600)
      .exactOptional()
      .openapi({
        title: 'Max Duration Seconds',
        description:
          'Maximum duration in seconds that the test conversation should run before timing out. If not specified, uses system default timeout.',
      }),
    test_suite: z
      .string()
      .max(100)
      .exactOptional()
      .openapi({
        title: 'Test Suite',
        description:
          'Optional test suite name to group related tests together. Useful for organizing tests by feature, team, or release cycle.',
      }),
    instructions: z
      .string()
      .min(1)
      .max(5000)
      .openapi({
        title: 'Instructions',
        description:
          'Detailed instructions that define the test scenario and what the assistant should accomplish. This guides the test execution and evaluation.',
        example:
          'Act as a frustrated customer who received a damaged product. Ask for a refund and escalate if not satisfied with the initial response.',
      }),
    rubric: z
      .array(
        z
          .strictObject({
            name: z
              .string()
              .openapi({
                description:
                  'Label for the evaluation criterion, e.g., Empathy, Accuracy, Clarity.',
              }),
            criteria: z
              .string()
              .openapi({
                description:
                  'Specific guidance on how to assess the assistant’s performance for this rubric item.',
              }),
          })
          .openapi({ required: ['name', 'criteria'] }),
      )
      .min(1)
      .openapi({
        title: 'Rubric',
        description:
          "Evaluation criteria used to assess the assistant's performance. Each rubric item contains a name and specific criteria for evaluation.",
        example: [
          { criteria: 'Assistant responds within 30 seconds', name: 'Response Time' },
          { criteria: 'Provides correct product information', name: 'Accuracy' },
        ],
      }),
  })
  .openapi({
    required: ['name', 'destination', 'instructions', 'rubric'],
    title: 'CreateAssistantTestRequest',
    description:
      'Request model for creating a new assistant test.\n\nThis model defines all the required and optional parameters needed to create\na comprehensive test for an AI assistant, including test configuration,\nevaluation criteria, and scheduling options.',
  })
  .openapi('CreateAssistantTestRequest')

