const CreateMessageRequestSchema = z
  .object({
    from: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Sending address (+E.164 formatted phone number, alphanumeric sender ID, or short code).\n\n**Required if sending with a phone number, short code, or alphanumeric sender ID.**\n',
        'x-format': 'address',
      }),
    messaging_profile_id: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Unique identifier for a messaging profile.\n\n**Required if sending via number pool or with an alphanumeric sender ID.**\n',
      }),
    to: ToNumberSchema,
    text: z
      .string()
      .exactOptional()
      .openapi({
        description: 'Message body (i.e., content) as a non-empty string.\n\n**Required for SMS**',
      }),
    subject: z.string().exactOptional().openapi({ description: 'Subject of multimedia message' }),
    media_urls: z
      .array(z.url())
      .exactOptional()
      .openapi({
        description:
          'A list of media URLs. The total media size must be less than 1 MB.\n\n**Required for MMS**',
      }),
    webhook_url: z
      .url()
      .exactOptional()
      .openapi({ description: 'The URL where webhooks related to this message will be sent.' }),
    webhook_failover_url: z
      .url()
      .exactOptional()
      .openapi({
        description:
          'The failover URL where webhooks related to this message will be sent if sending to the primary URL fails.',
      }),
    use_profile_webhooks: z
      .boolean()
      .default(true)
      .exactOptional()
      .openapi({
        description:
          'If the profile this number is associated with has webhooks, use them for delivery notifications. If webhooks are also specified on the message itself, they will be attempted first, then those on the profile.',
      }),
    type: z
      .enum(['SMS', 'MMS'])
      .exactOptional()
      .openapi({ description: 'The protocol for sending the message, either SMS or MMS.' }),
    auto_detect: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        description:
          'Automatically detect if an SMS message is unusually long and exceeds a recommended limit of message parts.',
      }),
    send_at: z.iso
      .datetime({ offset: true })
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'ISO 8601 formatted date indicating when to send the message - accurate up till a minute.',
      }),
    encoding: z
      .enum(['auto', 'gsm7', 'ucs2'])
      .default('auto')
      .exactOptional()
      .openapi({
        description:
          "Encoding to use for the message. `auto` (default) uses smart encoding to automatically select the most efficient encoding. `gsm7` forces GSM-7 encoding (returns 400 if message contains characters that cannot be encoded). `ucs2` forces UCS-2 encoding and disables smart encoding. When set, this overrides the messaging profile's `smart_encoding` setting.",
      }),
  })
  .openapi({
    required: ['to'],
    example: {
      from: '+18445550001',
      messaging_profile_id: 'abc85f64-5717-4562-b3fc-2c9600000000',
      to: '+18445550001',
      text: 'Hello, World!',
      subject: 'From Telnyx!',
      media_urls: ['http://example.com'],
      webhook_url: 'http://example.com/webhooks',
      webhook_failover_url: 'https://backup.example.com/hooks',
      use_profile_webhooks: true,
      type: 'MMS',
    },
  })
  .openapi('CreateMessageRequest')

