const CreateOutboundVoiceProfileRequestSchema = z
  .object({
    name: z
      .string()
      .min(3)
      .openapi({
        description: 'A user-supplied name to help with organization.',
        example: 'office',
      }),
    traffic_type: TrafficTypeSchema.exactOptional(),
    service_plan: ServicePlanSchema.exactOptional(),
    concurrent_call_limit: z
      .int()
      .nullable()
      .exactOptional()
      .openapi({
        description: 'Must be no more than your global concurrent call limit. Null means no limit.',
        example: 10,
      }),
    enabled: z
      .boolean()
      .default(true)
      .exactOptional()
      .openapi({
        description:
          'Specifies whether the outbound voice profile can be used. Disabled profiles will result in outbound calls being blocked for the associated Connections.',
        example: true,
      }),
    tags: z
      .array(z.string())
      .exactOptional()
      .openapi({ example: ['office-profile'] }),
    usage_payment_method: UsagePaymentMethodSchema.exactOptional(),
    whitelisted_destinations: z
      .array(z.string())
      .default(['US', 'CA'])
      .exactOptional()
      .openapi({
        description:
          'The list of destinations you want to be able to call using this outbound voice profile formatted in alpha2.',
        example: ['US', 'BR', 'AU'],
      }),
    max_destination_rate: z
      .number()
      .exactOptional()
      .openapi({
        description:
          'Maximum rate (price per minute) for a Destination to be allowed when making outbound calls.',
      }),
    daily_spend_limit: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The maximum amount of usage charges, in USD, you want Telnyx to allow on this outbound voice profile in a day before disallowing new calls.',
        example: '100.00',
      }),
    daily_spend_limit_enabled: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        description:
          'Specifies whether to enforce the daily_spend_limit on this outbound voice profile.',
        example: true,
      }),
    call_recording: OutboundCallRecordingSchema.exactOptional(),
    billing_group_id: z
      .uuid()
      .nullable()
      .default(null)
      .exactOptional()
      .openapi({
        description:
          'The ID of the billing group associated with the outbound proflile. Defaults to null (for no group assigned).',
        example: '6a09cdc3-8948-47f0-aa62-74ac943d6c58',
      }),
    calling_window: z
      .object({
        start_time: z
          .string()
          .regex(
            /^(?:[01]\d|2[0-3]):[0-5]\d(?::[0-5]\d(?:\.\d+)?)?(?:Z|[+-](?:[01]\d|2[0-3]):[0-5]\d)?$/,
          )
          .exactOptional()
          .openapi({
            format: 'time',
            description:
              'The UTC time of day (in HH:MM format, 24-hour clock) when calls are allowed to start.',
            example: '08:00:00.00Z',
          }),
        end_time: z
          .string()
          .regex(
            /^(?:[01]\d|2[0-3]):[0-5]\d(?::[0-5]\d(?:\.\d+)?)?(?:Z|[+-](?:[01]\d|2[0-3]):[0-5]\d)?$/,
          )
          .exactOptional()
          .openapi({
            format: 'time',
            description:
              'The UTC time of day (in HH:MM format, 24-hour clock) when calls are no longer allowed to start.',
            example: '20:00:00.00Z',
          }),
        calls_per_cld: z
          .int()
          .min(0)
          .exactOptional()
          .openapi({
            description:
              'The maximum number of calls that can be initiated to a single called party (CLD) within the calling window. A null value means no limit.',
            example: 5,
          }),
      })
      .exactOptional()
      .openapi({
        description:
          'Specifies the time window and call limits for calls made using this outbound voice profile. Note that all times are UTC in 24-hour clock time.',
        example: { start_time: '08:00:00.00Z', end_time: '20:00:00.00Z', calls_per_cld: 5 },
        required: [],
      }),
  })
  .openapi({
    title: 'Outbound Voice Profile',
    required: ['name'],
    example: {
      name: 'office',
      traffic_type: 'conversational',
      service_plan: 'global',
      concurrent_call_limit: 10,
      enabled: true,
      tags: ['office-profile'],
      usage_payment_method: 'rate-deck',
      whitelisted_destinations: ['US', 'BR', 'AU'],
      max_destination_rate: 10,
      daily_spend_limit: '100.00',
      daily_spend_limit_enabled: true,
      billing_group_id: '6a09cdc3-8948-47f0-aa62-74ac943d6c58',
      calling_window: { start_time: '08:00:00.00Z', end_time: '20:00:00.00Z', calls_per_cld: 5 },
    },
  })
  .openapi('CreateOutboundVoiceProfileRequest')

