const PronunciationDictAliasItemSchema = z
  .strictObject({
    text: z
      .string()
      .min(1)
      .max(200)
      .openapi({
        description:
          'The text to match in the input. Case-insensitive matching is used during synthesis.',
        example: 'Telnyx',
      }),
    type: z.literal('alias').openapi({ description: 'The item type.', example: 'alias' }),
    alias: z
      .string()
      .min(1)
      .max(500)
      .openapi({
        description: 'The replacement text that will be spoken instead.',
        example: 'tel-nicks',
      }),
  })
  .openapi({
    description:
      'An alias pronunciation item. When the `text` value is found in input, it is replaced with the `alias` before speech synthesis.',
    required: ['text', 'type', 'alias'],
  })
  .openapi('PronunciationDictAliasItem')

const PronunciationDictPhonemeItemSchema = z
  .strictObject({
    text: z
      .string()
      .min(1)
      .max(200)
      .openapi({
        description:
          'The text to match in the input. Case-insensitive matching is used during synthesis.',
        example: 'Telnyx',
      }),
    type: z.literal('phoneme').openapi({ description: 'The item type.', example: 'phoneme' }),
    phoneme: z
      .string()
      .min(1)
      .max(500)
      .openapi({
        description: 'The phoneme notation representing the desired pronunciation.',
        example: 'ˈtɛl.nɪks',
      }),
    alphabet: z
      .literal('ipa')
      .openapi({
        description: 'The phonetic alphabet used for the phoneme notation.',
        example: 'ipa',
      }),
  })
  .openapi({
    description:
      'A phoneme pronunciation item. When the `text` value is found in input, it is pronounced using the specified IPA phoneme notation.',
    required: ['text', 'type', 'phoneme', 'alphabet'],
  })
  .openapi('PronunciationDictPhonemeItem')

const PronunciationDictItemSchema = z
  .discriminatedUnion('type', [
    PronunciationDictAliasItemSchema,
    PronunciationDictPhonemeItemSchema,
  ])
  .openapi({
    description:
      "A single pronunciation dictionary item. Use type 'alias' to replace matched text with a spoken alias, or type 'phoneme' to specify exact pronunciation using IPA notation.",
    discriminator: {
      propertyName: 'type',
      mapping: {
        alias: '#/components/schemas/PronunciationDictAliasItem',
        phoneme: '#/components/schemas/PronunciationDictPhonemeItem',
      },
    },
  })
  .openapi('PronunciationDictItem')

