const CreateSpendLimitWithAmountSchema = z
  .strictObject({
    product: z
      .string()
      .openapi({
        description: 'Product to limit, as returned in `product` by the list operation.',
        example: 'inference',
      }),
    period: SpendLimitPeriodSchema.exactOptional(),
    credential_id: z
      .string()
      .min(1)
      .max(255)
      .nullable()
      .exactOptional()
      .openapi({
        description:
          "Optional. Identifier of one API key as recorded on usage, never the key's secret: the limit then applies to that key only. Absent or `null` sets the total limit. A blank value, or one with control characters, is refused; it never means the total limit. An API key limit always has an `amount`.",
        example: 'KEY0192F3A1B2C3D4E5F6A7B8C9D0E1F2',
      }),
    amount: z
      .number()
      .min(0)
      .openapi({
        description: 'Limit in USD. `0` blocks at the first cent of spend.',
        example: 100,
      }),
    unlimited: z
      .literal(false)
      .exactOptional()
      .openapi({
        description: 'Optional; only `false` is allowed together with `amount`.',
        example: false,
      }),
    reason: z
      .string()
      .max(500)
      .exactOptional()
      .openapi({
        description: 'Why the limit is set or changed, kept for audit.',
        example: 'Team budget',
      }),
  })
  .openapi({ title: 'Amount', description: 'A limit in USD.', required: ['product', 'amount'] })
  .openapi('CreateSpendLimitWithAmount')

const CreateSpendLimitUnlimitedSchema = z
  .strictObject({
    product: z
      .string()
      .openapi({
        description: 'Product to limit, as returned in `product` by the list operation.',
        example: 'inference',
      }),
    period: SpendLimitPeriodSchema.exactOptional(),
    unlimited: z
      .literal(true)
      .openapi({ description: '`true`: explicitly no cap.', example: true }),
    reason: z
      .string()
      .max(500)
      .exactOptional()
      .openapi({
        description: 'Why the limit is set or changed, kept for audit.',
        example: 'Team budget',
      }),
  })
  .openapi({
    title: 'Unlimited',
    description: 'Explicitly no cap. Not available for API key limits.',
    required: ['product', 'unlimited'],
  })
  .openapi('CreateSpendLimitUnlimited')

const CreateSpendLimitRequestSchema = z
  .xor([CreateSpendLimitWithAmountSchema, CreateSpendLimitUnlimitedSchema])
  .openapi({ description: 'Send exactly one of `amount` and `unlimited: true`.' })
  .openapi('CreateSpendLimitRequest')

