const DedicatedIpDeleteRequestSchema = z
  .object({
    force: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        description:
          'Set together with `drain: true` to release the last IP in a pool. Either flag alone has no effect.',
      }),
    drain: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        description:
          'Set together with `force: true` to release the last IP in a pool. Acknowledges that mail routed to the emptied pool is held until the pool has a sendable IP again.',
      }),
    reason: z
      .string()
      .exactOptional()
      .openapi({ description: 'Free-text reason recorded with the release.' }),
  })
  .openapi({
    description: 'Optional release options. The same fields are accepted as query parameters.',
    required: [],
  })
  .openapi('DedicatedIpDeleteRequest')

