const DialConferenceParticipantRequestSchema = z
  .object({
    Beep: z
      .enum(['true', 'false', 'onEnter', 'onExit'])
      .exactOptional()
      .openapi({
        description:
          'Whether to play a notification beep to the conference when the participant enters and exits.',
        example: 'onExit',
      }),
    StatusCallback: z
      .string()
      .exactOptional()
      .openapi({
        description: 'URL destination for Telnyx to send status callback events to for the call.',
        example: 'https://www.example.com/callback',
      }),
    StatusCallbackMethod: z
      .enum(['GET', 'POST'])
      .exactOptional()
      .openapi({ description: 'HTTP request type used for `StatusCallback`.', example: 'GET' }),
    StatusCallbackEvent: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "The changes to the call's state that should generate a call to `StatusCallback`. Can be: `initiated`, `ringing`, `answered`, and `completed`. Separate multiple values with a space. The default value is `completed`.",
        example: 'answered completed',
      }),
    To: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The phone number of the called party. Phone numbers are formatted with a `+` and country code.',
        example: '+16175551212',
      }),
    From: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The phone number of the party that initiated the call. Phone numbers are formatted with a `+` and country code.',
        example: '+16175551212',
      }),
    Timeout: z
      .int()
      .exactOptional()
      .openapi({
        description:
          'The number of seconds that we should allow the phone to ring before assuming there is no answer. Can be an integer between 5 and 120, inclusive. The default value is 30.',
        example: 30,
        'x-stainless-param': 'timeout_seconds',
      }),
    Muted: z
      .boolean()
      .exactOptional()
      .openapi({ description: 'Whether the participant should be muted.', example: true }),
    StartConferenceOnEnter: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'Whether to start the conference when the participant enters. Defaults to `true`.',
        example: false,
      }),
    EndConferenceOnExit: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'Whether to end the conference when the participant leaves. Defaults to `false`.',
        example: true,
      }),
    Label: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'A unique label for the participant that will be added to the conference. The label can be used to reference the participant for updates via the TeXML REST API.',
        example: 'customer',
      }),
    EarlyMedia: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        description:
          'Whether participant shall be bridged to conference before the participant answers (from early media if available). Defaults to `false`.',
        example: true,
      }),
    ConferenceStatusCallback: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The URL the conference callbacks will be sent to.',
        example: 'https://example.com/conference_status_callback',
      }),
    ConferenceStatusCallbackMethod: z
      .enum(['GET', 'POST'])
      .exactOptional()
      .openapi({
        description: 'HTTP request type used for `ConferenceStatusCallback`. Defaults to `POST`.',
        example: 'GET',
      }),
    ConferenceStatusCallbackEvent: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "The changes to the conference's state that should generate a call to `ConferenceStatusCallback`. Can be: `start`, `end`, `join` and `leave`. Separate multiple values with a space. By default no callbacks are sent.",
        example: 'start end join leave',
      }),
    WaitUrl: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The URL to call for an audio file to play while the participant is waiting for the conference to start.',
        example: 'https://www.example.com/wait_music.mp3',
      }),
    MaxParticipants: z
      .int()
      .exactOptional()
      .openapi({
        description:
          'The maximum number of participants in the conference. Can be a positive integer from 2 to 800. The default value is 250.',
        example: 30,
      }),
    Coaching: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'Whether the participant is coaching another call. When `true`, `CallSidToCoach` has to be given.',
        example: false,
      }),
    CallSidToCoach: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The SID of the participant who is being coached. The participant being coached is the only participant who can hear the participant who is coaching.',
        example: 'v3:9X2vxPDFY2RHSJ1EdMS0RHRksMTg7ldNxdjWbVr9zBjbGjGsSe-aiQ',
      }),
    CallerId: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'To be used as the caller id name (SIP From Display Name) presented to the destination (`To` number). The string should have a maximum of 128 characters, containing only letters, numbers, spaces, and `-_~!.+` special characters. If ommited, the display name will be the same as the number in the `From` field.',
        example: 'Info',
      }),
    TimeLimit: z
      .int()
      .exactOptional()
      .openapi({ description: 'The maximum duration of the call in seconds.', example: 30 }),
    MachineDetection: z
      .enum(['Enable', 'DetectMessageEnd'])
      .exactOptional()
      .openapi({
        description:
          'Whether to detect if a human or an answering machine picked up the call. Use `Enable` if you would like to ne notified as soon as the called party is identified. Use `DetectMessageEnd`, if you would like to leave a message on an answering machine.',
        example: 'Enable',
      }),
    MachineDetectionTimeout: z
      .int()
      .exactOptional()
      .openapi({
        description:
          'How long answering machine detection should go on for before sending an `Unknown` result. Given in milliseconds.',
        example: 1000,
      }),
    MachineDetectionSpeechThreshold: z
      .int()
      .default(3500)
      .exactOptional()
      .openapi({
        description:
          'Maximum threshold of a human greeting. If greeting longer than this value, considered machine. Ignored when `premium` detection is used.',
        example: 2000,
      }),
    MachineDetectionSpeechEndThreshold: z
      .int()
      .default(800)
      .exactOptional()
      .openapi({
        description:
          'Silence duration threshold after a greeting message or voice for it be considered human. Ignored when `premium` detection is used.',
        example: 2000,
      }),
    MachineDetectionSilenceTimeout: z
      .int()
      .default(3500)
      .exactOptional()
      .openapi({
        description:
          'If initial silence duration is greater than this value, consider it a machine. Ignored when `premium` detection is used.',
        example: 2000,
      }),
    MachineDetectionBeepProfile: z
      .enum(['both', 'freq_only'])
      .default('both')
      .exactOptional()
      .openapi({
        description:
          'Selects which detectors must validate a beep. `both` requires the amplitude and frequency detectors to agree. `freq_only` uses the frequency detector alone, for beeps whose volume is too unsteady for the default profile. Only used when MachineDetection is enabled.',
        example: 'freq_only',
      }),
    MachineDetectionBeepMinFrequency: z
      .int32()
      .min(200)
      .max(4000)
      .exactOptional()
      .openapi({
        description:
          'Lowest frequency, in Hz, that a tone must reach to be treated as a beep. Raising it above 480 excludes North American ringback (440 + 480 Hz), which can otherwise be reported as a beep when the `freq_only` profile is in use. Only used when MachineDetection is enabled.',
        example: 550,
      }),
    MachineDetectionBeepMaxFrequency: z
      .int32()
      .min(200)
      .max(4000)
      .exactOptional()
      .openapi({
        description:
          'Highest frequency, in Hz, that a tone can reach and still be treated as a beep. Only used when MachineDetection is enabled.',
        example: 2000,
      }),
    MachineDetectionBeepMinToneDuration: z
      .int32()
      .min(50)
      .max(5000)
      .exactOptional()
      .openapi({
        description:
          'Shortest tone, in milliseconds, that can be treated as a beep. Raising it rejects brief tones such as call-progress blips. Only used when MachineDetection is enabled.',
        example: 300,
      }),
    MachineDetectionBeepSpectralConfirmation: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'When enabled, a candidate beep must pass an additional spectral check before it is reported. Only used when MachineDetection is enabled.',
        example: true,
      }),
    MachineDetectionBeepSpectralWindow: z
      .int32()
      .min(20)
      .max(1000)
      .exactOptional()
      .openapi({
        description:
          'Length of the spectral confirmation window, in milliseconds. Only used when MachineDetection is enabled.',
        example: 100,
      }),
    MachineDetectionBeepSpectralMinPurity: z
      .number()
      .min(0)
      .max(1)
      .exactOptional()
      .openapi({
        description:
          'Minimum spectral purity, from 0 to 1, for a tone to be treated as a beep. Raising it rejects mixed tones such as ringback, which combines two frequencies. Only used when MachineDetection is enabled.',
        example: 0.8,
      }),
    MachineDetectionBeepSpectralRejectFaxCng: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'When enabled, the fax CNG tone is rejected rather than reported as a beep. Only used when MachineDetection is enabled.',
        example: true,
      }),
    AmdStatusCallback: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The URL the result of answering machine detection will be sent to.',
        example: 'https://www.example.com/amd_result',
      }),
    AmdStatusCallbackMethod: z
      .enum(['GET', 'POST'])
      .exactOptional()
      .openapi({
        description: 'HTTP request type used for `AmdStatusCallback`. Defaults to `POST`.',
        example: 'GET',
      }),
    ApplicationSid: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "The SID of the TeXML application that will handle the new participant's call. Required unless joining an existing conference by its ConferenceSid.",
        example: '1846572522338780702',
      }),
    CancelPlaybackOnMachineDetection: z
      .boolean()
      .default(true)
      .exactOptional()
      .openapi({
        description:
          'Whether to cancel ongoing playback on `machine` detection. Defaults to `true`.',
        example: false,
      }),
    CancelPlaybackOnDetectMessageEnd: z
      .boolean()
      .default(true)
      .exactOptional()
      .openapi({
        description:
          'Whether to cancel ongoing playback on `greeting ended` detection. Defaults to `true`.',
        example: false,
      }),
    PreferredCodecs: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The list of comma-separated codecs to be offered on a call.',
        example: 'PCMA,PCMU',
      }),
    Record: z
      .boolean()
      .exactOptional()
      .openapi({
        description: "Whether to record the entire participant's call leg. Defaults to `false`.",
        example: false,
      }),
    RecordingChannels: z
      .enum(['mono', 'dual'])
      .exactOptional()
      .openapi({
        description: 'The number of channels in the final recording. Defaults to `mono`.',
        example: 'dual',
      }),
    RecordingStatusCallback: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The URL the recording callbacks will be sent to.',
        example: 'https://example.com/recording_status_callback',
      }),
    RecordingStatusCallbackMethod: z
      .enum(['GET', 'POST'])
      .exactOptional()
      .openapi({
        description: 'HTTP request type used for `RecordingStatusCallback`. Defaults to `POST`.',
        example: 'GET',
      }),
    RecordingStatusCallbackEvent: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "The changes to the recording's state that should generate a call to `RecoridngStatusCallback`. Can be: `in-progress`, `completed` and `absent`. Separate multiple values with a space. Defaults to `completed`.",
        example: 'in-progress completed absent',
      }),
    RecordingTrack: z
      .enum(['inbound', 'outbound', 'both'])
      .exactOptional()
      .openapi({
        description: 'The audio track to record for the call. The default is `both`.',
        example: 'inbound',
      }),
    SipAuthPassword: z
      .string()
      .exactOptional()
      .openapi({ description: 'The password to use for SIP authentication.', example: '1234' }),
    SipAuthUsername: z
      .string()
      .exactOptional()
      .openapi({ description: 'The username to use for SIP authentication.', example: 'user' }),
    Trim: z
      .enum(['trim-silence', 'do-not-trim'])
      .exactOptional()
      .openapi({
        description:
          'Whether to trim any leading and trailing silence from the recording. Defaults to `trim-silence`.',
        example: 'trim-silence',
      }),
    ConferenceRecord: z
      .enum(['true', 'false', 'record-from-start', 'do-not-record'])
      .exactOptional()
      .openapi({
        description:
          'Whether to record the conference the participant is joining. Defualts to `do-not-record`. The boolean values `true` and `false` are synonymous with `record-from-start` and `do-not-record` respectively.',
        example: 'record-from-start',
      }),
    ConferenceRecordingStatusCallback: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The URL the conference recording callbacks will be sent to.',
        example: 'https://example.com/conference_recording_status_callback',
      }),
    ConferenceRecordingStatusCallbackMethod: z
      .enum(['GET', 'POST'])
      .exactOptional()
      .openapi({
        description:
          'HTTP request type used for `ConferenceRecordingStatusCallback`. Defaults to `POST`.',
        example: 'GET',
      }),
    ConferenceRecordingStatusCallbackEvent: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "The changes to the conference recording's state that should generate a call to `RecoridngStatusCallback`. Can be: `in-progress`, `completed` and `absent`. Separate multiple values with a space. Defaults to `completed`. `failed` and `absent` are synonymous.",
        example: 'in-progress completed failed absent',
      }),
    ConferenceRecordingTimeout: z
      .int()
      .default(0)
      .exactOptional()
      .openapi({
        description:
          'The number of seconds that Telnyx will wait for the recording to be stopped if silence is detected. The timer only starts when the speech is detected. Please note that the transcription is used to detect silence and the related charge will be applied. The minimum value is 0. The default value is 0 (infinite)',
        example: 5,
      }),
    ConferenceTrim: z
      .enum(['trim-silence', 'do-not-trim'])
      .exactOptional()
      .openapi({
        description:
          'Whether to trim any leading and trailing silence from the conference recording. Defaults to `trim-silence`.',
        example: 'trim-silence',
      }),
    CustomHeaders: z
      .array(
        z
          .object({
            name: z.string().openapi({ description: 'The name of the custom header' }),
            value: z.string().openapi({ description: 'The value of the custom header' }),
          })
          .openapi({ required: ['name', 'value'] }),
      )
      .exactOptional()
      .openapi({
        description:
          "Custom HTTP headers to be sent with the call. Each header should be an object with 'name' and 'value' properties.",
        example: [{ name: 'X-Custom-Header', value: 'custom-value' }],
      }),
  })
  .openapi({
    title: 'Create Conference Participant Request',
    example: { To: '+12065550100', From: '+12065550200' },
    required: [],
  })
  .openapi('DialConferenceParticipantRequest')

const DialMetricSchema = z
  .object({
    record_type: z.literal('dial_metric').exactOptional().openapi({ example: 'dial_metric' }),
    region: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Region where the dials were handled. Current values are `us`, `eu`, `australia`, `middle_east`, `canada` and `india`. New values can be added, so clients must tolerate values not listed here. Buckets of different regions are separate records.',
        example: 'us',
      }),
    start_time: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description: 'Start of the bucket (inclusive), UTC.',
        example: '2026-09-29T12:00:00.000Z',
      }),
    end_time: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description:
          'End of the bucket (exclusive), UTC. Five seconds, one minute or one hour after `start_time`, depending on `granularity`.',
        example: '2026-09-29T13:00:00.000Z',
      }),
    dials: z
      .object({
        total: z
          .int()
          .min(0)
          .exactOptional()
          .openapi({
            description:
              'All dial attempts, rejected ones included: accepted plus every rejected count.',
            example: 85600,
          }),
        accepted: z
          .int()
          .min(0)
          .exactOptional()
          .openapi({
            description: 'Dial attempts that were not rejected by a limit.',
            example: 85240,
          }),
        rejected: z
          .object({
            dps_limit: z
              .int()
              .min(0)
              .exactOptional()
              .openapi({ description: 'Rejected by the dials-per-second limit.', example: 360 }),
            hourly_limit: z
              .int()
              .min(0)
              .exactOptional()
              .openapi({ description: 'Rejected by an hourly limit.', example: 0 }),
            daily_limit: z
              .int()
              .min(0)
              .exactOptional()
              .openapi({ description: 'Rejected by a daily limit.', example: 0 }),
          })
          .exactOptional()
          .openapi({ description: 'Dial attempts rejected by a limit.', required: [] }),
      })
      .exactOptional()
      .openapi({ description: 'Dial attempt counts in the bucket.', required: [] }),
    average_dps: z
      .number()
      .exactOptional()
      .openapi({
        description:
          '`dials.total` divided by the bucket duration in seconds, rounded to 4 decimal places. Counts every dial attempt, rejected ones included.',
        example: 23.7778,
      }),
    peak_dps: z
      .number()
      .exactOptional()
      .openapi({
        description:
          'Dials per second, rounded to 4 decimal places, in the busiest 5-second window of the bucket, summed across all call-processing nodes of the region. Counts every dial attempt, rejected ones included, so `peak_dps` above `dps_limit` is expected when dials were rejected. For `granularity=second` it equals `average_dps`.',
        example: 104,
      }),
    dps_limit: z
      .int()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'DPS limit in force during the busiest 5-second window, so it compares directly with `peak_dps`. `null` means unlimited. Enforcement near the limit is approximate; `dials.rejected.dps_limit` is the authoritative signal that the limit was reached.',
        example: 100,
      }),
  })
  .openapi({
    title: 'Dial Metrics Bucket',
    description:
      'Dial counts and rates for one region in one time bucket. One record per region per bucket.',
    required: [],
  })
  .openapi('DialMetric')

const DialMetricsListMetaSchema = z
  .object({
    granularity: z
      .enum(['second', 'minute', 'hour'])
      .exactOptional()
      .openapi({ description: 'Echo of the requested granularity.', example: 'hour' }),
    start_time: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description:
          'Start of the range actually used: the requested `start_time`, or the start of the retention window when the requested value is older.',
        example: '2026-09-29T12:00:00.000Z',
      }),
    end_time: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description: 'Echo of the requested `end_time`.',
        example: '2026-09-29T14:00:00.000Z',
      }),
    cursors: z
      .object({
        after: z
          .string()
          .exactOptional()
          .openapi({
            description: 'Opaque cursor for the next page. Pass it as `page[after]`.',
            example: 'MTc5MDY4NjgwMDpldQ',
          }),
        before: z
          .string()
          .exactOptional()
          .openapi({
            description:
              'Present only on an empty page for a cursor that matched nothing: echoes that cursor.',
            example: 'MTc5MDY4MzIwMDp1cw',
          }),
      })
      .exactOptional()
      .openapi({
        description:
          'Empty on the last page. When `page[after]` matched no records, the page is empty and `after` and `before` both echo the given cursor.',
        required: [],
      }),
    next: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "Path to the next page, repeating this request's parameters. Absent on the last page.",
        example:
          '/v2/dial_metrics?end_time=2026-09-29T14%3A00%3A00.000Z&granularity=hour&page%5Bafter%5D=MTc5MDY4NjgwMDpldQ&page%5Blimit%5D=2&sort=-start_time&start_time=2026-09-29T12%3A00%3A00.000Z',
      }),
    sort: z
      .enum(['-start_time', 'start_time'])
      .exactOptional()
      .openapi({ description: 'Echo of the applied sort order.', example: '-start_time' }),
  })
  .openapi({ title: 'Dial Metrics List Meta', required: [] })
  .openapi('DialMetricsListMeta')

