const DirStatusSchema = z
  .enum([
    'draft',
    'submitted',
    'in_review',
    'verified',
    'rejected',
    'unsuccessful',
    'suspended',
    'expired',
    'infringement_claimed',
    'permanently_rejected',
    'delete_requested',
  ])
  .openapi({
    description:
      'DIR lifecycle status.\n- `draft` - newly created; editable; not yet submitted.\n- `submitted` / `in_review` - Telnyx is reviewing.\n- `verified` - approved; phone numbers may be attached.\n- `rejected` - Telnyx rejected this submission; `rejection_reasons` is populated; customer can edit and resubmit.\n- `unsuccessful` - system-side error during processing; customer can edit and resubmit.\n- `suspended` - temporarily disabled (e.g. by an active infringement claim).\n- `expired` - verification expired; customer must resubmit.\n- `infringement_claimed` - a trademark/impersonation claim is open against this DIR.\n- `permanently_rejected` - terminal; cannot be resubmitted.\n- `delete_requested` - you have requested deletion; the DIR still exists and Telnyx is completing the removal (de-registration and cleanup). A verified DIR keeps serving its branded identity, and keeps billing, until the removal finishes.',
  })
  .openapi('DirStatus')

const RejectionReasonSchema = z
  .object({
    code: z.string().exactOptional().openapi({ example: 'documentation_incomplete' }),
    title: z.string().exactOptional().openapi({ example: 'Documentation incomplete' }),
    detail: z
      .string()
      .exactOptional()
      .openapi({ example: 'Provided documents do not establish business identity.' }),
    message: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Customer-visible free-text comment from the Telnyx vetting team. Only the first entry of `rejection_reasons` carries this; the rest are `null`.',
        example: 'Please re-upload a clearer scan of the certificate.',
      }),
  })
  .openapi({ required: [] })
  .openapi('RejectionReason')

const DirSchema = z
  .object({
    id: z
      .uuid()
      .exactOptional()
      .openapi({ example: '16635d38-75a6-4481-82e8-69af60e05011', readOnly: true }),
    enterprise_id: z
      .uuid()
      .exactOptional()
      .openapi({ example: '4a6192a4-573d-446d-b3ce-aff9117272a6' }),
    display_name: z.string().exactOptional().openapi({ example: 'Acme Plumbing' }),
    reselling: z.boolean().exactOptional().openapi({ example: false }),
    certify_brand_is_accurate: z.boolean().exactOptional().openapi({ example: true }),
    certify_no_shaft_content: z.boolean().exactOptional().openapi({ example: true }),
    certify_ip_ownership: z.boolean().exactOptional().openapi({ example: true }),
    authorizer_name: z.string().nullable().exactOptional().openapi({ example: 'Sam Owner' }),
    authorizer_email: z
      .email()
      .nullable()
      .exactOptional()
      .openapi({ example: 'sam@acmeplumbing.example.com' }),
    logo_url: z
      .url()
      .nullable()
      .exactOptional()
      .openapi({ example: 'https://acmeplumbing.example.com/logo-256.bmp' }),
    call_reasons: z.array(CallReasonSchema).exactOptional(),
    documents: z.array(DocumentSchema).nullable().exactOptional(),
    status: DirStatusSchema.exactOptional(),
    rejection_reasons: z
      .array(RejectionReasonSchema)
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Populated when `status` is `rejected`; cleared on `/submit` or successful approval.',
      }),
    rejected_at: z.iso
      .datetime({ offset: true })
      .nullable()
      .exactOptional()
      .openapi({ readOnly: true }),
    created_at: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({ example: '2026-04-26T18:06:51.940749Z', readOnly: true }),
    updated_at: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({ example: '2026-04-26T18:09:24.785211Z', readOnly: true }),
    submitted_at: z.iso
      .datetime({ offset: true })
      .nullable()
      .exactOptional()
      .openapi({ example: '2026-04-26T18:07:03.716411Z', readOnly: true }),
    verified_at: z.iso
      .datetime({ offset: true })
      .nullable()
      .exactOptional()
      .openapi({ example: '2026-04-26T18:07:29.537926Z', readOnly: true }),
    expiring_at: z.iso
      .datetime({ offset: true })
      .nullable()
      .exactOptional()
      .openapi({ example: '2027-04-26T18:07:29.537981Z', readOnly: true }),
    delete_requested_at: z.iso
      .datetime({ offset: true })
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'When deletion was requested. Set once the DIR enters `delete_requested`; `null` otherwise.',
        example: '2026-04-27T09:12:44.201820Z',
        readOnly: true,
      }),
    webhook_url: z
      .url()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          "`https://` URL that receives webhook notifications for this DIR's compliance-review outcomes. `null` when not subscribed.",
        example: 'https://acmehealthcare.example.com/webhooks/branded-calling',
      }),
  })
  .openapi({ required: [] })
  .openapi('Dir')

const DirCommentCreateRequestSchema = z
