const EmailDomainDKIMRotationSchema = z
  .object({
    record_type: z.literal('email_domain_dkim_rotation'),
    domain_id: z.uuid(),
    domain: z.string(),
    dkim: z
      .object({
        id: z.uuid(),
        selector: z.string(),
        algorithm: z.literal('rsa-sha256'),
        key_length: z.literal(2048),
        version: z
          .int()
          .min(1)
          .openapi({ description: 'Monotonically increasing per-domain key version.' }),
        status: z.literal('active'),
        activated_at: z.iso.datetime({ offset: true }).nullable().exactOptional(),
      })
      .openapi({
        description: 'The new active DKIM key.',
        required: ['id', 'selector', 'algorithm', 'key_length', 'version', 'status'],
      }),
    previous_dkim_key: z
      .object({
        id: z.uuid(),
        selector: z.string(),
        version: z.int(),
        status: z.enum(['retiring', 'revoked']),
      })
      .nullable()
      .openapi({
        description:
          'The retired previous key, or null when the domain had no active key before rotation. Retained in a `retiring` state so it can be revoked after the DNS propagation grace period.\n',
        required: ['id', 'selector', 'version', 'status'],
      }),
    old_selector_retained: z
      .boolean()
      .openapi({
        description:
          'False for this service: one selector is fixed per domain, so rotation replaces the TXT value at the existing _domainkey host. There is no dual-selector overlap; publish the replacement TXT promptly because signing switches immediately.',
      }),
    dns_records: z
      .array(DNSRecordSchema)
      .openapi({
        description:
          "The DKIM DNS records the customer must publish, carrying the new key's TXT value with verification reset to pending.\n",
      }),
  })
  .openapi({
    description:
      "Result of rotating a domain's DKIM key. The new key is active and signing switches to it immediately; the previous key is retired to a `retiring` state (retained, not revoked) so it can be revoked after the DNS propagation grace period. Selectors are fixed, so the DKIM DNS record's TXT value is replaced in place at the shared `<selector>._domainkey.<domain>` host — `old_selector_retained` is false and the returned dns_records carry the new value the customer must publish promptly.\n",
    required: [
      'record_type',
      'domain_id',
      'domain',
      'dkim',
      'previous_dkim_key',
      'old_selector_retained',
      'dns_records',
    ],
    example: {
      record_type: 'email_domain_dkim_rotation',
      domain_id: '123e4567-e89b-12d3-a456-426614174002',
      domain: 'example.com',
      dkim: {
        id: '123e4567-e89b-12d3-a456-42661417400a',
        selector: 'telnyx1',
        algorithm: 'rsa-sha256',
        key_length: 2048,
        version: 2,
        status: 'active',
        activated_at: '2026-09-11T12:00:00Z',
      },
      previous_dkim_key: {
        id: '123e4567-e89b-12d3-a456-426614174009',
        selector: 'telnyx1',
        version: 1,
        status: 'retiring',
      },
      old_selector_retained: false,
      dns_records: [
        {
          id: '123e4567-e89b-12d3-a456-42661417400b',
          purpose: 'dkim',
          record_type: 'TXT',
          host: 'telnyx1._domainkey.example.com',
          value: 'v=DKIM1; k=rsa; p=MIIBIjANBgkqh...',
          actual_value: null,
          priority: null,
          required: true,
          status: 'pending',
        },
      ],
    },
  })
  .openapi('EmailDomainDKIMRotation')

const EmailDomainDKIMRotationResponseSchema = z
  .object({ data: EmailDomainDKIMRotationSchema })
  .openapi({ required: ['data'] })
  .openapi('EmailDomainDKIMRotationResponse')

