const EnqueueRequestSchema = z
  .object({
    queue_name: z
      .string()
      .openapi({
        description:
          "The name of the queue the call should be put in. If a queue with a given name doesn't exist yet it will be created.",
        example: 'tier_1_support',
      }),
    client_state: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Use this field to add state to every subsequent webhook. It must be a valid Base-64 encoded string.',
        example: 'aGF2ZSBhIG5pY2UgZGF5ID1d',
      }),
    command_id: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Use this field to avoid duplicate commands. Telnyx will ignore any command with the same `command_id` for the same `call_control_id`.',
        example: '891510ac-f3e4-11e8-af5b-de00688a4901',
      }),
    max_wait_time_secs: z
      .int()
      .exactOptional()
      .openapi({
        description: 'The number of seconds after which the call will be removed from the queue.',
        example: 600,
      }),
    max_size: z
      .int()
      .default(100)
      .exactOptional()
      .openapi({
        description:
          "The maximum number of calls allowed in the queue at a given time. Can't be modified for an existing queue.",
        example: 200,
      }),
    keep_after_hangup: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        description:
          'If set to true, the call will remain in the queue after hangup. In this case bridging to such call will fail with necessary information needed to re-establish the call.',
        example: true,
      }),
  })
  .openapi({
    title: 'Enqueue Request',
    required: ['queue_name'],
    example: {
      queue_name: 'support',
      max_wait_time_secs: 600,
      max_size: 20,
      client_state: 'aGF2ZSBhIG5pY2UgZGF5ID1d',
      command_id: '891510ac-f3e4-11e8-af5b-de00688a4901',
    },
  })
  .openapi('EnqueueRequest')

const OrganizationContactSchema = z
