const EnterpriseCreateSchema = z
  .object({
    legal_name: z
      .string()
      .min(3)
      .max(64)
      .openapi({
        example: 'Acme Plumbing LLC',
        description:
          "Your business's full registered legal name, exactly as it appears on your incorporation or tax documents, 3 to 64 characters.",
      }),
    organization_type: z
      .enum(['commercial', 'government', 'non_profit'])
      .openapi({
        example: 'commercial',
        description:
          'Organization category for vetting purposes:\n- `commercial` - for-profit business entities (LLC, corp, partnership, sole proprietorship). Most callers fall here.\n- `government` - federal/state/local government bodies.\n- `non_profit` - registered 501(c)(3)/equivalent (incl. educational institutions, charities, religious organisations).',
      }),
    country_code: z
      .string()
      .openapi({
        description: 'ISO 3166-1 alpha-2 country code. Currently `US` and `CA` are supported.',
        example: 'US',
      }),
    role_type: z
      .enum(['enterprise', 'bpo'])
      .default('enterprise')
      .exactOptional()
      .openapi({
        description:
          "`enterprise` for an organization registering its own DIRs (the default, and the right choice when the calls display your own brand). `bpo` for a Business Process Outsourcer: a call center that places calls on behalf of other enterprises and displays their brand. A `bpo` enterprise describes the call center itself and cannot own a DIR. Each client the call center calls for gets its own `enterprise` in the same account, with the client's DIR under it; that DIR is then linked to the `bpo` enterprise through `bpo_authorizations`. Fixed at creation.",
        example: 'enterprise',
      }),
    website: z
      .url()
      .max(255)
      .openapi({
        example: 'https://acmeplumbing.example.com',
        description:
          "Your business's public website address, including https://. Leave blank if your business has no website.",
      }),
    fein: z
      .string()
      .openapi({
        description:
          'US Federal Employer Identification Number (`NN-NNNNNNN`) or Canadian equivalent.',
        example: '12-3456789',
      }),
    industry: z
      .enum([
        'accounting',
        'finance',
        'billing',
        'collections',
        'business',
        'charity',
        'nonprofit',
        'communications',
        'telecom',
        'customer service',
        'support',
        'delivery',
        'shipping',
        'logistics',
        'education',
        'financial',
        'banking',
        'government',
        'public',
        'healthcare',
        'health',
        'pharmacy',
        'medical',
        'insurance',
        'legal',
        'law',
        'notifications',
        'scheduling',
        'real estate',
        'property',
        'retail',
        'ecommerce',
        'sales',
        'marketing',
        'software',
        'technology',
        'tech',
        'media',
        'surveys',
        'market research',
        'travel',
        'hospitality',
        'hotel',
      ])
      .openapi({
        description:
          'The industry your business operates in. Choose the closest match from the list; if your value is not accepted, pick the nearest category.',
        example: 'technology',
      }),
    number_of_employees: z
      .enum(['1-10', '11-50', '51-200', '201-500', '501-2000', '2001-10000', '10001+'])
      .openapi({
        example: '51-200',
        description:
          'Approximate headcount range. Used for vetting heuristics; pick the bucket that contains your current employee count.',
      }),
    organization_legal_type: z
      .enum(['corporation', 'llc', 'partnership', 'nonprofit', 'other'])
      .openapi({
        example: 'llc',
        description:
          'Legal-entity form. Pick the form that matches your incorporation documents:\n- `corporation` - C-corp or S-corp.\n- `llc` - limited liability company.\n- `partnership` - general/limited partnership.\n- `nonprofit` - non-profit corporation, charitable trust, or 501(c)(3)/equivalent.\n- `other` - anything else (sole proprietorships, government bodies, DBAs, etc.). You may be asked for additional documents during vetting.',
      }),
    doing_business_as: z
      .string()
      .max(255)
      .openapi({
        example: 'Acme Plumbing',
        description:
          'The trade name your business operates under if it is different from your legal name, also called a Doing Business As (DBA) name. Leave blank if you only use your legal name.',
      }),
    jurisdiction_of_incorporation: z
      .string()
      .max(255)
      .openapi({
        example: 'Delaware',
        description:
          'The state, province, or country where your business was legally incorporated, for example Delaware.',
      }),
    customer_reference: z
      .string()
      .max(255)
      .exactOptional()
      .openapi({
        description:
          'Your own label for this account. Enter any reference that helps you find it in your records. Telnyx does not use it during vetting.',
        example: 'internal-id-12345',
      }),
    primary_business_domain_sic_code: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'The 4-digit Standard Industrial Classification code for your main line of business, which tells us what industry you operate in. Look it up in the SIC code directory if you are unsure.',
      }),
    corporate_registration_number: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'The official number your company received when it was legally registered or incorporated (for example from your state or national business registry). It is on your certificate of incorporation.',
      }),
    professional_license_number: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'If your business operates under a professional license (for example legal, medical, or financial services), enter the license number issued by the licensing authority. Leave blank if it does not apply.',
      }),
    dun_bradstreet_number: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Your optional 9-digit D-U-N-S Number issued by Dun & Bradstreet, a unique identifier for your business. Leave blank if you do not have one.',
      }),
    organization_contact: OrganizationContactSchema,
    billing_contact: BillingContactSchema,
    organization_physical_address: PhysicalAddressSchema,
    billing_address: PhysicalAddressSchema,
  })
  .openapi({
    required: [
      'legal_name',
      'organization_type',
      'country_code',
      'website',
      'fein',
      'industry',
      'number_of_employees',
      'organization_legal_type',
      'doing_business_as',
      'jurisdiction_of_incorporation',
      'organization_contact',
      'billing_contact',
      'organization_physical_address',
      'billing_address',
    ],
  })
  .openapi('EnterpriseCreate')

