const HostedNumberOrderEventPayloadSchema = z
  .object({
    order_id: z
      .uuid()
      .exactOptional()
      .openapi({ description: 'The ID of the hosted number order.' }),
    order_status: z
      .enum([
        'pending',
        'provisioning',
        'successful',
        'failed',
        'deleted',
        'carrier_rejected',
        'compliance_review_failed',
        'incomplete_documentation',
        'incorrect_billing_information',
        'ineligible_carrier',
        'loa_file_invalid',
        'loa_file_successful',
      ])
      .exactOptional()
      .openapi({ description: 'Current status of the order.' }),
    profile_id: z
      .uuid()
      .exactOptional()
      .openapi({ description: 'The messaging profile associated with the order.' }),
    user_id: z
      .string()
      .exactOptional()
      .openapi({ description: 'The organization that owns the order.' }),
    numbers: z
      .array(
        z
          .object({
            value: z
              .string()
              .exactOptional()
              .openapi({ 'x-format': '+E.164', description: 'Phone number in +E.164 format.' }),
            status: z
              .enum([
                'deleted',
                'failed',
                'failed_activation',
                'failed_carrier_rejected',
                'failed_ineligible_carrier',
                'failed_number_already_hosted',
                'failed_number_not_found',
                'failed_ownership_verification',
                'failed_timeout',
                'ownership_successful',
                'pending',
                'provisioning',
                'successful',
              ])
              .exactOptional()
              .openapi({ description: 'Current status of this phone number within the order.' }),
          })
          .openapi({ required: [] }),
      )
      .exactOptional(),
    decision: z
      .enum(['pending', 'approved', 'rejected'])
      .exactOptional()
      .openapi({
        description:
          'Approval decision for the internal transfer. Defaults to `pending` for non-internal-transfer events.',
      }),
    approval_deadline: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .nullable()
      .exactOptional()
      .openapi({
        type: ['integer', 'null'],
        format: 'int64',
        description:
          'Unix timestamp (seconds) by which the losing organization must respond before auto-approval. Populated on internal-transfer events once an approval window has been issued.',
      }),
  })
