const MeetingSessionSchema = z
  .strictObject({
    id: z.string().openapi({ description: 'Unique identifier for the meeting session.' }),
    account_id: z.string().openapi({ description: 'Identifier of the owning account.' }),
    provider: z.string().openapi({ description: 'Provider handling the meeting session.' }),
    status: z
      .enum([
        'scheduled',
        'joining',
        'waiting_for_admission',
        'active',
        'leaving',
        'ended',
        'failed',
        'admission_denied',
      ])
      .openapi({
        description:
          'Lifecycle status. `waiting_for_admission` means the bot reached the meeting lobby and may require host approval. `active` means the bot entered the meeting/media path. `ended` alone does not prove attendance; use non-null `joined_at` as positive evidence that the session became active. `admission_denied` is reserved for an explicit provider denial, while cancellation or another termination can end a never-admitted session as `ended`.',
      }),
    status_detail: z
      .string()
      .nullable()
      .openapi({ description: 'Additional human-readable detail about the status, or null.' }),
    recording: z.boolean().openapi({ description: 'Whether the session is being recorded.' }),
    meeting_url: z.url().openapi({ description: 'The meeting URL the bot joins.' }),
    platform: z
      .enum(['zoom', 'google_meet', 'teams', 'webex', 'unknown'])
      .openapi({ description: 'Detected meeting platform.' }),
    bot_name: z.string().openapi({ description: 'Display name of the bot in the meeting.' }),
    config: MeetingSessionConfigSchema,
    avatar: z
      .xor([MeetingSessionAvatarSchema, z.null().nullable()])
      .openapi({
        description:
          "The assistant's avatar when the session was created with `assistant.avatar: true`, otherwise null.",
      }),
    avatar_state: z
      .union([
        z.literal('starting'),
        z.literal('connected'),
        z.literal('degraded'),
        z.literal('disconnected'),
        z.literal(null),
      ])
      .nullable()
      .openapi({
        description:
          "Current state of the avatar, or null if the session has no avatar. `starting` until the avatar's video is playing, then `connected`; `degraded` when the session has fallen back to voice-only (the `avatar.degraded` event carries the reason); `disconnected` when the avatar has ended.",
      }),
    avatar_state_changed_at: z.iso
      .datetime({ offset: true })
      .nullable()
      .openapi({ description: 'Timestamp of the last avatar state change, or null.' }),
    assistant: z
      .xor([MeetingSessionAssistantSchema, z.null().nullable()])
      .openapi({
        description: 'Assistant configuration if an assistant is attached, otherwise null.',
      }),
    assistant_state: z
      .union([
        z.literal('starting'),
        z.literal('connected'),
        z.literal('failed'),
        z.literal('ended'),
        z.literal(null),
      ])
      .nullable()
      .openapi({
        description: 'Current state of the assistant, or null if no assistant is attached.',
      }),
    assistant_state_changed_at: z.iso
      .datetime({ offset: true })
      .nullable()
      .openapi({ description: 'Timestamp of the last assistant state change, or null.' }),
    webhook_url: z
      .url()
      .nullable()
      .openapi({
        description: 'Webhook endpoint for session lifecycle callbacks, or null if not configured.',
      }),
    metadata: z
      .looseObject({})
      .openapi({ description: 'Arbitrary key-value metadata attached to the session.' }),
    failure_reason: z
      .string()
      .nullable()
      .openapi({ description: 'Human-readable failure reason if the session failed, or null.' }),
    created_at: z.iso
      .datetime({ offset: true })
      .openapi({ description: 'Timestamp when the session was created.' }),
    join_at: z.iso
      .datetime({ offset: true })
      .nullable()
      .openapi({ description: 'Scheduled join time, or null for immediate join.' }),
    joined_at: z.iso
      .datetime({ offset: true })
      .nullable()
      .openapi({
        description:
          'Timestamp when the session first became `active`, or null if it never became active. This remains positive admission evidence after terminal transitions.',
      }),
    ended_at: z.iso
      .datetime({ offset: true })
      .nullable()
      .openapi({ description: 'Timestamp when the session ended, or null if ongoing.' }),
    updated_at: z.iso
      .datetime({ offset: true })
      .openapi({ description: 'Timestamp of the last update to the session.' }),
  })
  .openapi({
    title: 'MeetingSession',
    description:
      'Represents a meeting session. All serializer fields are present and required; nullable fields use null when absent. No actor, provider-bot, idempotency, routing, key, or internal fields are exposed.',
    required: [
      'id',
      'account_id',
      'provider',
      'status',
      'status_detail',
      'recording',
      'meeting_url',
      'platform',
      'bot_name',
      'config',
      'avatar',
      'avatar_state',
      'avatar_state_changed_at',
      'assistant',
      'assistant_state',
      'assistant_state_changed_at',
      'webhook_url',
      'metadata',
      'failure_reason',
      'created_at',
      'join_at',
      'joined_at',
      'ended_at',
      'updated_at',
    ],
  })
  .openapi('MeetingSession')

