const ReplyEmailInboxMessageRequestSchema = z
  .union([
    z
      .unknown()
      .superRefine((val, ctx) => {
        if (typeof val === 'object' && val !== null && !Array.isArray(val)) {
          if (!Object.hasOwn(val, 'text')) {
            ctx.addIssue({ code: 'custom' })
          }
        }
      })
      .openapi({ required: ['text'] }),
    z
      .unknown()
      .superRefine((val, ctx) => {
        if (typeof val === 'object' && val !== null && !Array.isArray(val)) {
          if (!Object.hasOwn(val, 'html')) {
            ctx.addIssue({ code: 'custom' })
          }
        }
      })
      .openapi({ required: ['html'] }),
  ])
  .and(
    z
      .object({
        text: z
          .string()
          .regex(/\S/)
          .min(1)
          .exactOptional()
          .openapi({ description: 'Plain-text reply body.' }),
        html: z
          .string()
          .regex(/\S/)
          .min(1)
          .exactOptional()
          .openapi({ description: 'HTML reply body.' }),
      })
      .openapi({ required: [] }),
  )
  .openapi({
    description:
      'At least one of `text` or `html` must contain a non-whitespace body. Recipients are derived from the source message; caller-supplied `to`, `cc`, or `bcc` values are ignored.',
  })
  .openapi('ReplyEmailInboxMessageRequest')

