const SipRegistrationStatusSchema = z
  .object({
    connection_id: z
      .string()
      .exactOptional()
      .openapi({ description: 'Identifier of the connection associated with the credential.' }),
    connection_name: z
      .string()
      .exactOptional()
      .openapi({ description: 'Human-readable connection name.' }),
    credential_type: z
      .enum(['uac_external_credential', 'telephony_credential', 'sip_credential_connection'])
      .exactOptional()
      .openapi({ description: 'The credential type that was looked up.' }),
    credential_username: z
      .string()
      .exactOptional()
      .openapi({ description: 'SIP username used for the registration.' }),
    registered: z
      .boolean()
      .exactOptional()
      .openapi({ description: 'True if the endpoint is currently registered.' }),
    sip_registration_status: z
      .enum([
        'unregistering',
        'connection_disabled',
        'standby',
        'failed',
        'trying',
        'registered',
        'unknown',
      ])
      .exactOptional()
      .openapi({
        description: 'Human-readable registration status derived from the registrar state.',
      }),
    last_registration_response: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description: 'SIP response from the last registration attempt.',
        example: '200 OK',
      }),
    sip_registration_details: z
      .object({
        auth_retries: z
          .int()
          .exactOptional()
          .openapi({
            description:
              'Number of authentication retries on the last attempt (uac_external_credential).',
          }),
        expires: z
          .int()
          .exactOptional()
          .openapi({
            description:
              'When the current registration expires. The unit depends on `credential_type`: for `uac_external_credential` this is a Unix timestamp (seconds since epoch) of the next scheduled re-registration; for `telephony_credential` and `sip_credential_connection` this is the registration lifetime in seconds as negotiated with the registrar (the `Expires` value, defaulting to 3600 when the endpoint sends none).',
          }),
        uptime: z
          .int()
          .exactOptional()
          .openapi({
            description: 'Registration uptime reported by the registrar (uac_external_credential).',
          }),
        next_action_at: z
          .int()
          .exactOptional()
          .openapi({
            description:
              'Unix timestamp of the next scheduled registration action (uac_external_credential).',
          }),
        failures: z
          .int()
          .exactOptional()
          .openapi({
            description: 'Count of consecutive registration failures (uac_external_credential).',
          }),
        sip_uri_user_host: z
          .string()
          .exactOptional()
          .openapi({
            description: 'SIP URI user@host of the registered contact (uac_external_credential).',
          }),
        ua_ip: z
          .string()
          .exactOptional()
          .openapi({
            description:
              'IP address of the registered user agent (telephony_credential and sip_credential_connection).',
          }),
        ua_port: z
          .int()
          .exactOptional()
          .openapi({
            description:
              'Port of the registered user agent (telephony_credential and sip_credential_connection).',
          }),
        transport: z
          .string()
          .exactOptional()
          .openapi({
            description:
              'Transport used for the registration, e.g. UDP/TCP/TLS (telephony_credential and sip_credential_connection).',
          }),
        last_modified: z
          .string()
          .exactOptional()
          .openapi({
            description:
              'Timestamp when the registration was last modified (telephony_credential and sip_credential_connection).',
          }),
      })
      .exactOptional()
      .openapi({
        description:
          'Detailed registration information reported by the registrar. The populated fields depend on `credential_type`: UAC external credentials report `auth_retries`, `uptime`, `next_action_at`, `failures`, and `sip_uri_user_host`; telephony credentials and SIP credential connections report `ua_ip`, `ua_port`, `transport`, and `last_modified`. All types report `expires`, but its unit differs by `credential_type` — see that field.',
        required: [],
      }),
  })
  .openapi({ required: [] })
  .openapi('SipRegistrationStatus')

