const TelnyxQwen3TTSCloneSchema = z
  .object({
    audio_file: z
      .file()
      .openapi({
        type: 'string',
        format: 'binary',
        description:
          'Audio file to clone the voice from. Supported formats: WAV, MP3, FLAC, OGG, M4A. For best quality, provide 5–10 seconds of clear, uninterrupted speech. Maximum size: 20MB.',
      }),
    name: z.string().max(255).openapi({ description: 'Name for the voice clone.' }),
    language: z
      .string()
      .regex(/^([Aa]uto|[a-z]{2,3}(-[A-Za-z0-9]{2,8})*)$/)
      .openapi({ description: 'ISO 639-1 language code from the Qwen language set.' }),
    gender: z
      .enum(['male', 'female', 'neutral'])
      .openapi({ description: 'Gender of the voice clone.' }),
    ref_text: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Optional transcript of the audio file. Providing this improves clone quality.',
      }),
    label: z
      .string()
      .exactOptional()
      .openapi({ description: 'Optional custom label describing the voice style.' }),
    model_id: z
      .union([z.literal('Qwen3TTS'), z.literal(null)])
      .nullable()
      .exactOptional()
      .openapi({ description: 'TTS model identifier. Nullable/omittable — defaults to Qwen3TTS.' }),
    provider: z
      .enum(['telnyx', 'Telnyx'])
      .openapi({ description: 'Voice synthesis provider. Must be `telnyx`.' }),
  })
  .openapi({
    description: 'Upload-based voice clone using the Telnyx Qwen3TTS model (default).',
    required: ['audio_file', 'name', 'language', 'gender', 'provider'],
  })
  .openapi('TelnyxQwen3TTSClone')

