const UsageExportGuardrailEvaluationSchema = z
  .strictObject({
    id: z.string().regex(/^grd_[0-9a-f-]{36}$/),
    type: z.literal('guardrail.evaluation'),
    schema_version: z.literal(1),
    request_id: z.uuid(),
    created_at: z.iso.datetime({ offset: true }),
    token_group_id: z.uuid(),
    token_user_id: z.union([z.uuid(), z.null().nullable()]),
    token_key_id: z.uuid(),
    end_user_id: z.union([
      z
        .string()
        .regex(/^[^\u0000-\u001f\u007f]+$/)
        .min(1)
        .max(256),
      z.null().nullable(),
    ]),
    model: z
      .string()
      .regex(/^[^\u0000-\u001f\u007f]+$/)
      .min(1)
      .max(256),
    stage: z.enum(['prompt', 'response']),
    outcome: z.enum(['evaluated', 'flagged', 'blocked', 'unevaluated']),
    findings: z.array(GuardrailFindingSchema),
    evaluation_input_tokens: z.union([z.int().min(0), z.null().nullable()]),
    evaluation_output_tokens: z.union([z.int().min(0), z.null().nullable()]),
    metadata: RequestMetadataSchema,
  })
  .openapi({
    required: [
      'id',
      'type',
      'schema_version',
      'request_id',
      'created_at',
      'token_group_id',
      'token_user_id',
      'token_key_id',
      'end_user_id',
      'model',
      'stage',
      'outcome',
      'findings',
      'evaluation_input_tokens',
      'evaluation_output_tokens',
      'metadata',
    ],
  })
  .openapi('UsageExportGuardrailEvaluation')

const UsageExportInferenceRequestSchema = z
  .strictObject({
    id: z
      .string()
      .regex(/^req_[0-9a-f-]{36}_r[1-9][0-9]*$/)
      .openapi({ description: 'Deterministic: req_{request_id}_r{revision}. Deduplicate on id.' }),
    type: z.literal('inference.request'),
    schema_version: z.literal(1),
    request_id: z.uuid(),
    revision: z.int().min(1),
    supersedes: z
      .union([z.string().regex(/^req_[0-9a-f-]{36}_r[1-9][0-9]*$/), z.null().nullable()])
      .openapi({ description: 'Previous revision id; keep the highest revision per request_id.' }),
    timings: z
      .strictObject({
        admitted_at: z.iso.datetime({ offset: true }),
        first_attempt_at: z.union([z.iso.datetime({ offset: true }), z.null().nullable()]),
        completed_at: z.union([z.iso.datetime({ offset: true }), z.null().nullable()]),
        settled_at: z.iso.datetime({ offset: true }),
        gateway_duration_ms: z
          .union([z.int().min(0), z.null().nullable()])
          .openapi({
            description:
              'completed_at - admitted_at as recorded by the ledger; not time to first token.',
          }),
      })
      .openapi({
        required: [
          'admitted_at',
          'first_attempt_at',
          'completed_at',
          'settled_at',
          'gateway_duration_ms',
        ],
      }),
    token_group_id: z.uuid(),
    token_user_id: z.union([z.uuid(), z.null().nullable()]),
    token_key_id: z.uuid(),
    end_user_id: z.union([
      z
        .string()
        .regex(/^[^\u0000-\u001f\u007f]+$/)
        .min(1)
        .max(256),
      z.null().nullable(),
    ]),
    model: z
      .string()
      .regex(/^[^\u0000-\u001f\u007f]+$/)
      .min(1)
      .max(256),
    provider: z
      .string()
      .regex(/^[^\u0000-\u001f\u007f]+$/)
      .min(1)
      .max(256),
    provider_model: z
      .string()
      .regex(/^[^\u0000-\u001f\u007f]+$/)
      .min(1)
      .max(256),
    route_mode: z.enum(['managed', 'byok', 'cache']),
    protocol: z.enum(['openai', 'anthropic']),
    stream: z.boolean(),
    status: z.enum(['succeeded', 'failed', 'partial', 'unknown']),
    attempts: z.int().min(0),
    input_tokens: z.union([z.int().min(0), z.null().nullable()]),
    output_tokens: z.union([z.int().min(0), z.null().nullable()]),
    usage_source: z.union([
      z.enum(['provider', 'gateway_tokenizer', 'operator']),
      z.null().nullable(),
    ]),
    usage_status: z.enum(['known', 'unknown', 'reconciled']),
    cost: z.union([
      z
        .string()
        .regex(/^((0|[1-9][0-9]{0,8})\.[0-9]{6}|1000000000\.000000)$/)
        .openapi({
          description:
            'USD decimal string with exactly 6 places, 0 to 1000000000.000000 (the Money bound); enforcement basis, not invoice truth.',
        }),
      z.null().nullable(),
    ]),
    biller: z.enum(['telnyx', 'provider', 'none']),
    cache_hit: z.boolean(),
    provider_key_id: z.union([z.uuid(), z.null().nullable()]),
    configuration_version: z.int().min(1),
    rate_version: z
      .string()
      .regex(/^[^\u0000-\u001f\u007f]+$/)
      .min(1)
      .max(256),
    metadata: RequestMetadataSchema.openapi({
      description: 'Customer request tags captured at admission; {} when untagged.',
    }),
  })
  .openapi({
    required: [
      'id',
      'type',
      'schema_version',
      'request_id',
      'revision',
      'supersedes',
      'timings',
      'token_group_id',
      'token_user_id',
      'token_key_id',
      'end_user_id',
      'model',
      'provider',
      'provider_model',
      'route_mode',
      'protocol',
      'stream',
      'status',
      'attempts',
      'input_tokens',
      'output_tokens',
      'usage_source',
      'usage_status',
      'cost',
      'biller',
      'cache_hit',
      'provider_key_id',
      'configuration_version',
      'rate_version',
      'metadata',
    ],
  })
  .openapi('UsageExportInferenceRequest')

