const X402PaymentRequirementsSchema = z
  .object({
    x402Version: z
      .literal(2)
      .exactOptional()
      .openapi({ description: 'x402 protocol version. Currently always 2.' }),
    resource: z
      .object({
        url: z
          .string()
          .exactOptional()
          .openapi({ description: 'Canonical URL of the payment resource.' }),
        description: z
          .string()
          .exactOptional()
          .openapi({ description: 'Human-readable description of the payment.' }),
        mimeType: z.string().exactOptional().openapi({ description: 'MIME type of the resource.' }),
      })
      .exactOptional()
      .openapi({
        description: 'The resource being paid for. Included in the payment signature.',
        required: [],
      }),
    accepts: z
      .array(
        z
          .object({
            scheme: z
              .string()
              .exactOptional()
              .openapi({ description: 'Payment scheme (e.g. "exact").' }),
            network: z
              .string()
              .exactOptional()
              .openapi({
                description:
                  'Blockchain network identifier in CAIP-2 format (e.g. "eip155:8453" for Base).',
              }),
            amount: z
              .string()
              .exactOptional()
              .openapi({ description: "Amount in the token's smallest unit." }),
            asset: z
              .string()
              .exactOptional()
              .openapi({ description: 'Token contract address (e.g. USDC on Base).' }),
            payTo: z.string().exactOptional().openapi({ description: 'Recipient wallet address.' }),
            maxTimeoutSeconds: z
              .int()
              .exactOptional()
              .openapi({
                description: 'Maximum time in seconds before the payment authorization expires.',
              }),
            extra: z
              .object({
                quoteId: z.string().exactOptional(),
                facilitatorUrl: z.string().exactOptional(),
                name: z
                  .string()
                  .exactOptional()
                  .openapi({ description: 'EIP-712 domain name (e.g. "USD Coin").' }),
                version: z
                  .string()
                  .exactOptional()
                  .openapi({ description: 'EIP-712 domain version.' }),
              })
              .exactOptional()
              .openapi({
                description:
                  'Additional scheme-specific parameters including EIP-712 domain info and the facilitator URL.',
                required: [],
              }),
          })
          .openapi({ required: [] }),
      )
      .exactOptional()
      .openapi({
        description:
          'Accepted payment schemes. Currently only the `exact` EVM scheme is supported.',
      }),
  })
  .openapi({
    description:
      'x402 protocol v2 payment requirements. Contains all information needed to construct and sign a payment authorization.',
    required: [],
  })
  .openapi('X402PaymentRequirements')

