const TexmlCreateSiprecSessionRequestRequestBody = {
  description: 'Starts a SIPREC session.',
  content: {
    'application/x-www-form-urlencoded': {
      schema: z
        .object({
          ConnectorName: z
            .string()
            .exactOptional()
            .openapi({
              description: 'The name of the connector to use for the SIPREC session.',
              example: 'my_connector',
            }),
          Name: z
            .string()
            .exactOptional()
            .openapi({
              description:
                'Name of the SIPREC session. May be used to stop the SIPREC session from TeXML instruction.',
              example: 'my_siprec_session',
            }),
          Track: z
            .enum(['both_tracks', 'inbound_track', 'outbound_track'])
            .exactOptional()
            .openapi({
              description:
                'The track to be used for siprec session. Can be `both_tracks`, `inbound_track` or `outbound_track`. Defaults to `both_tracks`.',
              example: 'both_tracks',
            }),
          IncludeMetadataCustomHeaders: z
            .preprocess(
              ((read) => (val: unknown) => {
                const result = read.safeParse(val)
                return result.success ? result.data : val
              })(z.stringbool()),
              z.union([z.literal(true), z.literal(false)]),
            )
            .exactOptional()
            .openapi({
              description:
                'When set, custom parameters will be added as metadata (recording.session.ExtensionParameters). Otherwise, they’ll be added to sip headers.',
              example: true,
            }),
          Secure: z
            .preprocess(
              ((read) => (val: unknown) => {
                const result = read.safeParse(val)
                return result.success ? result.data : val
              })(z.stringbool()),
              z.union([z.literal(true), z.literal(false)]),
            )
            .exactOptional()
            .openapi({
              description:
                'Controls whether to encrypt media sent to your SRS using SRTP and TLS. When set you need to configure SRS port in your connector to 5061.',
              example: true,
            }),
          SessionTimeoutSecs: z
            .preprocess(
              (val) =>
                typeof val === 'string' &&
                /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                  ? Number(val)
                  : val,
              z.int(),
            )
            .default(1800)
            .exactOptional()
            .openapi({
              description:
                'Sets `Session-Expires` header to the INVITE. A reinvite is sent every half the value set. Usefull for session keep alive. Minimum value is 90, set to 0 to disable.',
              example: 900,
            }),
          SipTransport: z
            .enum(['udp', 'tcp', 'tls'])
            .default('udp')
            .exactOptional()
            .openapi({ description: 'Specifies SIP transport protocol.', example: 'tcp' }),
          StatusCallback: z
            .string()
            .exactOptional()
            .openapi({
              description:
                'URL destination for Telnyx to send status callback events to for the siprec session.',
              example: 'https://www.example.com/callback',
            }),
          StatusCallbackMethod: z
            .enum(['GET', 'POST'])
            .exactOptional()
            .openapi({
              description: 'HTTP request type used for `StatusCallback`.',
              example: 'GET',
            }),
        })
        .openapi({ title: 'Create Siprec Session Request', required: [] }),
    },
  },
}

