export const getAiAssistantsTestsRoute = createRoute({
  method: 'get',
  path: '/ai/assistants/tests',
  tags: ['Assistants'],
  summary: 'List assistant tests with pagination',
  description: 'Retrieves a paginated list of assistant tests with optional filtering capabilities',
  operationId: 'get_assistant_tests_public_assistants_tests_get',
  request: {
    query: z
      .looseObject({})
      .transform((val) => {
        const rest: [string, unknown][] = []
        const groups = new Map<string, Record<string, unknown>>()
        const group = (name: string) => {
          const found = groups.get(name)
          if (found !== undefined) return found
          const made: Record<string, unknown> = Object.create(null)
          groups.set(name, made)
          return made
        }
        const isGroup = (item: unknown): item is Record<string, unknown> =>
          typeof item === 'object' && item !== null && !Array.isArray(item)
        const lists = new WeakSet<object>()
        const isIndex = (part: string | undefined) => part !== undefined && /^\d*$/.test(part)
        const child = (target: Record<string, unknown>, key: string, asList: boolean) => {
          const held = target[key]
          if (isGroup(held)) return held
          const made: Record<string, unknown> = Object.create(null)
          if (asList) lists.add(made)
          target[key] = made
          return made
        }
        const set = (
          root: Record<string, unknown>,
          path: readonly string[],
          item: unknown,
        ): void => {
          const work: [Record<string, unknown>, number, unknown, boolean][] = [
            [root, 0, item, false],
          ]
          for (let job = work.pop(); job !== undefined; job = work.pop()) {
            const [target, at, value, split] = job
            const head = path[at]
            if (head === undefined) continue
            const next = path[at + 1]
            if (head === '') {
              if (!split && Array.isArray(value)) {
                for (let i = value.length - 1; i >= 0; i -= 1)
                  work.push([target, at, value[i], true])
                continue
              }
              const size = Object.keys(target).length
              if (next === undefined) {
                target[String(size)] = value
                continue
              }
              const free =
                next === ''
                  ? -1
                  : Object.values(target).findIndex((held) => isGroup(held) && !(next in held))
              work.push([
                child(target, String(free < 0 ? size : free), isIndex(next)),
                at + 1,
                value,
                false,
              ])
              continue
            }
            if (next === undefined) {
              target[head] = value
              continue
            }
            work.push([child(target, head, isIndex(next)), at + 1, value, false])
          }
        }
        const settle = (root: unknown): unknown => {
          if (!isGroup(root)) return root
          const found: [Record<string, unknown>, string, Record<string, unknown>][] = []
          const queue: Record<string, unknown>[] = [root]
          for (const node of queue) {
            for (const [key, inner] of Object.entries(node)) {
              if (isGroup(inner)) {
                found.push([node, key, inner])
                queue.push(inner)
              }
            }
          }
          const finish = (group: Record<string, unknown>): unknown =>
            lists.has(group)
              ? Object.entries(group)
                  .sort((a, b) => Number(a[0]) - Number(b[0]))
                  .map(([, inner]) => inner)
              : Object.assign(Object.create(null), group)
          for (const [parent, key, group] of found.reverse()) {
            parent[key] = finish(group)
          }
          return finish(root)
        }
        const deep: string[] = ['page']
        for (const [key, item] of Object.entries(val)) {
          const match = /^([^\[\]]+)((?:\[[^\[\]]*\])+)$/.exec(key)
          const name = match?.[1]
          const path = match?.[2]
          if (name !== undefined && path !== undefined && deep.includes(name)) {
            const parts = path.slice(1, -1).split('][')
            set(group(name), parts, item)
            continue
          }
          rest.push([key, item])
        }
        return Object.fromEntries([
          ...rest,
          ...[...groups].map(([name, held]) => [name, settle(held)] as const),
        ])
      })
      .pipe(
        z.object({
          test_suite: z
            .string()
            .exactOptional()
            .openapi({
              param: {
                name: 'test_suite',
                in: 'query',
                required: false,
                schema: {
                  type: 'string',
                  description: 'Filter tests by test suite name',
                  title: 'Test Suite',
                },
                description: 'Filter tests by test suite name',
              },
              description: 'Filter tests by test suite name',
              title: 'Test Suite',
            }),
          telnyx_conversation_channel: z
            .string()
            .exactOptional()
            .openapi({
              param: {
                name: 'telnyx_conversation_channel',
                in: 'query',
                required: false,
                schema: {
                  type: 'string',
                  description: "Filter tests by communication channel (e.g., 'web_chat', 'sms')",
                  title: 'Telnyx Conversation Channel',
                },
                description: "Filter tests by communication channel (e.g., 'web_chat', 'sms')",
              },
              description: "Filter tests by communication channel (e.g., 'web_chat', 'sms')",
              title: 'Telnyx Conversation Channel',
            }),
          destination: z
            .string()
            .exactOptional()
            .openapi({
              param: {
                name: 'destination',
                in: 'query',
                required: false,
                schema: {
                  type: 'string',
                  description: 'Filter tests by destination (phone number, webhook URL, etc.)',
                  title: 'Destination',
                },
                description: 'Filter tests by destination (phone number, webhook URL, etc.)',
              },
              description: 'Filter tests by destination (phone number, webhook URL, etc.)',
              title: 'Destination',
            }),
          page: z
            .object({
              size: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int().min(1).max(100),
                )
                .default(20)
                .exactOptional()
                .openapi({
                  description: 'Number of tests to return per page (1-100)',
                  title: 'Page[Size]',
                }),
              number: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int().min(1),
                )
                .default(1)
                .exactOptional()
                .openapi({
                  description: 'Page number to retrieve (1-based indexing)',
                  title: 'Page[Number]',
                }),
            })
            .exactOptional()
            .openapi({
              param: {
                name: 'page',
                in: 'query',
                style: 'deepObject',
                explode: true,
                description:
                  'Consolidated page parameter (deepObject style). Originally: page[size], page[number]',
                schema: {
                  type: 'object',
                  properties: {
                    size: {
                      type: 'integer',
                      maximum: 100,
                      minimum: 1,
                      description: 'Number of tests to return per page (1-100)',
                      default: 20,
                      title: 'Page[Size]',
                    },
                    number: {
                      type: 'integer',
                      minimum: 1,
                      description: 'Page number to retrieve (1-based indexing)',
                      default: 1,
                      title: 'Page[Number]',
                    },
                  },
                },
                required: false,
              },
              required: [],
            }),
        }),
      ),
  },
  responses: {
    200: {
      description: 'Returns paginated test list with metadata for navigation and filtering',
      content: { 'application/json': { schema: PaginatedAssistantTestListSchema } },
    },
    422: {
      description: 'Validation Error',
      content: { 'application/json': { schema: HTTPValidationErrorSchema } },
    },
  },
})

