export const deleteAiAssistantsAssistantIdRoute = createRoute({
  method: 'delete',
  path: '/ai/assistants/{assistant_id}',
  tags: ['Assistants'],
  summary: 'Delete an assistant',
  description:
    "Delete an AI Assistant by `assistant_id`.\n\nBy default this performs a soft delete: the assistant moves to the Recently Deleted list and stays restorable for 30 days, after which it is permanently deleted automatically. The assistant's versions and TeXML application are preserved during the retention window.\n\nPass `hard_delete=true` to skip the retention window and permanently delete the assistant immediately. A hard delete erases the assistant and all of its versions, and deletes its TeXML application unless phone numbers are still assigned to it. It does not delete conversations, recordings, shared tools the assistant referenced, or knowledge-base embeddings.\n\nDeletion fails with `400` if other assistants reference this one through a handoff tool or a conversation-flow edge — remove those references first.",
  operationId: 'delete_assistant_public_assistants__assistant_id__delete',
  request: {
    params: z.object({
      assistant_id: z
        .string()
        .openapi({
          param: {
            name: 'assistant_id',
            in: 'path',
            description: 'Unique identifier of the assistant.',
            required: true,
            schema: { type: 'string', title: 'Assistant Id' },
          },
          title: 'Assistant Id',
        }),
    }),
    query: z.object({
      hard_delete: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            name: 'hard_delete',
            in: 'query',
            description:
              'Permanently delete the assistant immediately instead of soft-deleting it to the Recently Deleted list, where it stays restorable for 30 days.',
            required: false,
            schema: { type: 'boolean', default: false, title: 'Hard Delete' },
          },
          title: 'Hard Delete',
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successful Response',
      content: {
        'application/json': {
          schema: AssistantDeletedResponseSchema,
          example: { id: 'assistant_7f3c2a1b', object: 'assistant.deleted', deleted: true },
        },
      },
    },
    400: {
      description:
        'Bad Request (code 10015). Another assistant depends on this one: a handoff tool points to it, or a conversation-flow edge hands off to it. The detail names the referencing assistants; remove those references and retry.',
      content: {
        'application/json': {
          schema: InferenceEmbeddingErrorResponseSchema,
          example: {
            errors: [
              {
                code: '10015',
                title: 'Bad Request',
                detail:
                  "Cannot delete assistant assistant_7f3c2a1b. The following assistant(s) have handoff tools pointing to it: 'Billing Bot' (assistant_9c1d2e3f). Please remove these handoff tools before deleting.",
              },
            ],
          },
        },
      },
    },
    422: {
      description: 'Validation Error',
      content: { 'application/json': { schema: HTTPValidationErrorSchema } },
    },
  },
})

