export const getAiAssistantsAssistantIdScheduledEventsRoute = createRoute({
  method: 'get',
  path: '/ai/assistants/{assistant_id}/scheduled_events',
  tags: ['Assistants'],
  summary: 'List scheduled events',
  description: 'Get scheduled events for an assistant with pagination and filtering',
  operationId: 'get_scheduled_events',
  request: {
    params: z.object({
      assistant_id: z
        .string()
        .openapi({
          param: {
            name: 'assistant_id',
            in: 'path',
            description: 'Unique identifier of the assistant.',
            required: true,
            schema: { type: 'string', title: 'Assistant Id' },
          },
          title: 'Assistant Id',
        }),
    }),
    query: z
      .looseObject({})
      .transform((val) => {
        const rest: [string, unknown][] = []
        const groups = new Map<string, Record<string, unknown>>()
        const group = (name: string) => {
          const found = groups.get(name)
          if (found !== undefined) return found
          const made: Record<string, unknown> = Object.create(null)
          groups.set(name, made)
          return made
        }
        const isGroup = (item: unknown): item is Record<string, unknown> =>
          typeof item === 'object' && item !== null && !Array.isArray(item)
        const lists = new WeakSet<object>()
        const isIndex = (part: string | undefined) => part !== undefined && /^\d*$/.test(part)
        const child = (target: Record<string, unknown>, key: string, asList: boolean) => {
          const held = target[key]
          if (isGroup(held)) return held
          const made: Record<string, unknown> = Object.create(null)
          if (asList) lists.add(made)
          target[key] = made
          return made
        }
        const set = (
          root: Record<string, unknown>,
          path: readonly string[],
          item: unknown,
        ): void => {
          const work: [Record<string, unknown>, number, unknown, boolean][] = [
            [root, 0, item, false],
          ]
          for (let job = work.pop(); job !== undefined; job = work.pop()) {
            const [target, at, value, split] = job
            const head = path[at]
            if (head === undefined) continue
            const next = path[at + 1]
            if (head === '') {
              if (!split && Array.isArray(value)) {
                for (let i = value.length - 1; i >= 0; i -= 1)
                  work.push([target, at, value[i], true])
                continue
              }
              const size = Object.keys(target).length
              if (next === undefined) {
                target[String(size)] = value
                continue
              }
              const free =
                next === ''
                  ? -1
                  : Object.values(target).findIndex((held) => isGroup(held) && !(next in held))
              work.push([
                child(target, String(free < 0 ? size : free), isIndex(next)),
                at + 1,
                value,
                false,
              ])
              continue
            }
            if (next === undefined) {
              target[head] = value
              continue
            }
            work.push([child(target, head, isIndex(next)), at + 1, value, false])
          }
        }
        const settle = (root: unknown): unknown => {
          if (!isGroup(root)) return root
          const found: [Record<string, unknown>, string, Record<string, unknown>][] = []
          const queue: Record<string, unknown>[] = [root]
          for (const node of queue) {
            for (const [key, inner] of Object.entries(node)) {
              if (isGroup(inner)) {
                found.push([node, key, inner])
                queue.push(inner)
              }
            }
          }
          const finish = (group: Record<string, unknown>): unknown =>
            lists.has(group)
              ? Object.entries(group)
                  .sort((a, b) => Number(a[0]) - Number(b[0]))
                  .map(([, inner]) => inner)
              : Object.assign(Object.create(null), group)
          for (const [parent, key, group] of found.reverse()) {
            parent[key] = finish(group)
          }
          return finish(root)
        }
        const deep: string[] = ['page']
        for (const [key, item] of Object.entries(val)) {
          const match = /^([^\[\]]+)((?:\[[^\[\]]*\])+)$/.exec(key)
          const name = match?.[1]
          const path = match?.[2]
          if (name !== undefined && path !== undefined && deep.includes(name)) {
            const parts = path.slice(1, -1).split('][')
            set(group(name), parts, item)
            continue
          }
          rest.push([key, item])
        }
        return Object.fromEntries([
          ...rest,
          ...[...groups].map(([name, held]) => [name, settle(held)] as const),
        ])
      })
      .pipe(
        z.object({
          from_date: z.iso
            .datetime({ offset: true })
            .exactOptional()
            .openapi({
              param: {
                name: 'from_date',
                in: 'query',
                description: 'Start of the date range filter (inclusive, ISO 8601).',
                required: false,
                schema: { type: 'string', format: 'date-time', title: 'From Date' },
              },
              title: 'From Date',
            }),
          to_date: z.iso
            .datetime({ offset: true })
            .exactOptional()
            .openapi({
              param: {
                name: 'to_date',
                in: 'query',
                description: 'End of the date range filter (inclusive, ISO 8601).',
                required: false,
                schema: { type: 'string', format: 'date-time', title: 'To Date' },
              },
              title: 'To Date',
            }),
          conversation_channel: ConversationChannelTypeSchema.openapi({
            param: {
              name: 'conversation_channel',
              in: 'query',
              description: 'Filter results by conversation channel.',
              required: false,
              schema: {
                $ref: '#/components/schemas/ConversationChannelType',
                title: 'Conversation Channel',
              },
            },
          }).exactOptional(),
          page: z
            .object({
              size: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int().min(1).max(100),
                )
                .default(20)
                .exactOptional()
                .openapi({ title: 'Page[Size]' }),
              number: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int().min(1),
                )
                .default(1)
                .exactOptional()
                .openapi({ title: 'Page[Number]' }),
            })
            .exactOptional()
            .openapi({
              param: {
                name: 'page',
                in: 'query',
                style: 'deepObject',
                explode: true,
                description:
                  'Consolidated page parameter (deepObject style). Originally: page[size], page[number]',
                schema: {
                  type: 'object',
                  properties: {
                    size: {
                      type: 'integer',
                      maximum: 100,
                      minimum: 1,
                      default: 20,
                      title: 'Page[Size]',
                    },
                    number: { type: 'integer', minimum: 1, default: 1, title: 'Page[Number]' },
                  },
                },
                required: false,
              },
              required: [],
            }),
        }),
      ),
  },
  responses: {
    200: {
      description: 'Successful Response',
      content: {
        'application/json': {
          schema: PaginatedScheduledEventListSchema,
          example: {
            meta: { total_pages: 0, total_results: 0, page_number: 0, page_size: 0 },
            data: [
              {
                telnyx_conversation_channel: 'phone_call',
                telnyx_end_user_target: 'Telnyx End User Target',
                telnyx_agent_target: 'Telnyx Agent Target',
                scheduled_at_fixed_datetime: '2024-01-23T18:10:02.574Z',
                assistant_id: 'Assistant Id',
                retry_count: 0,
                retry_attempts: 0,
                scheduled_event_id: 'Scheduled Event Id',
                conversation_id: 'Conversation Id',
                created_at: '2024-01-23T18:10:02.574Z',
                status: 'pending',
                errors: ['string'],
                call_status: 'Call Status',
                call_duration: 0,
                max_retries_client_errors: 0,
                retry_interval_secs: 0,
                call_attempts: [
                  {
                    attempt_number: 0,
                    attempted_at: '2024-01-23T18:10:02.574Z',
                    call_status: 'Call Status',
                    call_duration: 0,
                    telnyx_call_control_id: 'Telnyx Call Control Id',
                  },
                ],
                dispatched_at: '2024-01-23T18:10:02.574Z',
                call_settings: { sip_region: 'US' },
              },
            ],
          },
        },
      },
    },
    422: {
      description: 'Validation Error',
      content: { 'application/json': { schema: HTTPValidationErrorSchema } },
    },
  },
})

