export const getAiAvatarsRoute = createRoute({
  method: 'get',
  path: '/ai/avatars',
  tags: ['Avatars'],
  summary: 'List avatars',
  description:
    "Returns a paginated list of the Telnyx stock avatars and custom avatars available to the authenticated organization. Custom avatars owned by other organizations are never returned. The `image_url` value is suitable for displaying a thumbnail and may be refreshed by listing or retrieving the avatar again. `suggested_voice_id` recommends a compatible Telnyx voice for stock avatars and is an empty string for custom avatars; it does not change an AI Assistant's voice automatically.",
  operationId: 'list_avatars_public_avatars_get',
  request: {
    query: z.object({
      'page[size]': z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1).max(100),
        )
        .default(20)
        .exactOptional()
        .openapi({
          param: {
            name: 'page[size]',
            in: 'query',
            description: 'Number of avatars to return per page.',
            required: false,
            schema: { type: 'integer', minimum: 1, maximum: 100, default: 20 },
          },
        }),
      'page[number]': z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            name: 'page[number]',
            in: 'query',
            description: 'Page number to retrieve, starting at 1.',
            required: false,
            schema: { type: 'integer', minimum: 1, default: 1 },
          },
        }),
      'filter[name]': z
        .string()
        .min(1)
        .max(255)
        .exactOptional()
        .openapi({
          param: {
            name: 'filter[name]',
            in: 'query',
            description:
              'Return avatars whose names contain this value, using case-insensitive matching.',
            required: false,
            schema: { type: 'string', minLength: 1, maxLength: 255 },
          },
        }),
      'filter[id]': AvatarIdSchema.openapi({
        param: {
          name: 'filter[id]',
          in: 'query',
          description: 'Return the avatar with this exact ID.',
          required: false,
          schema: { $ref: '#/components/schemas/AvatarId' },
        },
      }).exactOptional(),
      'filter[avatar_type]': AvatarTypeSchema.openapi({
        param: {
          name: 'filter[avatar_type]',
          in: 'query',
          description: 'Return only stock or custom avatars.',
          required: false,
          schema: { $ref: '#/components/schemas/AvatarType' },
        },
      }).exactOptional(),
    }),
  },
  responses: {
    200: {
      description: 'A page of available avatars.',
      content: {
        'application/json': {
          schema: AvatarListResponseSchema,
          example: {
            data: [
              {
                id: 'elena',
                name: 'Elena',
                provider: 'telnyx',
                avatar_type: 'stock',
                hosted: true,
                image_url: 'https://example.com/avatars/elena.png',
                suggested_voice_id: 'Telnyx.Ultra.db6b0ed5-d5d3-463d-ae85-518a07d3c2b4',
              },
              {
                id: 'avatar_0123456789abcdef0123456789abcdef',
                name: 'Customer portrait',
                provider: 'telnyx',
                avatar_type: 'custom',
                hosted: true,
                image_url: 'https://example.com/avatar.png',
                image_url_expires_at: '2026-10-13T15:00:00Z',
                suggested_voice_id: '',
                content_type: 'image/png',
                size_bytes: 248512,
                width_px: 1920,
                height_px: 1080,
                created_at: '2026-10-13T14:00:00Z',
                updated_at: '2026-10-13T14:00:00Z',
              },
            ],
            meta: { total_pages: 1, total_results: 2, page_number: 1, page_size: 20 },
          },
        },
      },
    },
    400: AvatarRequestValidationErrorResponseResponse,
    503: AvatarServiceUnavailableResponseResponse,
  },
})

export const postAiAvatarsRoute = createRoute({
  method: 'post',
  path: '/ai/avatars',
  tags: ['Avatars'],
  summary: 'Create a custom avatar',
  description:
    'Uploads an image, validates its file type, size, safe decoding, and resolution, stores it in Telnyx-managed private storage, and creates an avatar owned by the authenticated organization. Creating an avatar does not update an AI Assistant; use the returned ID separately wherever the avatar is consumed. The avatar image is stored independently from the rendering model and background, which are selected where the avatar is consumed. Supported image types are JPEG, PNG, and WebP. Images may be up to 10 MiB, must be between 256 and 8192 pixels on each side, and may contain at most 40 megapixels. A per-organization custom-avatar quota applies; the create request returns an error when the quota is reached. For best results, use a 16:9 landscape image, preferably 1920 by 1080 pixels and at least 1280 by 720 pixels. Show one centered, front-facing person from the shoulders up, keep the full head and hair visible with space around it, and use a sharp, evenly lit image with unobstructed eyes and mouth. Use a transparent PNG or WebP when the avatar will be combined with a selectable background. These composition recommendations are not enforced in the first release; the first release does not validate the number of faces, pose, or image content.',
  operationId: 'create_avatar_public_avatars_post',
  request: {
    body: {
      content: {
        'multipart/form-data': {
          schema: CreateAvatarRequestSchema,
          example: { image_file: 'string($binary)', name: 'Customer portrait' },
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'The custom avatar was validated, stored, and created.',
      content: {
        'application/json': {
          schema: AvatarResponseSchema,
          example: {
            data: {
              id: 'avatar_0123456789abcdef0123456789abcdef',
              name: 'Customer portrait',
              provider: 'telnyx',
              avatar_type: 'custom',
              hosted: true,
              image_url: 'https://example.com/avatar.png',
              image_url_expires_at: '2026-10-13T15:00:00Z',
              suggested_voice_id: '',
              content_type: 'image/png',
              size_bytes: 248512,
              width_px: 1920,
              height_px: 1080,
              created_at: '2026-10-13T14:00:00Z',
              updated_at: '2026-10-13T14:00:00Z',
            },
          },
        },
      },
    },
    400: AvatarRequestValidationErrorResponseResponse,
    422: AvatarValidationErrorResponseResponse,
    503: AvatarServiceUnavailableResponseResponse,
  },
})

