export const postAiOpenaiResponsesRoute = createRoute({
  method: 'post',
  path: '/ai/openai/responses',
  tags: ['OpenAI Chat'],
  summary: 'Create an OpenAI-compatible response',
  description:
    "Create a response using Telnyx's OpenAI-compatible Responses API. This endpoint is compatible with the [OpenAI Responses API](https://developers.openai.com/api/reference/responses/overview) and may be used with the OpenAI JS or Python SDK by setting the base URL to `https://api.telnyx.com/v2/ai/openai`.\n\nThe `conversation` parameter refers to a Telnyx Conversation rather than an OpenAI-hosted conversation object. To persist a thread across turns, first [create a conversation](https://developers.telnyx.com/api-reference/conversations/create-a-conversation) with `POST /ai/conversations`, then pass that conversation's `id` in the Responses request as `conversation`. The endpoint appends the new input, assistant output, reasoning, and tool-call messages to that conversation. Reuse the same `conversation` id on subsequent Responses requests, including tool-result followups, so the model receives the prior context.\n\nIf `conversation` is omitted, the request is processed without persisting messages to a Telnyx conversation. Use the Conversations API to manage history: [list conversations](https://developers.telnyx.com/api-reference/conversations/list-conversations) (optionally filtered by metadata), [fetch messages](https://developers.telnyx.com/api-reference/conversations/get-conversation-messages) for a conversation, and optionally [add messages](https://developers.telnyx.com/api-reference/conversations/create-message) outside the Responses flow.\n\nYou can attach arbitrary metadata when creating a conversation (for example to tag the conversation's source, channel, or user) and later filter by it when listing conversations.",
  operationId: 'chat_public_openai_responses_completions_post',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .looseObject({
              model: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Model identifier to use for the response, for example `zai-org/GLM-5.1-FP8` or another model available from the Telnyx OpenAI-compatible models endpoint.',
                }),
              service_tier: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    "The service tier to use for this request. Supported values vary by model; use `GET /v2/ai/openai/models` and inspect the model's `service_tiers` field. If omitted, Telnyx-hosted models use `default`.",
                }),
              region: z
                .enum(['USA', 'EU', 'AUS', 'UAE'])
                .exactOptional()
                .openapi({
                  description:
                    "Optional data-residency region the request should be served from, using the same vocabulary as your account's Data Locality setting. Behavior depends on `mode`. Supported for Telnyx-hosted models only: a request routed to an external provider never passes through Telnyx model routing, so a region cannot be enforced for it. Omit for today's latency-based routing.",
                }),
              mode: z
                .enum(['preferred', 'strict'])
                .default('preferred')
                .exactOptional()
                .openapi({
                  description:
                    'How strictly `region` is applied. `preferred` (the default when `region` is set) tries that region first and falls back to another when the model cannot be served there, so a request that would have succeeded still succeeds. `strict` pins the request: it is served from that region or it fails with a 422, never redirected to another region. Requires `region`.',
                }),
              input: z
                .any()
                .exactOptional()
                .openapi({
                  description:
                    'The input items for this turn, using the OpenAI Responses API input format.',
                }),
              conversation: z
                .uuid()
                .exactOptional()
                .openapi({
                  description:
                    "Optional Telnyx Conversation ID from `POST /ai/conversations`. When provided, Telnyx stores this turn on that conversation and uses the conversation's prior messages as context. Reuse the same ID for subsequent turns and tool-result followups. Omit it for a non-persisted, stateless response.",
                }),
              instructions: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Optional system/developer instructions for the model. When used with a persisted `conversation`, send these on the first request that creates the thread; subsequent turns can rely on the stored history.',
                }),
              stream: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    "Set to `true` to stream Server-Sent Events, matching OpenAI's Responses streaming format.",
                }),
              reasoning: z
                .object({
                  effort: z
                    .enum(['none', 'minimal', 'low', 'medium', 'high', 'xhigh', 'max'])
                    .exactOptional()
                    .openapi({
                      description:
                        'Controls the reasoning effort for models that support it. Same values and semantics as reasoning_effort on Chat Completions.',
                    }),
                })
                .exactOptional()
                .openapi({ required: [] }),
            })
            .openapi({ required: [] }),
          example: {
            model: 'zai-org/GLM-5.1-FP8',
            conversation: '6a09cdc3-8948-47f0-aa62-74ac943d6c58',
            instructions: 'You are a friendly chatbot.',
            input: [{ role: 'user', content: [{ type: 'input_text', text: 'Hello, world!' }] }],
            stream: false,
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Successful Response',
      content: {
        'application/json': {
          schema: z.looseObject({}),
          example: {
            id: 'resp_8b1f2a3c9d4e5f6a',
            object: 'response',
            created_at: 1706011802,
            status: 'completed',
            model: 'zai-org/GLM-5.1-FP8',
            output: [
              {
                type: 'message',
                id: 'msg_8b1f2a3c9d4e5f6a',
                role: 'assistant',
                content: [
                  {
                    type: 'output_text',
                    text: 'Telnyx provides carrier-grade voice, messaging, and AI inference through one API.',
                  },
                ],
              },
            ],
            usage: { input_tokens: 24, output_tokens: 18, total_tokens: 42 },
          },
        },
      },
    },
    422: {
      description: 'Validation Error',
      content: { 'application/json': { schema: HTTPValidationErrorSchema } },
    },
  },
})

