export const postAiToolsRoute = createRoute({
  method: 'post',
  path: '/ai/tools',
  tags: ['Assistants'],
  summary: 'Create Tool',
  description: 'Create a new custom AI tool that can be attached to AI assistants.',
  operationId: 'create_tool_post',
  request: {
    headers: z.object({ 'Idempotency-Key': IdempotencyKeyParamsSchema }),
    body: {
      content: { 'application/json': { schema: CreateSharedToolRequestSchema } },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Successful Response',
      content: {
        'application/json': {
          schema: SharedToolResponseSchema,
          example: {
            id: 'Id',
            type: 'Type',
            display_name: 'Display Name',
            timeout_ms: 5000,
            created_at: 'Created At',
            tool_definition: { type: 'webhook' },
          },
        },
      },
      headers: z.object({ 'Idempotent-Replayed': IdempotentReplayedHeaderSchema }),
    },
    400: {
      description:
        'Bad Request / Validation Failed (10015). Invalid, duplicate, empty, malformed, or overlong Idempotency-Key headers are rejected by Edge with HTTP 400 and error code 10015.',
      content: { 'application/json': { schema: InferenceEmbeddingErrorResponseSchema } },
    },
    409: IdempotencyConflictResponseResponse,
    413: {
      description:
        "Payload Too Large. A request sent with an Idempotency-Key whose body exceeds the endpoint's Edge replay-protection limit (256 KB) is rejected before it reaches the service. Requests sent without the header are not subject to this limit.",
      content: { 'application/json': { schema: InferenceEmbeddingErrorResponseSchema } },
    },
    422: {
      description:
        'Validation Error. Reusing an Idempotency-Key with a different request body also returns 422 with error code 10027.',
      content: {
        'application/json': {
          schema: z.union([HTTPValidationErrorSchema, InferenceEmbeddingErrorResponseSchema]),
        },
      },
    },
    503: {
      description:
        'Service unavailable (10016), including unavailable Edge idempotency protection for a keyed request.',
      content: { 'application/json': { schema: InferenceEmbeddingErrorResponseSchema } },
    },
  },
})

