export const postBrowserSessionsIdActionsRoute = createRoute({
  method: 'post',
  path: '/browser_sessions/{id}/actions',
  tags: ['Actions'],
  summary: 'Execute browser action',
  description:
    'Executes a browser action on the session. Returns 200 if completed within wait_seconds, 202 if still in-flight.\n\nAction types: navigate, observe, click, fill, select, press, scroll, wait_for, screenshot, batch.',
  operationId: 'ExecuteBrowserAction',
  request: {
    params: z.object({
      id: z
        .string()
        .openapi({ param: { name: 'id', in: 'path', required: true, schema: { type: 'string' } } }),
    }),
    query: z.object({
      wait_seconds: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(0).max(25),
        )
        .default(10)
        .exactOptional()
        .openapi({
          param: {
            name: 'wait_seconds',
            in: 'query',
            required: false,
            schema: { type: 'integer', minimum: 0, maximum: 25, default: 10 },
            description:
              'Maximum seconds the submission request waits for completion, not an execution timeout. If still queued or running, returns 202 without cancelling execution; poll the returned action ID.',
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: ActionRequestSchema,
          examples: {
            navigate: {
              summary: 'Navigate',
              value: { type: 'navigate', url: 'https://example.com/' },
            },
            observe: { summary: 'Observe', value: { type: 'observe' } },
            click: {
              summary: 'Click',
              value: { type: 'click', observation_id: 'obs_...', ref: 'e1' },
            },
            screenshot: { summary: 'Screenshot', value: { type: 'screenshot' } },
            batch: {
              summary: 'Batch',
              value: {
                type: 'batch',
                actions: [{ type: 'navigate', url: 'https://example.com/' }, { type: 'observe' }],
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description:
        'Terminal action: succeeded, failed, or unknown. Inspect data.status and data.error; HTTP 200 does not imply successful execution.',
      content: {
        'application/json': {
          schema: z
            .object({ data: ActionResponseSchema.exactOptional() })
            .openapi({ required: [] }),
        },
      },
    },
    202: {
      description: 'Action still in-flight — poll for result',
      content: {
        'application/json': {
          schema: z
            .object({ data: ActionResponseSchema.exactOptional() })
            .openapi({ required: [] }),
        },
      },
    },
    400: BadRequestResponse,
    401: UnauthorizedResponse,
    404: NotFoundResponse,
    409: {
      description:
        'session_not_ready: new actions require a ready session; poll while provisioning, but do not retry new actions on closing or terminal sessions. concurrent_action: wait for the in-flight action. idempotency_conflict: the key was reused with a different normalized request.',
      content: {
        'application/json': {
          schema: ErrorResponseSchema,
          example: {
            error: {
              code: 'session_not_ready',
              message: 'session is provisioning',
              retryable: true,
            },
          },
        },
      },
    },
    503: {
      description:
        'The request could not be completed reliably. Retrieve action and session state before retrying; a mutation may already have taken effect. Do not blindly repeat it with a new idempotency key or session.',
      content: {
        'application/json': {
          schema: ErrorResponseSchema,
          example: {
            error: {
              code: 'execution_lost',
              message: 'Request could not be completed reliably',
              retryable: true,
            },
          },
        },
      },
    },
  },
})

