export const getDirRoute = createRoute({
  method: 'get',
  path: '/dir',
  tags: ['Display Identity Records'],
  summary: 'List all DIRs across your enterprises',
  description:
    'Returns every DIR (Display Identity Record) you own, across all of your enterprises, as a single list. Pagination is JSON:API style (`page[number]`, `page[size]`, max 250). Supports `filter[]` query params: `filter[enterprise_id]`, `filter[status]`, `filter[display_name][contains]`, `filter[call_reason][contains]`, plus the renewal-window filters `filter[expiring_at][gte]` / `filter[expiring_at][lte]`. Sortable by `created_at`, `updated_at`, `display_name`, `status` (prefix `-` for descending; default `-created_at`).',
  operationId: 'listAllDirs',
  request: {
    query: z.object({
      'page[number]': BcPageNumberParamsSchema,
      'page[size]': BcPageSizeParamsSchema,
      sort: z
        .enum([
          'created_at',
          '-created_at',
          'updated_at',
          '-updated_at',
          'display_name',
          '-display_name',
          'status',
          '-status',
        ])
        .default('-created_at')
        .exactOptional()
        .openapi({
          param: {
            name: 'sort',
            in: 'query',
            required: false,
            description:
              'Sort field. Allowed values: `created_at`, `updated_at`, `display_name`, `status`. Prefix with `-` for descending. Default `-created_at`.',
            schema: {
              type: 'string',
              default: '-created_at',
              enum: [
                'created_at',
                '-created_at',
                'updated_at',
                '-updated_at',
                'display_name',
                '-display_name',
                'status',
                '-status',
              ],
            },
          },
        }),
      'filter[expiring_at][gte]': z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            name: 'filter[expiring_at][gte]',
            in: 'query',
            required: false,
            description:
              'Return only DIRs whose `expiring_at` is at or after this ISO-8601 timestamp. Pairs with the `[lte]` variant to build renewal-window dashboards.',
            schema: { type: 'string', format: 'date-time' },
          },
        }),
      'filter[expiring_at][lte]': z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            name: 'filter[expiring_at][lte]',
            in: 'query',
            required: false,
            description:
              'Return only DIRs whose `expiring_at` is at or before this ISO-8601 timestamp.',
            schema: { type: 'string', format: 'date-time' },
          },
        }),
      'filter[enterprise_id]': z
        .uuid()
        .exactOptional()
        .openapi({
          param: {
            name: 'filter[enterprise_id]',
            in: 'query',
            required: false,
            description: 'Filter by enterprise ID.',
            schema: { type: 'string', format: 'uuid' },
          },
        }),
      'filter[status]': DirStatusSchema.openapi({
        param: {
          name: 'filter[status]',
          in: 'query',
          required: false,
          description: 'Filter by DIR status.',
          schema: { $ref: '#/components/schemas/DirStatus' },
        },
      }).exactOptional(),
      'filter[display_name][contains]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'filter[display_name][contains]',
            in: 'query',
            required: false,
            description: 'Case-insensitive partial match on display name.',
            schema: { type: 'string' },
          },
        }),
      'filter[call_reason][contains]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'filter[call_reason][contains]',
            in: 'query',
            required: false,
            description: 'Case-insensitive partial match on call reason.',
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Paginated list of DIRs across all your enterprises.',
      content: { 'application/json': { schema: DirListSchema } },
    },
    default: BrandedCallingGenericErrorResponseResponse,
    '4XX': BrandedCallingGenericErrorResponseResponse,
  },
})

