export const postEmailBlocksImportRoute = createRoute({
  method: 'post',
  path: '/email_blocks/import',
  tags: ['Email Suppression Imports'],
  summary: 'Create an async CSV import job',
  description:
    'Accepts `multipart/form-data` with a `file` field (the CSV) and an\noptional `block_ttl_days` (integer >0, default 30). Validates:\n  - content ≤ 25 MiB, else `413`\n  - row count ≤ 250 000, else `413`\n  - header-only / all-blank / undetectable provider → `400`\nReturns `202` with the import record (status `pending`); an Oban\nworker (`EmailBlockImportWorker`, max_attempts 3) transitions\n`pending → processing → completed | failed`.\n\nNative Telnyx exports are detected by the stable first-12-column\nheader signature (`id` … `group_id`) and are restored with their\noriginal `from`, `domain_id`, `group_id`, `source`, `status`,\n`expires_at`, plus `bounce_category`, `dsn_code`, and `meta` when\npresent (`scope` is re-derived from `domain_id`/`from`; the\nexported `scope` cell must be a valid enum value). Lifecycle\nchanges reconcile through the same create path as the API: a row\nalready in the requested state restores its mutable backup fields\nwithout a new audit event, and a real transition (e.g. tombstone\n→ active) appends the matching lifecycle event. `block_ttl_days`\nis not applied to native rows — their exported `expires_at` is\npreserved verbatim.\n\nCompetitor and generic imports (SendGrid / Mailgun / SES /\ngeneric) remain account-scoped (`from`, `domain_id`, `group_id`,\n`scope` are not read) and `block_ttl_days` applies only to\nimported `manual_block` rows; other reasons get `expires_at: nil`.\nProvider is auto-detected from the CSV header\n(`sendgrid` / `mailgun` / `ses` / `generic`).\n',
  operationId: 'createEmailBlockImport',
  request: {
    body: {
      content: {
        'multipart/form-data': {
          schema: z
            .object({
              file: z
                .file()
                .openapi({
                  type: 'string',
                  format: 'binary',
                  description: 'The CSV file (Plug.Upload). Missing/non-upload → 400.',
                }),
              block_ttl_days: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int().min(1),
                )
                .default(30)
                .exactOptional()
                .openapi({
                  description:
                    'TTL for imported `manual_block` rows; other reasons get `expires_at: null`. Invalid/missing → falls back to 30.',
                }),
            })
            .openapi({ required: ['file'] }),
          example: { file: 'blocks.csv', block_ttl_days: 30 },
        },
      },
      required: true,
    },
  },
  responses: {
    202: {
      description: 'Import job accepted (status `pending`).',
      content: {
        'application/json': {
          schema: EmailBlockImportResponseSchema,
          example: {
            data: {
              id: '3fa85f64-5717-4562-b3fc-2c963f66afa6',
              record_type: 'email_block_import',
              status: 'pending',
              total: 0,
              provider: 'sendgrid',
              created_at: '2024-01-23T18:10:02.574Z',
              updated_at: '2024-01-23T18:10:02.574Z',
              completed_at: '2024-01-23T18:10:02.574Z',
              processed_rows: 0,
              created_count: 0,
              existing_count: 0,
              skipped_count: 0,
              error_count: 0,
              failure_reason: 'string',
            },
          },
        },
      },
    },
    400: ValidationErrorQueryResponse,
    401: EmailUnauthorizedResponse,
    406: FrameworkErrorResponse,
    413: {
      description:
        'Two distinct 413 paths. Content-level cap (decoded CSV > 25 MiB\nor > 250 000 rows) returns `10015` with `source.pointer /file`.\nThe multipart parser raises `RequestTooLargeError` when the\nencoded body exceeds 26 MiB — that\'s a framework error rendered\nwith body `code: "413"` (matches the HTTP status).\n',
      content: {
        'application/json': {
          schema: ErrorListSchema,
          example: {
            errors: [
              { code: '10007', title: 'Unexpected error', detail: 'An unexpected error occured.' },
            ],
          },
        },
      },
    },
    422: ChangesetErrorResponse,
    500: {
      description: 'Import-create fallback (`code 10019`, "Failed to create import").',
      content: {
        'application/json': {
          schema: ErrorListSchema,
          example: {
            errors: [
              { code: '10007', title: 'Unexpected error', detail: 'An unexpected error occured.' },
            ],
          },
        },
      },
    },
  },
})

