export const getEmailBlocksIdEventsRoute = createRoute({
  method: 'get',
  path: '/email_blocks/{id}/events',
  tags: ['Email Suppressions'],
  summary: 'List audit events for a suppression',
  description:
    'Offset pagination only (`page[number]` default 1, `page[size]`\ndefault **50**, max 100). No `sort`, no `filter`, no cursor —\nordering is fixed `desc occurred_at, desc id`. Verifies the block\nbelongs to the account first (cross-account → 404).\n',
  operationId: 'listEmailBlockEvents',
  request: {
    params: z.object({ id: PathIdParamsSchema }),
    query: z.object({
      'page[number]': BlocksPageNumberParamsSchema,
      'page[size]': z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1).max(100),
        )
        .default(50)
        .exactOptional()
        .openapi({
          param: {
            name: 'page[size]',
            in: 'query',
            description: 'Page size (default 50, max 100).',
            schema: { type: 'integer', minimum: 1, maximum: 100, default: 50 },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Audit events (newest-first).',
      content: {
        'application/json': {
          schema: EmailBlockEventListResponseSchema,
          example: {
            data: [
              {
                id: '3fa85f64-5717-4562-b3fc-2c963f66afa6',
                record_type: 'email_block_event',
                event_type: 'created',
                reason: 'string',
                source: 'string',
                actor: 'string',
                occurred_at: '2024-01-23T18:10:02.574Z',
              },
            ],
            meta: { page_number: 0, page_size: 0, total_pages: 0, total_results: 0 },
          },
        },
      },
    },
    400: ValidationErrorQueryResponse,
    401: EmailUnauthorizedResponse,
    404: BlocksNotFoundResponse,
    406: FrameworkErrorResponse,
  },
})

