export const postEmailInboxesInboxIdDraftsDraftIdSendRoute = createRoute({
  method: 'post',
  path: '/email_inboxes/{inbox_id}/drafts/{draft_id}/send',
  tags: ['Email Drafts'],
  summary: 'Send a draft',
  description:
    'Sends the draft through the standard send pipeline — the same domain resolution,\nsuppression, reputation, daily-quota, persistence and Detail Record behaviour as\n`POST /v2/email_messages`. The response body is the created email message.\n\nIf the draft has no explicit `from_email`, the inbox address is used.\n\nThe draft is marked `sent` only after the send is accepted; a send rejected for\nsuppression, quota or reputation leaves the draft editable so it can be fixed and\nretried. A draft that is already `sent` returns 422 rather than sending twice.\n',
  operationId: 'SendEmailDraft',
  request: {
    params: z.object({ inbox_id: DraftInboxIdParamsSchema, draft_id: DraftIdParamsSchema }),
  },
  responses: {
    202: {
      description: 'The draft was accepted for delivery. Returns the created email message.',
      content: { 'application/json': { schema: EmailMessageResponseSchema } },
    },
    400: {
      description: 'The draft is missing fields required to send (sender, subject, or recipients).',
      content: {
        'application/json': {
          schema: EmailErrorResponseSchema,
          example: {
            errors: [
              {
                code: '10015',
                title: 'Bad Request',
                detail: 'The request failed because it was not well-formed.',
              },
            ],
          },
        },
      },
    },
    401: EmailUnauthorizedResponseResponse,
    403: {
      description: 'The sender domain is not permitted to send.',
      content: { 'application/json': { schema: EmailErrorResponseSchema } },
    },
    404: EmailNotFoundResponseResponse,
    422: {
      description: 'The draft has already been sent, or failed send-time validation.',
      content: {
        'application/json': {
          schema: EmailErrorResponseSchema,
          example: {
            errors: [
              {
                code: '10015',
                title: 'Validation Failed',
                detail: 'this draft has already been sent',
                source: { pointer: '/data/attributes/status' },
              },
            ],
          },
        },
      },
    },
    429: EmailSendTooManyRequestsResponseResponse,
    503: DraftUnavailableResponseResponse,
  },
})

