export const postEmailInboxesInboxIdMessagesMessageIdLabelsRoute = createRoute({
  method: 'post',
  path: '/email_inboxes/{inbox_id}/messages/{message_id}/labels',
  tags: ['Email Inboxes'],
  summary: 'Add labels to an inbox message',
  description:
    'Adds one or more mutable labels to a message. Labels carry agent\nworkflow state such as `spam`, `needs_review`, or `processed`.\n\nLabels are **not** the same as the send-time `tags` on outbound\nmessages: `tags` are immutable and propagate to Email Detail Records\nand Mission Control for billing attribution, while labels are mailbox\nstate that never reaches the reporting contract.\n\nThe operation is an idempotent set union — adding a label the message\nalready carries is a no-op and still returns 200. Labels are\ncase-sensitive, and message labels are independent of thread labels.\n',
  operationId: 'AddEmailInboxMessageLabels',
  request: {
    params: z.object({
      inbox_id: InboxIdPathParamParamsSchema,
      message_id: MessageIdPathParamParamsSchema,
    }),
    body: {
      content: {
        'application/json': {
          schema: LabelMutationRequestSchema,
          example: { labels: ['spam', 'urgent'] },
        },
      },
      required: true,
    },
  },
  responses: {
    200: InboundMessageLabelResponseResponse,
    401: EmailUnauthorizedResponseResponse,
    404: EmailNotFoundResponseResponse,
    422: ValidationErrorResponseResponse,
    503: LabelServiceUnavailableResponseResponse,
  },
})

