export const getEmailMessagesRoute = createRoute({
  method: 'get',
  path: '/email_messages',
  tags: ['Email Messages'],
  summary: 'List email messages',
  description:
    'Lists messages sorted newest first by `created_at desc, id desc`. Tags and metadata filters compose with cursor pagination. The legacy `/v2/emails` GET route is a backward-compatible alias for this operation.\n',
  operationId: 'ListEmailMessages',
  request: {
    query: z.object({
      page_size: EmailPageSizeParamsSchema,
      page_cursor: PageCursorParamsSchema,
      'filter[tags]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'filter[tags]',
            in: 'query',
            required: false,
            description:
              'Comma-separated tags. Each segment is trimmed, and messages having at least one supplied tag are returned; matching is exact and case-sensitive after trimming. Because commas delimit values and surrounding whitespace is removed, this filter cannot represent stored tags containing literal commas or leading/trailing whitespace. An empty value omits the filter. Empty segments and non-string/nested query shapes return HTTP 400.',
            schema: { type: 'string' },
            example: 'billing,transactional',
          },
        }),
      'filter[metadata]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'filter[metadata]',
            in: 'query',
            required: false,
            description:
              'Metadata containment filter, supplied as a JSON object or comma-separated `key=value` pairs. All supplied key/value pairs must be contained in the message metadata. An empty value or empty JSON object omits the filter. Malformed values, valid non-object JSON, pairs without `=`, empty keys, and non-string/nested query shapes return HTTP 400.',
            schema: { type: 'string' },
            examples: {
              jsonObject: { value: '{"campaign":"spring","region":"us"}' },
              keyValuePairs: { value: 'campaign=spring,region=us' },
            },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Paginated list of email messages.',
      content: { 'application/json': { schema: EmailMessageListResponseSchema } },
    },
    400: {
      description: 'The tags or metadata filter is malformed or uses an unsupported query shape.',
      content: {
        'application/json': {
          schema: EmailErrorResponseSchema,
          examples: {
            invalidTagsFilter: {
              value: {
                errors: [
                  {
                    code: '10015',
                    title: 'Bad Request',
                    detail: 'filter[tags] must be a comma-separated list of non-empty tags',
                  },
                ],
              },
            },
            invalidMetadataFilter: {
              value: {
                errors: [
                  {
                    code: '10015',
                    title: 'Bad Request',
                    detail:
                      'filter[metadata] must be a JSON object or comma-separated key=value pairs',
                  },
                ],
              },
            },
          },
        },
      },
    },
    401: EmailUnauthorizedResponseResponse,
  },
})

