export const postEmailMessagesBatchRoute = createRoute({
  method: 'post',
  path: '/email_messages/batch',
  tags: ['Email Messages'],
  summary: 'Create a batch of email messages',
  description:
    'Creates up to 1,000 email messages in a single request. Request-wide admission checks run first and can reject the whole batch before message creation. After those checks pass, each message is validated and sent independently; item-level failures do not affect other messages, and the processed batch returns 207 Multi-Status. Per-message failures include validation errors; when a template has `strict_variables` enabled, a missing required variable produces a per-item `unprocessable_entity` error naming that variable while the other messages continue.',
  operationId: 'CreateEmailMessageBatch',
  request: {
    headers: z.object({ 'Idempotency-Key': IdempotencyKeyParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: CreateEmailBatchRequestSchema,
          example: {
            sandbox_mode: false,
            messages: [
              {
                from: 'sender@example.com',
                to: ['recipient1@example.com'],
                subject: 'Hello 1',
                text_body: 'Message 1',
              },
              {
                from: 'sender@example.com',
                to: ['recipient2@example.com'],
                subject: 'Hello 2',
                text_body: 'Message 2',
              },
            ],
          },
        },
      },
      required: true,
    },
  },
  responses: {
    207: {
      description:
        'Multi-Status — returned after request-wide admission checks pass and item processing runs. Each message is validated and sent independently; per-message failures do not affect other messages in the batch. An invalid or non-future `scheduled_at`/`send_at` is reported as a per-item `unprocessable_entity` error while the remaining items continue. When all messages succeed, `errors` is empty and every item is in `data`; otherwise `data` contains successes and `errors` contains failures. Request-wide gates can instead return 4xx or 5xx.',
      content: { 'application/json': { schema: EmailBatchResponseSchema } },
    },
    400: {
      description:
        'Bad Request / Validation Failed (10015). Invalid, duplicate, empty, malformed, or overlong Idempotency-Key headers are rejected by Edge with HTTP 400 and error code 10015.',
      content: {
        'application/json': {
          schema: EmailErrorResponseSchema,
          example: {
            errors: [{ code: '10015', title: 'Bad Request', detail: 'email is required' }],
          },
        },
      },
    },
    401: EmailUnauthorizedResponseResponse,
    409: IdempotencyConflictResponseResponse,
    413: PayloadTooLargeResponseResponse,
    422: {
      description: 'The Idempotency-Key was already used for a different request (10027).',
      content: {
        'application/json': {
          schema: EmailErrorResponseSchema,
          example: {
            errors: [
              {
                code: '10027',
                title: 'Unprocessable Entity',
                detail:
                  'The server understood the syntax of the request but was unable to process the instructions.',
              },
            ],
          },
        },
      },
    },
    429: EmailSendTooManyRequestsResponseResponse,
    503: EmailServiceUnavailableResponseResponse,
  },
})

export const getEmailMessagesEmailIdEventsRoute = createRoute({
  method: 'get',
  path: '/email_messages/{email_id}/events',
  tags: ['Email Messages'],
  summary: 'List events for an email message',
  description:
    'Lists events for a single message sorted oldest first by `occurred_at asc, id asc`.\nThe legacy `/v2/emails/{id}/events` GET route is a backward-compatible alias.\n\nFor compatibility, each event carries the legacy\ncustomer-visible `event_type` (`email.`-prefixed), the additive\n`canonical_event_type` (`email.`-prefixed), and the deprecated\n`type` duplicate — whose value keeps the exact legacy format:\nthe bare stored event name, never `email.`-prefixed. Gateway\nrejections render `email.failed` + canonical `email.gw_reject`; MTA\nexpirations render `email.bounced` + canonical `email.expired`;\nevery unchanged outcome carries identical `event_type` and\n`canonical_event_type` values (and `type` keeps the stored name).\n',
  operationId: 'ListEmailMessageEvents',
  request: {
    params: z.object({
      email_id: z
        .uuid()
        .openapi({
          param: {
            name: 'email_id',
            in: 'path',
            required: true,
            description: 'Email message UUID.',
            schema: { type: 'string', format: 'uuid' },
          },
        }),
    }),
    query: z.object({ page_size: EmailPageSizeParamsSchema, page_cursor: PageCursorParamsSchema }),
  },
  responses: {
    200: {
      description: 'Paginated list of message events.',
      content: {
        'application/json': {
          schema: MessageEventListResponseSchema,
          example: {
            data: [
              {
                type: 'queued',
                event_type: 'email.queued',
                canonical_event_type: 'email.queued',
                occurred_at: '2026-07-06T18:24:00.000Z',
              },
              {
                type: 'gw_reject',
                event_type: 'email.failed',
                canonical_event_type: 'email.gw_reject',
                occurred_at: '2026-07-06T18:24:00.000Z',
              },
            ],
            meta: { page_size: 50 },
          },
        },
      },
    },
    401: EmailUnauthorizedResponseResponse,
    404: EmailNotFoundResponseResponse,
  },
})

