export const patchEmailMessagesEmailIdScheduleRoute = createRoute({
  method: 'patch',
  path: '/email_messages/{email_id}/schedule',
  tags: ['Email Messages'],
  summary: 'Reschedule a scheduled email message',
  description:
    'Moves an existing scheduled email to a new future send time. Only the delivery time (`scheduled_at`) changes; the message ID, content, recipients, tags, and metadata remain unchanged. Returns `409 Conflict` if the message is no longer scheduled or its scheduled-send worker has already started processing it. This route emits no dedicated `rescheduled` event.',
  operationId: 'RescheduleEmailMessage',
  request: {
    params: z.object({
      email_id: z
        .uuid()
        .openapi({
          param: {
            name: 'email_id',
            in: 'path',
            required: true,
            description: 'Email message UUID.',
            schema: { type: 'string', format: 'uuid' },
          },
        }),
    }),
    body: {
      description:
        'Provide a future delivery time. The timestamp in this example is illustrative; replace it with a value that is in the future when making a request.',
      content: {
        'application/json': {
          schema: RescheduleEmailMessageRequestSchema,
          example: { scheduled_at: '2099-08-07T14:30:00Z' },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description:
        'Scheduled email rescheduled. The response matches the single-message GET representation.',
      content: { 'application/json': { schema: EmailMessageDetailResponseSchema } },
    },
    401: EmailUnauthorizedResponseResponse,
    404: EmailNotFoundResponseResponse,
    409: {
      description:
        'The email is not scheduled or its scheduled-send worker is already processing it.',
      content: { 'application/json': { schema: EmailErrorResponseSchema } },
    },
    422: {
      description: '`scheduled_at` is missing, invalid ISO 8601, or not in the future.',
      content: {
        'application/json': {
          schema: EmailErrorResponseSchema,
          example: {
            errors: [
              {
                code: '10015',
                title: 'Validation Failed',
                detail: 'scheduled_at must be in the future',
                source: { pointer: '/data/attributes/scheduled_at' },
              },
            ],
          },
        },
      },
    },
  },
})

