export const getEmailThreadsRoute = createRoute({
  method: 'get',
  path: '/email_threads',
  tags: ['Email Threads'],
  summary: 'List threads across every inbox in the account',
  description:
    'Lists thread summaries for the whole account, newest first, using stable\ncursor pagination. An agent operating many inboxes gets every\nconversation in one call instead of one call per inbox. Each thread\ncarries its own `inbox_id` so a reply can be routed back to the right\ninbox. Use `filter[inbox_id]` (repeatable) to narrow the result to\nspecific inboxes. Because a thread ID can be delivered to multiple\ninboxes, each result is identified by its `(inbox_id, id)` pair.\n',
  operationId: 'ListEmailThreads',
  request: {
    query: z.object({
      'filter[inbox_id]': z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.uuid()).min(1),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'filter[inbox_id]',
            in: 'query',
            required: false,
            description:
              'Restrict results to one or more inboxes. Repeat the parameter\n(`filter[inbox_id][]=...&filter[inbox_id][]=...`) or pass a\ncomma-separated list. Omit to list every inbox in the account.\nInboxes outside the account are silently excluded. If the filter\nis present, it must contain at least one non-empty UUID.\n',
            explode: true,
            schema: { type: 'array', minItems: 1, items: { type: 'string', format: 'uuid' } },
          },
        }),
      'page[size]': z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1).max(100),
        )
        .default(25)
        .exactOptional()
        .openapi({
          param: {
            name: 'page[size]',
            in: 'query',
            required: false,
            description: 'Number of results to return. Defaults to 25; maximum is 100.',
            schema: { type: 'integer', minimum: 1, maximum: 100, default: 25 },
          },
        }),
      'page[after]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'page[after]',
            in: 'query',
            required: false,
            description: 'Opaque cursor returned by the previous page.',
            schema: { type: 'string' },
          },
        }),
      'filter[label]': z
        .string()
        .max(255)
        .exactOptional()
        .openapi({
          param: {
            name: 'filter[label]',
            in: 'query',
            required: false,
            description:
              "Returns only threads carrying this label. Matching is exact and case-sensitive. Thread labels are independent of the labels on the thread's messages.",
            schema: { type: 'string', maxLength: 255 },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Paginated account-wide threads.',
      content: {
        'application/json': {
          schema: InboundThreadListResponseSchema,
          example: {
            data: [
              {
                id: '33333333-3333-3333-3333-333333333333',
                record_type: 'email_thread',
                inbox_id: '11111111-1111-1111-1111-111111111111',
                subject: 'Project update',
                preview: null,
                message_count: 2,
                unread_count: 1,
                last_message_id: '55555555-5555-5555-5555-555555555555',
                last_message_at: '2026-07-15T12:30:00Z',
                created_at: '2026-07-14T10:00:00Z',
                updated_at: '2026-07-15T12:30:00Z',
                labels: ['needs_review'],
              },
              {
                id: '44444444-4444-4444-4444-444444444444',
                record_type: 'email_thread',
                inbox_id: '22222222-2222-2222-2222-222222222222',
                subject: 'Support request',
                preview: null,
                message_count: 1,
                unread_count: 0,
                last_message_id: '66666666-6666-6666-6666-666666666666',
                last_message_at: '2026-07-15T09:00:00Z',
                created_at: '2026-07-15T09:00:00Z',
                updated_at: '2026-07-15T09:00:00Z',
                labels: [],
              },
            ],
            meta: {
              page_size: 25,
              page_cursor:
                'MjAyNi0wNy0xNVQxMjozMDowMFp8MzMzMzMzMzMtMzMzMy0zMzMzLTMzMzMtMzMzMzMzMzMzMzMz',
            },
          },
        },
      },
    },
    401: EmailUnauthorizedResponseResponse,
    404: EmailNotFoundResponseResponse,
    422: ValidationErrorResponseResponse,
    503: {
      description: 'Inbound thread storage is temporarily unavailable.',
      content: {
        'application/json': {
          schema: EmailErrorResponseSchema,
          example: {
            errors: [
              {
                code: '10016',
                title: 'Service Unavailable',
                detail: 'Email threads are temporarily unavailable. Please try again later.',
              },
            ],
          },
        },
      },
    },
  },
})

