export const getEnterprisesEnterpriseIdReputationNumbersRoute = createRoute({
  method: 'get',
  path: '/enterprises/{enterprise_id}/reputation/numbers',
  tags: ['Reputation'],
  summary: 'List reputation-monitored phone numbers for an enterprise',
  description:
    'Paginated list of phone numbers registered for reputation monitoring under this enterprise. The response includes the latest reputation snapshot per number where one has been collected.',
  operationId: 'listReputationNumbers',
  request: {
    params: z.object({ enterprise_id: EnterpriseIdParamsSchema }),
    query: z.object({
      'page[number]': BcPageNumberParamsSchema,
      'page[size]': z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1).max(250),
        )
        .default(10)
        .exactOptional()
        .openapi({
          param: {
            name: 'page[size]',
            in: 'query',
            description:
              'Items per page. Default 10. Maximum 250; values above are clamped to 250.',
            required: false,
            schema: { type: 'integer', minimum: 1, maximum: 250, default: 10, example: 10 },
          },
          example: 10,
        }),
      'filter[phone_number][contains]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'filter[phone_number][contains]',
            in: 'query',
            required: false,
            description: 'Partial match on phone number. Must contain at least 5 digits.',
            schema: { type: 'string', example: '+16035551234' },
          },
          example: '+16035551234',
        }),
      'filter[phone_number][eq]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'filter[phone_number][eq]',
            in: 'query',
            required: false,
            description: 'Exact phone-number match (E.164).',
            schema: { type: 'string', example: '+16035551234' },
          },
          example: '+16035551234',
        }),
      'filter[source]': ReputationNumberSourceSchema.openapi({
        param: {
          name: 'filter[source]',
          in: 'query',
          required: false,
          description: 'Only numbers with this source.',
          schema: { $ref: '#/components/schemas/ReputationNumberSource' },
        },
      }).exactOptional(),
      'filter[ownership_status]': ReputationOwnershipStatusSchema.openapi({
        param: {
          name: 'filter[ownership_status]',
          in: 'query',
          required: false,
          description:
            'Only numbers with this ownership status. `removed` lists the numbers that were removed, each with its `removal_reason` and `removed_at`; removed numbers are not returned otherwise.',
          schema: { $ref: '#/components/schemas/ReputationOwnershipStatus' },
        },
      }).exactOptional(),
    }),
  },
  responses: {
    200: {
      description: 'Paginated list of numbers with reputation data.',
      content: { 'application/json': { schema: ReputationPhoneNumberListWithReputationSchema } },
    },
    401: NumberReputationGenericErrorResponseResponse,
    404: NumberReputationGenericErrorResponseResponse,
  },
})

