export const postExternalConnectionsIdUploadsRoute = createRoute({
  method: 'post',
  path: '/external_connections/{id}/uploads',
  tags: ['External Connections'],
  summary: 'Creates an Upload request',
  description:
    'Creates a new Upload request to Microsoft teams with the included phone numbers. Only one of civic_address_id or location_id must be provided, not both. The maximum allowed phone numbers for the numbers_ids array is 1000.',
  operationId: 'CreateExternalConnectionUpload',
  request: {
    params: z.object({ id: ExternalVoiceIntegrationsIdParamsSchema }),
    body: {
      description: 'Parameters that can be set when creating an Upload request.',
      content: { 'application/json': { schema: CreateExternalConnectionUploadRequestSchema } },
      required: true,
    },
  },
  responses: {
    202: {
      description:
        'Upload request accepted. Track progress via GET /external_connections/{id}/uploads/status, or per ticket via GET /external_connections/{id}/uploads/{ticket_id}.',
      content: {
        'application/json': {
          schema: z
            .object({
              success: z
                .boolean()
                .exactOptional()
                .openapi({ description: 'Describes wether or not the operation was successful' }),
              ticket_id: z
                .uuid()
                .exactOptional()
                .openapi({ description: 'Ticket id of the upload request' }),
            })
            .openapi({ title: 'Create Upload request Response', required: [] }),
          example: { success: true, ticket_id: '3fa85f64-5717-4562-b3fc-2c963f66afa6' },
        },
      },
    },
    401: { description: 'Unauthorized' },
    404: { description: 'Not found' },
    413: {
      description:
        'Payload too large. The maximum allowed phone numbers for the numbers_ids array is 1000.',
    },
    422: { description: 'Unprocessable Entity' },
    504: { description: 'Gateway Timeout' },
  },
})

