export const getIntegrationSecretsRoute = createRoute({
  method: 'get',
  path: '/integration_secrets',
  tags: ['Integration Secrets'],
  summary: 'List integration secrets',
  description: 'Retrieve a list of all integration secrets configured by the user.',
  operationId: 'list_integration_secrets',
  request: {
    query: z
      .looseObject({})
      .transform((val) => {
        const rest: [string, unknown][] = []
        const groups = new Map<string, Record<string, unknown>>()
        const group = (name: string) => {
          const found = groups.get(name)
          if (found !== undefined) return found
          const made: Record<string, unknown> = Object.create(null)
          groups.set(name, made)
          return made
        }
        const isGroup = (item: unknown): item is Record<string, unknown> =>
          typeof item === 'object' && item !== null && !Array.isArray(item)
        const lists = new WeakSet<object>()
        const isIndex = (part: string | undefined) => part !== undefined && /^\d*$/.test(part)
        const child = (target: Record<string, unknown>, key: string, asList: boolean) => {
          const held = target[key]
          if (isGroup(held)) return held
          const made: Record<string, unknown> = Object.create(null)
          if (asList) lists.add(made)
          target[key] = made
          return made
        }
        const set = (
          root: Record<string, unknown>,
          path: readonly string[],
          item: unknown,
        ): void => {
          const work: [Record<string, unknown>, number, unknown, boolean][] = [
            [root, 0, item, false],
          ]
          for (let job = work.pop(); job !== undefined; job = work.pop()) {
            const [target, at, value, split] = job
            const head = path[at]
            if (head === undefined) continue
            const next = path[at + 1]
            if (head === '') {
              if (!split && Array.isArray(value)) {
                for (let i = value.length - 1; i >= 0; i -= 1)
                  work.push([target, at, value[i], true])
                continue
              }
              const size = Object.keys(target).length
              if (next === undefined) {
                target[String(size)] = value
                continue
              }
              const free =
                next === ''
                  ? -1
                  : Object.values(target).findIndex((held) => isGroup(held) && !(next in held))
              work.push([
                child(target, String(free < 0 ? size : free), isIndex(next)),
                at + 1,
                value,
                false,
              ])
              continue
            }
            if (next === undefined) {
              target[head] = value
              continue
            }
            work.push([child(target, head, isIndex(next)), at + 1, value, false])
          }
        }
        const settle = (root: unknown): unknown => {
          if (!isGroup(root)) return root
          const found: [Record<string, unknown>, string, Record<string, unknown>][] = []
          const queue: Record<string, unknown>[] = [root]
          for (const node of queue) {
            for (const [key, inner] of Object.entries(node)) {
              if (isGroup(inner)) {
                found.push([node, key, inner])
                queue.push(inner)
              }
            }
          }
          const finish = (group: Record<string, unknown>): unknown =>
            lists.has(group)
              ? Object.entries(group)
                  .sort((a, b) => Number(a[0]) - Number(b[0]))
                  .map(([, inner]) => inner)
              : Object.assign(Object.create(null), group)
          for (const [parent, key, group] of found.reverse()) {
            parent[key] = finish(group)
          }
          return finish(root)
        }
        const deep: string[] = ['page', 'filter']
        for (const [key, item] of Object.entries(val)) {
          const match = /^([^\[\]]+)((?:\[[^\[\]]*\])+)$/.exec(key)
          const name = match?.[1]
          const path = match?.[2]
          if (name !== undefined && path !== undefined && deep.includes(name)) {
            const parts = path.slice(1, -1).split('][')
            set(group(name), parts, item)
            continue
          }
          rest.push([key, item])
        }
        return Object.fromEntries([
          ...rest,
          ...[...groups].map(([name, held]) => [name, settle(held)] as const),
        ])
      })
      .pipe(
        z.object({
          page: z
            .object({
              size: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional()
                .openapi({ title: 'Page Size', example: 25 }),
              number: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional()
                .openapi({ title: 'Page Number', example: 1 }),
            })
            .exactOptional()
            .openapi({
              param: {
                name: 'page',
                in: 'query',
                style: 'deepObject',
                explode: true,
                description:
                  'Consolidated page parameter (deepObject style). Originally: page[size], page[number]',
                schema: {
                  type: 'object',
                  properties: {
                    size: { type: 'integer', title: 'Page Size', example: 25 },
                    number: { type: 'integer', title: 'Page Number', example: 1 },
                  },
                },
                examples: {
                  'page[number]=1&page[size]=20': {
                    summary: 'First page with 20 results per page',
                    value: { number: 1, size: 20 },
                  },
                  'page[number]=2&page[size]=20': {
                    summary: 'Second page with 20 results per page',
                    value: { number: 2, size: 20 },
                  },
                  'page[number]=1&page[size]=50': {
                    summary: 'First page with 50 results per page',
                    value: { number: 1, size: 50 },
                  },
                },
                required: false,
              },
              required: [],
            }),
          filter: z
            .object({
              type: z
                .enum(['bearer', 'basic'])
                .exactOptional()
                .openapi({ title: 'Filter by type', example: 'bearer' }),
            })
            .exactOptional()
            .openapi({
              param: {
                name: 'filter',
                in: 'query',
                style: 'deepObject',
                explode: true,
                description:
                  'Consolidated filter parameter (deepObject style). Originally: filter[type]',
                schema: {
                  type: 'object',
                  properties: {
                    type: {
                      type: 'string',
                      title: 'Filter by type',
                      example: 'bearer',
                      enum: ['bearer', 'basic'],
                    },
                  },
                },
                examples: {
                  'filter[type]=bearer': {
                    summary: 'Filter results to only show bearer type secrets',
                    value: { type: 'bearer' },
                  },
                  'filter[type]=basic': {
                    summary: 'Filter results to only show basic authentication type secrets',
                    value: { type: 'basic' },
                  },
                },
                required: false,
              },
              required: [],
            }),
        }),
      ),
  },
  responses: {
    200: {
      description: 'Successful Response',
      content: { 'application/json': { schema: IntegrationSecretsListDataSchema } },
    },
    400: {
      description: 'Bad Request',
      content: {
        'application/json': {
          schema: IntegrationSecretsErrorResponseSchema,
          example: {
            errors: [
              {
                code: '10015',
                title: 'Bad Request',
                detail: 'The request failed because it was not well-formed.',
              },
            ],
          },
        },
      },
    },
  },
})

