export const getLegacyReportingUsageReportsMessagingRoute = createRoute({
  method: 'get',
  path: '/legacy/reporting/usage_reports/messaging',
  tags: ['MDR Usage Reports'],
  summary: 'List MDR usage reports',
  description: 'Fetch all previous requests for MDR usage reports. ',
  operationId: 'getMdrUsageReports',
  request: {
    query: z.object({
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().min(1),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            name: 'page',
            in: 'query',
            description: 'Page number',
            schema: { minimum: 1, type: 'integer', format: 'int32', default: 1 },
            required: false,
          },
        }),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().min(1).max(250),
        )
        .default(20)
        .exactOptional()
        .openapi({
          param: {
            name: 'per_page',
            in: 'query',
            description: 'Size of the page',
            schema: { maximum: 250, minimum: 1, type: 'integer', format: 'int32', default: 20 },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successful',
      content: {
        'application/json': { schema: StandardMdrGetUsageReportsResponseFfba4faa88Schema },
      },
    },
    400: {
      description: 'Bad Request',
      content: {
        'application/json': {
          schema: StandardErrorResponseFfba4faa88Schema,
          example: {
            errors: [
              {
                code: '10015',
                title: 'Bad Request',
                detail: 'The request failed because it was not well-formed.',
              },
            ],
          },
        },
      },
    },
  },
})

