export const getLlmTokenGatewaySpendEventsRoute = createRoute({
  method: 'get',
  path: '/llm_token_gateway/spend/events',
  tags: ['AI Gateway'],
  summary: 'List gateway spend events',
  description:
    'Return request-level usage history for the authenticated account. Supply both UTC dates or neither; omitting both returns the previous full UTC day. Dates use a half-open range [start_date, end_date) of at most 31 days. Cost reflects budget reference rates, not invoice charges. Unknown spend is excluded and reported separately. The report snapshot supports at most 10,000 matching requests, independently of page size. Exceeding this bound returns HTTP 503 without partial results. Narrow the date range or resource filters before retrying. A failed report must not be interpreted as zero usage. Request tags can filter either report and metadata:<key> can group the summary.',
  operationId: 'get_ai_gateway_spend_events',
  request: {
    query: z
      .looseObject({})
      .transform((val) => {
        const rest: [string, unknown][] = []
        const groups = new Map<string, Record<string, unknown>>()
        const group = (name: string) => {
          const found = groups.get(name)
          if (found !== undefined) return found
          const made: Record<string, unknown> = Object.create(null)
          groups.set(name, made)
          return made
        }
        const isGroup = (item: unknown): item is Record<string, unknown> =>
          typeof item === 'object' && item !== null && !Array.isArray(item)
        const lists = new WeakSet<object>()
        const isIndex = (part: string | undefined) => part !== undefined && /^\d*$/.test(part)
        const child = (target: Record<string, unknown>, key: string, asList: boolean) => {
          const held = target[key]
          if (isGroup(held)) return held
          const made: Record<string, unknown> = Object.create(null)
          if (asList) lists.add(made)
          target[key] = made
          return made
        }
        const set = (
          root: Record<string, unknown>,
          path: readonly string[],
          item: unknown,
        ): void => {
          const work: [Record<string, unknown>, number, unknown, boolean][] = [
            [root, 0, item, false],
          ]
          for (let job = work.pop(); job !== undefined; job = work.pop()) {
            const [target, at, value, split] = job
            const head = path[at]
            if (head === undefined) continue
            const next = path[at + 1]
            if (head === '') {
              if (!split && Array.isArray(value)) {
                for (let i = value.length - 1; i >= 0; i -= 1)
                  work.push([target, at, value[i], true])
                continue
              }
              const size = Object.keys(target).length
              if (next === undefined) {
                target[String(size)] = value
                continue
              }
              const free =
                next === ''
                  ? -1
                  : Object.values(target).findIndex((held) => isGroup(held) && !(next in held))
              work.push([
                child(target, String(free < 0 ? size : free), isIndex(next)),
                at + 1,
                value,
                false,
              ])
              continue
            }
            if (next === undefined) {
              target[head] = value
              continue
            }
            work.push([child(target, head, isIndex(next)), at + 1, value, false])
          }
        }
        const settle = (root: unknown): unknown => {
          if (!isGroup(root)) return root
          const found: [Record<string, unknown>, string, Record<string, unknown>][] = []
          const queue: Record<string, unknown>[] = [root]
          for (const node of queue) {
            for (const [key, inner] of Object.entries(node)) {
              if (isGroup(inner)) {
                found.push([node, key, inner])
                queue.push(inner)
              }
            }
          }
          const finish = (group: Record<string, unknown>): unknown =>
            lists.has(group)
              ? Object.entries(group)
                  .sort((a, b) => Number(a[0]) - Number(b[0]))
                  .map(([, inner]) => inner)
              : Object.assign(Object.create(null), group)
          for (const [parent, key, group] of found.reverse()) {
            parent[key] = finish(group)
          }
          return finish(root)
        }
        const deep: string[] = ['metadata']
        for (const [key, item] of Object.entries(val)) {
          const match = /^([^\[\]]+)((?:\[[^\[\]]*\])+)$/.exec(key)
          const name = match?.[1]
          const path = match?.[2]
          if (name !== undefined && path !== undefined && deep.includes(name)) {
            const parts = path.slice(1, -1).split('][')
            set(group(name), parts, item)
            continue
          }
          rest.push([key, item])
        }
        return Object.fromEntries([
          ...rest,
          ...[...groups].map(([name, held]) => [name, settle(held)] as const),
        ])
      })
      .pipe(
        z.object({
          'page[number]': AiGatewaySpendPageNumberParamsSchema,
          'page[size]': AiGatewaySpendPageSizeParamsSchema,
          'page[snapshot]': SnapshotParamsSchema,
          start_date: z.iso
            .date()
            .exactOptional()
            .openapi({
              param: {
                name: 'start_date',
                in: 'query',
                required: false,
                schema: { type: 'string', format: 'date' },
                description: '',
              },
            }),
          end_date: z.iso
            .date()
            .exactOptional()
            .openapi({
              param: {
                name: 'end_date',
                in: 'query',
                required: false,
                schema: { type: 'string', format: 'date' },
                description: '',
              },
            }),
          token_group_id: z
            .uuid()
            .exactOptional()
            .openapi({
              param: {
                name: 'token_group_id',
                in: 'query',
                required: false,
                schema: { type: 'string', format: 'uuid' },
                description: '',
              },
            }),
          token_user_id: z
            .uuid()
            .exactOptional()
            .openapi({
              param: {
                name: 'token_user_id',
                in: 'query',
                required: false,
                schema: { type: 'string', format: 'uuid' },
                description: '',
              },
            }),
          token_key_id: z
            .uuid()
            .exactOptional()
            .openapi({
              param: {
                name: 'token_key_id',
                in: 'query',
                required: false,
                schema: { type: 'string', format: 'uuid' },
                description: '',
              },
            }),
          end_user_id: z
            .string()
            .regex(/^[^\u0000-\u001f\u007f]+$/)
            .min(1)
            .max(256)
            .exactOptional()
            .openapi({
              param: {
                name: 'end_user_id',
                in: 'query',
                required: false,
                schema: {
                  type: 'string',
                  minLength: 1,
                  maxLength: 256,
                  pattern: '^[^\\u0000-\\u001f\\u007f]+$',
                },
                description: '',
              },
            }),
          metadata: z
            .record(
              z.string(),
              z
                .string()
                .regex(/^[^\u0000-\u001f\u007f]+$/)
                .min(1)
                .max(256),
            )
            .refine((val) => Object.keys(val).length <= 5)
            .superRefine((o, ctx) => {
              const regex = new RegExp('^[A-Za-z0-9][A-Za-z0-9_.-]{0,63}$')
              for (const k of Object.keys(o)) {
                if (!regex.test(k)) {
                  ctx.addIssue({ code: 'custom', path: [k] })
                }
              }
            })
            .exactOptional()
            .openapi({
              param: {
                name: 'metadata',
                in: 'query',
                required: false,
                style: 'deepObject',
                explode: true,
                schema: {
                  type: 'object',
                  maxProperties: 5,
                  propertyNames: { pattern: '^[A-Za-z0-9][A-Za-z0-9_.-]{0,63}$' },
                  additionalProperties: {
                    type: 'string',
                    minLength: 1,
                    maxLength: 256,
                    pattern: '^[^\\u0000-\\u001f\\u007f]+$',
                  },
                },
                description:
                  'Request tag filters as metadata[<key>]=<value>, at most 5, combined with AND. A value matches the tag\'s text form exactly (booleans as true/false, integers in decimal), so metadata[flag]=true matches both boolean true and the string "true". Keys are case-sensitive; reserved-prefix keys are rejected. Unindexed: bounded by the account, the date range and the report timeout.',
              },
            }),
        }),
      ),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: SpendEventsSchema,
          example: {
            data: [],
            meta: {
              page_number: 1,
              page_size: 20,
              has_more: false,
              snapshot: '9b7e4a10-3c2d-4f5e-8a6b-1d2c3e4f5a60',
            },
          },
        },
      },
      headers: z.object({
        'X-Request-ID': z
          .uuid()
          .exactOptional()
          .openapi({ description: 'Server-generated correlation ID.', param: { required: false } }),
        'Cache-Control': z
          .literal('no-store')
          .exactOptional()
          .openapi({
            description: 'All API responses; application cache is server-side only.',
            param: { required: false },
          }),
      }),
    },
    400: AiGatewaySpendGatewayError400Response,
    401: GatewayError401Response,
    403: GatewayError403Response,
    404: GatewayError404Response,
    409: AiGatewaySpendGatewayError409Response,
    412: GatewayError412Response,
    428: GatewayError428Response,
    429: GatewayError429Response,
    502: GatewayError502Response,
    503: AiGatewaySpendGatewayError503Response,
    504: GatewayError504Response,
  },
  security: [{ telnyxApiKey: [] }],
})

