export const getLlmTokenGatewayUsageExportRoute = createRoute({
  method: 'get',
  path: '/llm_token_gateway/usage/export',
  tags: ['AI Gateway'],
  summary: 'Export gateway usage',
  description:
    'Durable, replayable, content-free usage export for customer pipelines. Requires the dedicated llm_token_gateway.usage_export.read V2 action; spend.read and usage.read do not grant it. Records are inference.request (one per immutable ledger revision; a correction adds a new id with supersedes, keep the highest revision per request_id) and guardrail.evaluation (one per guardrail event, including blocked prompts with no inference record; correlate on request_id). Delivery is at least once in commit order: deduplicate on id. Records appear after settlement and after every older database transaction has finished (meta.horizon_lag_seconds); keep polling with next_cursor, which is always returned and is reusable after has_more is false. After a logical database restore, restart from start_time and deduplicate on id; a cursor from before it may return 409 cursor_expired (no Retry-After). Retention promise 30 days. No prompts, responses, provider credentials, supplier or customer rates. Gateway reference/enforcement usage, not invoice truth or BYOK provider charges.',
  operationId: 'exportGatewayUsage',
  request: {
    query: z.object({
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1).max(1000),
        )
        .default(500)
        .exactOptional()
        .openapi({
          param: {
            name: 'limit',
            in: 'query',
            required: false,
            schema: { type: 'integer', minimum: 1, maximum: 1000, default: 500 },
            description: '',
          },
        }),
      cursor: z
        .string()
        .regex(/^[A-Za-z0-9_-]+$/)
        .min(1)
        .max(512)
        .exactOptional()
        .openapi({
          param: {
            name: 'cursor',
            in: 'query',
            required: false,
            schema: { type: 'string', minLength: 1, maxLength: 512, pattern: '^[A-Za-z0-9_-]+$' },
            description:
              'Opaque next_cursor from a previous page; not combinable with start_time. Bound to the requested types; the account always comes from the credential.',
          },
        }),
      start_time: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            name: 'start_time',
            in: 'query',
            required: false,
            schema: { type: 'string', format: 'date-time' },
            description:
              'First page only: RFC 3339 with offset, at most 30 days ago and not in the future; default now - 24h.',
          },
        }),
      types: z
        .string()
        .regex(/^[a-z.]+(,[a-z.]+)?$/)
        .exactOptional()
        .openapi({
          param: {
            name: 'types',
            in: 'query',
            required: false,
            schema: { type: 'string', pattern: '^[a-z.]+(,[a-z.]+)?$' },
            description:
              'Comma-separated subset of inference.request,guardrail.evaluation; default both.',
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: UsageExportPageSchema,
          example: {
            data: [],
            meta: { next_cursor: 'synthetic_cursor', has_more: false, horizon_lag_seconds: 0 },
          },
        },
      },
      headers: z.object({
        'X-Request-ID': z
          .uuid()
          .exactOptional()
          .openapi({ description: 'Server-generated correlation ID.', param: { required: false } }),
        'Cache-Control': z
          .literal('no-store')
          .exactOptional()
          .openapi({
            description: 'All API responses; application cache is server-side only.',
            param: { required: false },
          }),
      }),
    },
    400: AiGatewayGatewayError400Response,
    401: GatewayError401Response,
    403: GatewayError403Response,
    404: GatewayError404Response,
    409: GatewayError40911Response,
    412: GatewayError412Response,
    428: GatewayError428Response,
    429: GatewayError429Response,
    502: GatewayError502Response,
    503: UsageExportUnavailableResponse,
    504: GatewayError504Response,
  },
  security: [{ telnyxApiKey: [] }],
})

export const getLlmTokenGatewayUsageSummaryRoute = createRoute({
  method: 'get',
  path: '/llm_token_gateway/usage/summary',
  tags: ['AI Gateway'],
  summary: 'Get gateway usage summary',
  description:
    'Gateway reference/enforcement usage, not invoice truth or BYOK provider charges. Requires the dedicated llm_token_gateway.usage.read V2 action for combined spend and guardrail reporting; existing spend.read and guardrail_events.read grants do not grant this endpoint. All totals, UTC daily buckets, models and latest 20 guardrail events share one database snapshot. UTC half-open dates, at most 31 days. Zero-filled days; at most 1000 models (503 rather than truncation on overflow/timeout). Known tokens sum independently known categories across latest attempt evidence, including corrections; unknown spend is excluded and unknown_requests/reserved_spend remain explicit. Guardrail counts count events, not distinct requests. No raw spend events, prompts or secrets. This read-only report creates no pagination snapshot and accepts no pagination parameters.',
  operationId: 'gateway_usage_summary',
  request: {
    query: z
      .looseObject({})
      .transform((val) => {
        const rest: [string, unknown][] = []
        const groups = new Map<string, Record<string, unknown>>()
        const group = (name: string) => {
          const found = groups.get(name)
          if (found !== undefined) return found
          const made: Record<string, unknown> = Object.create(null)
          groups.set(name, made)
          return made
        }
        const isGroup = (item: unknown): item is Record<string, unknown> =>
          typeof item === 'object' && item !== null && !Array.isArray(item)
        const lists = new WeakSet<object>()
        const isIndex = (part: string | undefined) => part !== undefined && /^\d*$/.test(part)
        const child = (target: Record<string, unknown>, key: string, asList: boolean) => {
          const held = target[key]
          if (isGroup(held)) return held
          const made: Record<string, unknown> = Object.create(null)
          if (asList) lists.add(made)
          target[key] = made
          return made
        }
        const set = (
          root: Record<string, unknown>,
          path: readonly string[],
          item: unknown,
        ): void => {
          const work: [Record<string, unknown>, number, unknown, boolean][] = [
            [root, 0, item, false],
          ]
          for (let job = work.pop(); job !== undefined; job = work.pop()) {
            const [target, at, value, split] = job
            const head = path[at]
            if (head === undefined) continue
            const next = path[at + 1]
            if (head === '') {
              if (!split && Array.isArray(value)) {
                for (let i = value.length - 1; i >= 0; i -= 1)
                  work.push([target, at, value[i], true])
                continue
              }
              const size = Object.keys(target).length
              if (next === undefined) {
                target[String(size)] = value
                continue
              }
              const free =
                next === ''
                  ? -1
                  : Object.values(target).findIndex((held) => isGroup(held) && !(next in held))
              work.push([
                child(target, String(free < 0 ? size : free), isIndex(next)),
                at + 1,
                value,
                false,
              ])
              continue
            }
            if (next === undefined) {
              target[head] = value
              continue
            }
            work.push([child(target, head, isIndex(next)), at + 1, value, false])
          }
        }
        const settle = (root: unknown): unknown => {
          if (!isGroup(root)) return root
          const found: [Record<string, unknown>, string, Record<string, unknown>][] = []
          const queue: Record<string, unknown>[] = [root]
          for (const node of queue) {
            for (const [key, inner] of Object.entries(node)) {
              if (isGroup(inner)) {
                found.push([node, key, inner])
                queue.push(inner)
              }
            }
          }
          const finish = (group: Record<string, unknown>): unknown =>
            lists.has(group)
              ? Object.entries(group)
                  .sort((a, b) => Number(a[0]) - Number(b[0]))
                  .map(([, inner]) => inner)
              : Object.assign(Object.create(null), group)
          for (const [parent, key, group] of found.reverse()) {
            parent[key] = finish(group)
          }
          return finish(root)
        }
        const deep: string[] = ['metadata']
        for (const [key, item] of Object.entries(val)) {
          const match = /^([^\[\]]+)((?:\[[^\[\]]*\])+)$/.exec(key)
          const name = match?.[1]
          const path = match?.[2]
          if (name !== undefined && path !== undefined && deep.includes(name)) {
            const parts = path.slice(1, -1).split('][')
            set(group(name), parts, item)
            continue
          }
          rest.push([key, item])
        }
        return Object.fromEntries([
          ...rest,
          ...[...groups].map(([name, held]) => [name, settle(held)] as const),
        ])
      })
      .pipe(
        z.object({
          token_group_id: z
            .uuid()
            .openapi({
              param: {
                name: 'token_group_id',
                in: 'query',
                required: true,
                schema: { type: 'string', format: 'uuid' },
                description: '',
              },
            }),
          start_date: z.iso
            .date()
            .openapi({
              param: {
                name: 'start_date',
                in: 'query',
                required: true,
                schema: { type: 'string', format: 'date' },
                description: '',
              },
            }),
          end_date: z.iso
            .date()
            .openapi({
              param: {
                name: 'end_date',
                in: 'query',
                required: true,
                schema: { type: 'string', format: 'date' },
                description: '',
              },
            }),
          metadata: z
            .record(
              z.string(),
              z
                .string()
                .regex(/^[^\u0000-\u001f\u007f]+$/)
                .min(1)
                .max(256),
            )
            .refine((val) => Object.keys(val).length <= 5)
            .superRefine((o, ctx) => {
              const regex = new RegExp('^[A-Za-z0-9][A-Za-z0-9_.-]{0,63}$')
              for (const k of Object.keys(o)) {
                if (!regex.test(k)) {
                  ctx.addIssue({ code: 'custom', path: [k] })
                }
              }
            })
            .exactOptional()
            .openapi({
              param: {
                name: 'metadata',
                in: 'query',
                required: false,
                style: 'deepObject',
                explode: true,
                schema: {
                  type: 'object',
                  maxProperties: 5,
                  propertyNames: { pattern: '^[A-Za-z0-9][A-Za-z0-9_.-]{0,63}$' },
                  additionalProperties: {
                    type: 'string',
                    minLength: 1,
                    maxLength: 256,
                    pattern: '^[^\\u0000-\\u001f\\u007f]+$',
                  },
                },
                description:
                  'Request tag filters as metadata[<key>]=<value>, at most 5, combined with AND. A value matches the tag\'s text form exactly (booleans as true/false, integers in decimal), so metadata[flag]=true matches both boolean true and the string "true". Keys are case-sensitive; reserved-prefix keys are rejected. Unindexed: bounded by the account, the date range and the report timeout.',
              },
            }),
        }),
      ),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: GatewayUsageSchema,
          example: {
            data: {
              totals: {
                requests: 2,
                input_tokens: 120,
                output_tokens: 30,
                unknown_requests: 1,
                cache_hits: 0,
                succeeded_requests: 1,
                failed_requests: 0,
                partial_requests: 0,
                spend: 0.00045,
                reserved_spend: 0.01,
              },
              by_day: [
                {
                  date: '2026-09-01',
                  requests: 2,
                  input_tokens: 120,
                  output_tokens: 30,
                  unknown_requests: 1,
                  cache_hits: 0,
                  succeeded_requests: 1,
                  failed_requests: 0,
                  partial_requests: 0,
                  spend: 0.00045,
                  reserved_spend: 0.01,
                },
              ],
              by_model: [
                {
                  model: 'Qwen/Qwen3-235B-A22B',
                  requests: 2,
                  input_tokens: 120,
                  output_tokens: 30,
                  unknown_requests: 1,
                  cache_hits: 0,
                  succeeded_requests: 1,
                  failed_requests: 0,
                  partial_requests: 0,
                  spend: 0.00045,
                  reserved_spend: 0.01,
                },
              ],
              guardrails: { blocked_events: 0, flagged_events: 0, recent_events: [] },
            },
            meta: {
              token_group_id: '11111111-1111-4111-8111-111111111111',
              start_date: '2026-09-01',
              end_date: '2026-09-02',
              metadata: {},
            },
          },
        },
      },
      headers: z.object({
        'X-Request-ID': z
          .uuid()
          .exactOptional()
          .openapi({ description: 'Server-generated correlation ID.', param: { required: false } }),
        'Cache-Control': z
          .literal('no-store')
          .exactOptional()
          .openapi({
            description: 'All API responses; application cache is server-side only.',
            param: { required: false },
          }),
      }),
    },
    400: AiGatewayGatewayError400Response,
    401: GatewayError401Response,
    403: GatewayError403Response,
    404: GatewayError404Response,
    409: GatewayError409Response,
    412: GatewayError412Response,
    428: GatewayError428Response,
    429: GatewayError429Response,
    502: GatewayError502Response,
    503: UsageSummaryUnavailableResponse,
    504: GatewayError504Response,
  },
  security: [{ telnyxApiKey: [] }],
})

export const postMachinePaymentsAccountCreditRoute = createRoute({
  method: 'post',
  path: '/machine-payments/account-credit',
  tags: ['Machine Payments'],
  summary: 'Create a machine payment account credit',
  description:
    "Creates an account credit using the Machine Payment Protocol (MPP), an HTTP-402 payment flow for machines and agents.\n\nThe flow has two steps. First, send an authenticated request with the `amount_usd` to credit; the response is `402 Payment Required` with one or more payment challenges (for example separate Tempo and Stripe challenges) in the `WWW-Authenticate` header. Second, retry the request with an `Authorization: Payment ...` credential constructed from the challenge; on success the response includes the credited transaction and a `Payment-Receipt` header.\n\nThe credited account is never chosen by the request body: the initial request credits the account of the authenticated user, and a paid retry credits the account bound to the verified payment credential. The amount must be within the configured bounds (by default between 5.00 and 500.00 USD).\n\nSuccessful paid retries are idempotent — when Rails reaches its duplicate-transaction lookup for an already-recorded payment, it returns the existing transaction with `created: false` instead of crediting the account again. This deduplication applies to successful fulfillment: re-sending the same Stripe credential may instead be rejected by the upstream provider as an idempotent replay and return `402 Payment Required` rather than the existing transaction.\n\n> **Warning: the payment credential is bound to a specific Telnyx account ID.** A payment is captured before the bound account is validated. If the credential names an account that is missing, suspended, blocked, cancelled, dormant, or ineligible for the tier, the payment is captured but **no account is credited**. If the credential names a different but eligible account, that account is credited — the service does not compare it against the payer's account. There is **no automatic refund**: if the captured payment does not credit the intended account, contact Telnyx support for remediation.",
  operationId: 'createMachinePaymentAccountCredit',
  request: {
    body: {
      content: {
        'application/json': {
          schema: MachinePaymentAccountCreditRequestSchema,
          example: { amount_usd: '10.00' },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description:
        'Successful duplicate paid retry — the existing account-credit transaction is returned and the account is not credited again. This applies when Rails reaches its duplicate-transaction lookup; re-sending the same Stripe credential may instead be rejected by the upstream provider as an idempotent replay and return `402 Payment Required`.',
      content: {
        'application/json': {
          schema: MachinePaymentAccountCreditResponseSchema,
          example: {
            data: {
              id: 'de06811a-2e43-4561-af5a-7d0a26e20bbb',
              record_type: 'machine_payment_account_credit',
              account_id: '123456789',
              amount: '10.00',
              currency: 'USD',
              payment_source: 'machine_payment',
              provider: 'stripe',
              payment_method: 'stripe_spt',
              payment_intent_id: 'pi_3OrJx2eZvKYlo2C1234abcd',
              receipt_reference: 'pi_3OrJx2eZvKYlo2C1234abcd',
              mpp_resource: 'telnyx:account-credit:123456789:usd:10.00',
              status: 'settled',
              created: false,
              created_at: '2026-08-12T15:00:00Z',
            },
          },
        },
      },
      headers: z.object({ 'Payment-Receipt': PaymentReceiptHeaderSchema }),
    },
    201: {
      description: 'Account credit created from a verified machine payment',
      content: {
        'application/json': {
          schema: MachinePaymentAccountCreditResponseSchema,
          example: {
            data: {
              id: 'de06811a-2e43-4561-af5a-7d0a26e20bbb',
              record_type: 'machine_payment_account_credit',
              account_id: '123456789',
              amount: '10.00',
              currency: 'USD',
              payment_source: 'machine_payment',
              provider: 'stripe',
              payment_method: 'stripe_spt',
              payment_intent_id: 'pi_3OrJx2eZvKYlo2C1234abcd',
              receipt_reference: 'pi_3OrJx2eZvKYlo2C1234abcd',
              mpp_resource: 'telnyx:account-credit:123456789:usd:10.00',
              status: 'settled',
              created: true,
              created_at: '2026-08-12T15:00:00Z',
            },
          },
        },
      },
      headers: z.object({ 'Payment-Receipt': PaymentReceiptHeaderSchema }),
    },
    400: {
      description:
        'Bad request — proxied verbatim from the upstream machine payment service when it rejects the request: a malformed or undeserializable `Authorization: Payment ...` credential, a payment credential whose amount violates the upstream amount policy, or a request that fails upstream schema validation. The body is the upstream singular `error` envelope, not the standard Telnyx `errors` array.',
      content: {
        'application/json': {
          schema: MachinePaymentUpstreamErrorSchema,
          examples: {
            'invalid-payment-credential': {
              summary: 'Malformed or undeserializable Payment credential',
              value: { error: 'Invalid Payment authorization credential' },
            },
            'amount-policy': {
              summary: 'Credential amount outside the upstream amount policy',
              value: { error: 'amount_usd must be at least 5.00' },
            },
          },
        },
      },
    },
    401: {
      description:
        'Unauthorized — the request carried neither valid Telnyx API credentials nor an `Authorization: Payment ...` credential',
      content: {
        'application/json': {
          schema: MachinePaymentsErrorResponseSchema,
          example: {
            errors: [
              {
                code: '10009',
                title: 'Authentication failed',
                detail:
                  'The required authentication headers were either invalid or not included in the request.',
              },
            ],
          },
        },
      },
    },
    402: {
      description:
        'Payment required. One or more Machine Payment Protocol challenges (for example separate Tempo and Stripe challenges) are returned in the `WWW-Authenticate` header. Construct a payment credential from a challenge and retry the request with an `Authorization: Payment ...` header.',
      headers: z.object({ 'WWW-Authenticate': WWWAuthenticateChallengeHeaderSchema }),
    },
    403: {
      description:
        'Forbidden — machine payments are not enabled for the account, the account tier is ineligible, the account is suspended, or the request origin is not permitted. Note: when the account is suspended the failure is returned via `render_failure` as `{"success": false, "message": "You must verify your identity before you may perform this action.", "reasons": []}` rather than the standard `errors` envelope.',
      content: {
        'application/json': {
          schema: z.xor([
            MachinePaymentsErrorResponseSchema,
            MachinePaymentSuspendedAccountFailureSchema,
          ]),
          examples: {
            'machine-payments-disabled': {
              summary: 'Machine payments not enabled, tier ineligible, or origin not permitted',
              value: { errors: [{ detail: 'Machine payments are not currently enabled' }] },
            },
            'suspended-account': {
              summary: 'Suspended account',
              value: {
                success: false,
                message: 'You must verify your identity before you may perform this action.',
                reasons: [],
              },
            },
          },
        },
      },
    },
    404: {
      description:
        'Not found — proxied verbatim from the upstream machine payment service when the machine payment provider is disabled. The body is the upstream singular `error` envelope, not the standard Telnyx `errors` array.',
      content: {
        'application/json': {
          schema: MachinePaymentUpstreamErrorSchema,
          example: { error: 'Not found' },
        },
      },
    },
    409: {
      description:
        'Conflict — the payment maps to an already-recorded account credit with different fulfillment metadata, so the account is not credited again',
      content: {
        'application/json': {
          schema: MachinePaymentsErrorResponseSchema,
          example: {
            errors: [
              { detail: 'machine payment account credit conflicts with existing transaction' },
            ],
          },
        },
      },
    },
    422: {
      description:
        'Unprocessable entity — missing or invalid `amount_usd`, or the request fails account-credit policy checks',
      content: {
        'application/json': {
          schema: MachinePaymentsErrorResponseSchema,
          example: {
            errors: [
              {
                code: '10027',
                title: 'Invalid request',
                detail: 'amount_usd must be at least 5.00',
              },
            ],
          },
        },
      },
    },
    502: {
      description:
        'Bad gateway — the upstream machine payment service failed to process the request. Other upstream failure statuses (for example 404 when the machine payment provider is disabled, or 400 for schema validation failures) may be proxied verbatim to the client.',
      content: {
        'application/json': {
          schema: MachinePaymentsErrorResponseSchema,
          example: { errors: [{ detail: 'Machine payment service failed' }] },
        },
      },
    },
  },
  security: [{ bearerAuth: [] }, { Payment: [] }],
})

export const getManagedAccountsRoute = createRoute({
  method: 'get',
  path: '/managed_accounts',
  tags: ['Managed Accounts'],
  summary: 'Lists accounts managed by the current user.',
  description:
    'Lists the accounts managed by the current user. Users need to be explictly approved by Telnyx in order to become manager accounts.',
  operationId: 'ListManagedAccounts',
  request: {
    query: z
      .looseObject({})
      .transform((val) => {
        const rest: [string, unknown][] = []
        const groups = new Map<string, Record<string, unknown>>()
        const group = (name: string) => {
          const found = groups.get(name)
          if (found !== undefined) return found
          const made: Record<string, unknown> = Object.create(null)
          groups.set(name, made)
          return made
        }
        const isGroup = (item: unknown): item is Record<string, unknown> =>
          typeof item === 'object' && item !== null && !Array.isArray(item)
        const lists = new WeakSet<object>()
        const isIndex = (part: string | undefined) => part !== undefined && /^\d*$/.test(part)
        const child = (target: Record<string, unknown>, key: string, asList: boolean) => {
          const held = target[key]
          if (isGroup(held)) return held
          const made: Record<string, unknown> = Object.create(null)
          if (asList) lists.add(made)
          target[key] = made
          return made
        }
        const set = (
          root: Record<string, unknown>,
          path: readonly string[],
          item: unknown,
        ): void => {
          const work: [Record<string, unknown>, number, unknown, boolean][] = [
            [root, 0, item, false],
          ]
          for (let job = work.pop(); job !== undefined; job = work.pop()) {
            const [target, at, value, split] = job
            const head = path[at]
            if (head === undefined) continue
            const next = path[at + 1]
            if (head === '') {
              if (!split && Array.isArray(value)) {
                for (let i = value.length - 1; i >= 0; i -= 1)
                  work.push([target, at, value[i], true])
                continue
              }
              const size = Object.keys(target).length
              if (next === undefined) {
                target[String(size)] = value
                continue
              }
              const free =
                next === ''
                  ? -1
                  : Object.values(target).findIndex((held) => isGroup(held) && !(next in held))
              work.push([
                child(target, String(free < 0 ? size : free), isIndex(next)),
                at + 1,
                value,
                false,
              ])
              continue
            }
            if (next === undefined) {
              target[head] = value
              continue
            }
            work.push([child(target, head, isIndex(next)), at + 1, value, false])
          }
        }
        const settle = (root: unknown): unknown => {
          if (!isGroup(root)) return root
          const found: [Record<string, unknown>, string, Record<string, unknown>][] = []
          const queue: Record<string, unknown>[] = [root]
          for (const node of queue) {
            for (const [key, inner] of Object.entries(node)) {
              if (isGroup(inner)) {
                found.push([node, key, inner])
                queue.push(inner)
              }
            }
          }
          const finish = (group: Record<string, unknown>): unknown =>
            lists.has(group)
              ? Object.entries(group)
                  .sort((a, b) => Number(a[0]) - Number(b[0]))
                  .map(([, inner]) => inner)
              : Object.assign(Object.create(null), group)
          for (const [parent, key, group] of found.reverse()) {
            parent[key] = finish(group)
          }
          return finish(root)
        }
        const deep: string[] = ['filter', 'page']
        for (const [key, item] of Object.entries(val)) {
          const match = /^([^\[\]]+)((?:\[[^\[\]]*\])+)$/.exec(key)
          const name = match?.[1]
          const path = match?.[2]
          if (name !== undefined && path !== undefined && deep.includes(name)) {
            const parts = path.slice(1, -1).split('][')
            set(group(name), parts, item)
            continue
          }
          rest.push([key, item])
        }
        return Object.fromEntries([
          ...rest,
          ...[...groups].map(([name, held]) => [name, settle(held)] as const),
        ])
      })
      .pipe(
        z.object({
          filter: ManagedAccountsFilterConsolidatedParamsSchema,
          page: PageConsolidatedParamsSchema,
          sort: ManagedAccountsSortParamsSchema,
          include_cancelled_accounts: IncludeCancelledAccountsParamsSchema,
        }),
      ),
  },
  responses: {
    200: {
      description: 'Successful response with a list of managed accounts.',
      content: {
        'application/json': {
          schema: z
            .object({
              data: z.array(ManagedAccountMultiListingSchema).exactOptional(),
              meta: PaginationMetaSchema.exactOptional(),
            })
            .openapi({ required: [] }),
        },
      },
    },
    401: ManagedAccountsUnauthorizedResponseResponse,
  },
})

