export const postMediaRoute = createRoute({
  method: 'post',
  path: '/media',
  tags: ['Media Storage API'],
  summary: 'Upload media',
  description: 'Upload media file to Telnyx so it can be used with other Telnyx services',
  operationId: 'CreateMediaStorage',
  request: {
    body: {
      description: 'Upload media request',
      content: {
        'application/json': { schema: UploadMediaRequestSchema },
        'multipart/form-data': {
          schema: z
            .object({
              media: z
                .file()
                .openapi({
                  type: 'string',
                  format: 'binary',
                  description: 'The file you want to upload. The maximum allowed size is 20 MB.',
                }),
              ttl_secs: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional()
                .openapi({
                  description:
                    'The number of seconds after which the media resource will be deleted, defaults to 2 days. The maximum allowed vale is 630720000, which translates to 20 years.',
                  example: 86400,
                }),
              media_name: z
                .string()
                .exactOptional()
                .openapi({ description: 'The unique identifier of a file.', example: 'my_file' }),
            })
            .openapi({
              title: 'Upload media multipart request',
              required: ['media'],
              example: { media: 'string($binary)', ttl_secs: 86400, media_name: 'my-file' },
            }),
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'A response describing a media resource',
      content: {
        'application/json': {
          schema: z
            .object({ data: MediaResourceSchema.exactOptional() })
            .openapi({ title: 'Media resource response', required: [] }),
        },
      },
    },
    401: MediaStorageGenericErrorResponseResponse,
    422: MediaStorageGenericErrorResponseResponse,
    default: MediaStorageGenericErrorResponseResponse,
  },
})

