export const postMessagesAlphanumericSenderIdRoute = createRoute({
  method: 'post',
  path: '/messages/alphanumeric/sender/id',
  tags: ['Messages'],
  summary: 'Send a message using an alphanumeric sender ID',
  description: 'Send an SMS message using an alphanumeric sender ID. This is SMS only.',
  operationId: 'SendAlphanumericSenderIdMessage',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              from: z
                .string()
                .openapi({
                  description: "A valid alphanumeric sender ID on the user's account.",
                  example: 'MyCompany',
                }),
              to: ToNumberSchema.openapi({
                description: 'Receiving address (+E.164 formatted phone number).',
              }),
              text: z.string().openapi({ description: 'The message body.' }),
              messaging_profile_id: z
                .uuid()
                .openapi({ description: 'The messaging profile ID to use.' }),
              webhook_url: z
                .url()
                .nullable()
                .exactOptional()
                .openapi({ description: 'Callback URL for delivery status updates.' }),
              webhook_failover_url: z
                .url()
                .nullable()
                .exactOptional()
                .openapi({ description: 'Failover callback URL for delivery status updates.' }),
              use_profile_webhooks: z
                .boolean()
                .exactOptional()
                .openapi({ description: "If true, use the messaging profile's webhook settings." }),
            })
            .openapi({ required: ['from', 'to', 'text', 'messaging_profile_id'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Successful response with the sent message.',
      content: { 'application/json': { schema: OutboundMessageResponseSchema } },
    },
    400: MessagingBadRequestResponseResponse,
    401: MessagingUnauthorizedResponseResponse,
    422: MessagingUnprocessableEntityResponseResponse,
  },
})

