export const getMobileNetworkOperatorsRoute = createRoute({
  method: 'get',
  path: '/mobile_network_operators',
  tags: ['Mobile Network Operators'],
  summary: 'List mobile network operators',
  description:
    "Telnyx has a set of GSM mobile operators partners that are available through our mobile network roaming. This resource is entirely managed by Telnyx and may change over time. That means that this resource won't allow any write operations for it. Still, it's available so it can be used as a support resource that can be related to other resources or become a configuration option.",
  operationId: 'GetMobileNetworkOperators',
  request: {
    query: z
      .looseObject({})
      .transform((val) => {
        const rest: [string, unknown][] = []
        const groups = new Map<string, Record<string, unknown>>()
        const group = (name: string) => {
          const found = groups.get(name)
          if (found !== undefined) return found
          const made: Record<string, unknown> = Object.create(null)
          groups.set(name, made)
          return made
        }
        const spread = new Map<string, string[]>([
          ['name', ['filter']],
          ['country_code', ['filter']],
          ['mcc', ['filter']],
          ['mnc', ['filter']],
          ['tadig', ['filter']],
          ['network_preferences_enabled', ['filter']],
          ['number', ['page']],
          ['size', ['page']],
        ])
        for (const [key, item] of Object.entries(val)) {
          const owners = spread.get(key)
          if (owners !== undefined) {
            for (const owner of owners) {
              group(owner)[key] = item
            }
            continue
          }
          rest.push([key, item])
        }
        return Object.fromEntries([...rest, ...groups])
      })
      .pipe(
        z.object({
          filter: FilterMobileNetworkOperatorsConsolidatedParamsSchema,
          page: WirelessPageConsolidatedC5290d5308ParamsSchema,
        }),
      ),
  },
  responses: {
    200: {
      description: 'Successful Response',
      content: {
        'application/json': {
          schema: z
            .object({
              data: z.array(MobileNetworkOperatorSchema).exactOptional(),
              meta: PaginationMetaSchema.exactOptional(),
            })
            .openapi({ required: [] }),
        },
      },
    },
    401: { description: 'Unauthorized' },
    default: WirelessGenericErrorResponseC5290d5308Response,
  },
})

