export const getSimCardActionsRoute = createRoute({
  method: 'get',
  path: '/sim_card_actions',
  tags: ['SIM Card Actions'],
  summary: 'List SIM card actions',
  description:
    'This API lists a paginated collection of SIM card actions. It enables exploring a collection of existing asynchronous operations using specific filters.',
  operationId: 'ListSimCardActions',
  request: {
    query: z
      .looseObject({})
      .transform((val) => {
        const rest: [string, unknown][] = []
        const groups = new Map<string, Record<string, unknown>>()
        const group = (name: string) => {
          const found = groups.get(name)
          if (found !== undefined) return found
          const made: Record<string, unknown> = Object.create(null)
          groups.set(name, made)
          return made
        }
        const spread = new Map<string, string[]>([
          ['sim_card_id', ['filter']],
          ['status', ['filter']],
          ['bulk_sim_card_action_id', ['filter']],
          ['action_type', ['filter']],
          ['number', ['page']],
          ['size', ['page']],
        ])
        for (const [key, item] of Object.entries(val)) {
          const owners = spread.get(key)
          if (owners !== undefined) {
            for (const owner of owners) {
              group(owner)[key] = item
            }
            continue
          }
          rest.push([key, item])
        }
        return Object.fromEntries([...rest, ...groups])
      })
      .pipe(
        z.object({
          filter: FilterSIMCardActionsConsolidatedParamsSchema,
          page: WirelessPageConsolidatedC5290d5308ParamsSchema,
        }),
      ),
  },
  responses: {
    200: {
      description: 'Successful Response',
      content: {
        'application/json': {
          schema: z
            .object({
              data: z.array(WirelessSIMCardActionSchema).exactOptional(),
              meta: PaginationMetaSchema.exactOptional(),
            })
            .openapi({ required: [] }),
        },
      },
    },
    401: { description: 'Unauthorized' },
    default: WirelessGenericErrorResponseC5290d5308Response,
  },
})

