export const getSimCardsRoute = createRoute({
  method: 'get',
  path: '/sim_cards',
  tags: ['SIM Cards'],
  summary: 'Get all SIM cards',
  description: 'Get all SIM cards belonging to the user that match the given filters.',
  operationId: 'GetSimCards',
  request: {
    query: z
      .looseObject({})
      .transform((val) => {
        const rest: [string, unknown][] = []
        const groups = new Map<string, Record<string, unknown>>()
        const group = (name: string) => {
          const found = groups.get(name)
          if (found !== undefined) return found
          const made: Record<string, unknown> = Object.create(null)
          groups.set(name, made)
          return made
        }
        const spread = new Map<string, string[]>([
          ['iccid', ['filter']],
          ['msisdn', ['filter']],
          ['status', ['filter']],
          ['tags', ['filter']],
          ['number', ['page']],
          ['size', ['page']],
        ])
        for (const [key, item] of Object.entries(val)) {
          const owners = spread.get(key)
          if (owners !== undefined) {
            for (const owner of owners) {
              group(owner)[key] = item
            }
            continue
          }
          rest.push([key, item])
        }
        return Object.fromEntries([...rest, ...groups])
      })
      .pipe(
        z.object({
          filter: FilterSIMCardConsolidatedParamsSchema,
          page: WirelessPageConsolidatedC5290d5308ParamsSchema,
          include_sim_card_group: IncludeSIMCardGroupParamsSchema,
          'filter[sim_card_group_id]': FilterSIMCardGroupIdParamsSchema,
          sort: z
            .enum([
              'current_billing_period_consumed_data.amount',
              '-current_billing_period_consumed_data.amount',
            ])
            .exactOptional()
            .openapi({
              param: {
                name: 'sort',
                description:
                  'Sorts SIM cards by the given field. Defaults to ascending order unless field is prefixed with a minus sign.',
                in: 'query',
                required: false,
                example: '-current_billing_period_consumed_data.amount',
                schema: {
                  type: 'string',
                  enum: [
                    'current_billing_period_consumed_data.amount',
                    '-current_billing_period_consumed_data.amount',
                  ],
                },
              },
            }),
        }),
      ),
  },
  responses: {
    200: {
      description: 'Successful response',
      content: {
        'application/json': {
          schema: z
            .object({
              data: z.array(SimpleSIMCardSchema).exactOptional(),
              meta: PaginationMetaSchema.exactOptional(),
            })
            .openapi({ required: [] }),
        },
      },
    },
    401: { description: 'Unauthorized' },
    default: WirelessGenericErrorResponseC5290d5308Response,
  },
})

