export const getSipRegistrationStatusRoute = createRoute({
  method: 'get',
  path: '/sip_registration_status',
  tags: ['UAC Connections'],
  summary: 'SIP Registration Status',
  description:
    'Returns the live SIP registration status for a Telnyx endpoint: whether it is currently registered, when the current registration expires, and the last response Telnyx received from the registrar.\n\nThe endpoint supports three credential types, selected with the `credential_type` query parameter. Each type is keyed by a different identifier:\n\n| `credential_type` | Keyed by | Use case |\n| --- | --- | --- |\n| `uac_external_credential` | `connection_id` | A UAC (SIP attach) connection that registers to an external PBX. |\n| `telephony_credential` | `username` | An ephemeral, one-time-use telephony credential. |\n| `sip_credential_connection` | `username` | A traditional SIP credential connection that registers directly to Telnyx. |\n\nThe authenticated account is taken from your API key; you can only read the registration status of connections and credentials your account owns.',
  operationId: 'GetSipRegistrationStatus',
  request: {
    query: z.object({
      credential_type: z
        .enum(['uac_external_credential', 'telephony_credential', 'sip_credential_connection'])
        .openapi({
          param: {
            name: 'credential_type',
            in: 'query',
            required: true,
            description:
              'The kind of credential to look up. `uac_external_credential` is keyed by `connection_id`; `telephony_credential` and `sip_credential_connection` are keyed by `username`.',
            schema: {
              type: 'string',
              enum: [
                'uac_external_credential',
                'telephony_credential',
                'sip_credential_connection',
              ],
            },
          },
        }),
      connection_id: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'connection_id',
            in: 'query',
            required: false,
            description:
              'Identifier of the UAC connection to look up. Required when `credential_type` is `uac_external_credential`.',
            schema: { type: 'string' },
            example: '1234567890',
          },
        }),
      username: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'username',
            in: 'query',
            required: false,
            description:
              'SIP username to look up. Required when `credential_type` is `telephony_credential` or `sip_credential_connection`.',
            schema: { type: 'string' },
            example: 'useralice12345',
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Registration status payload',
      content: {
        'application/json': {
          schema: SipRegistrationStatusSchema,
          examples: {
            uac_credential: {
              summary: 'UAC external credential - registered',
              value: {
                connection_id: '1234567890',
                connection_name: 'FreePBX UAC 1002',
                credential_type: 'uac_external_credential',
                credential_username: 'useralice12345',
                registered: true,
                sip_registration_status: 'registered',
                last_registration_response: '200 OK',
                sip_registration_details: {
                  auth_retries: 0,
                  expires: 1780404431,
                  uptime: 1780401551699908,
                  next_action_at: 1780414482,
                  failures: 0,
                  sip_uri_user_host: '1002@192.0.2.10',
                },
              },
            },
            telephony_credential: {
              summary: 'Telephony credential - registered',
              value: {
                connection_id: '2845678901234567890',
                connection_name: 'Softphone Credential Connection',
                credential_type: 'telephony_credential',
                credential_username: 'gencredq7f3k9x2',
                registered: true,
                sip_registration_status: 'registered',
                last_registration_response: '200 OK',
                sip_registration_details: {
                  expires: 3600,
                  ua_ip: '192.0.2.55',
                  ua_port: 14934,
                  transport: 'UDP',
                  last_modified: '2026-06-15T11:23:13Z',
                },
              },
            },
            sip_credential_connection: {
              summary: 'SIP credential connection - registered',
              value: {
                connection_id: '1701773312243271678',
                connection_name: 'Office Softphone',
                credential_type: 'sip_credential_connection',
                credential_username: 'office_softphone_01',
                registered: true,
                sip_registration_status: 'registered',
                last_registration_response: '200 OK',
                sip_registration_details: {
                  expires: 3600,
                  ua_ip: '192.0.2.88',
                  ua_port: 5060,
                  transport: 'TCP',
                  last_modified: '2026-06-05T09:10:00Z',
                },
              },
            },
            not_registered: {
              summary: 'Not registered (trying)',
              value: {
                connection_id: '1701773312243271678',
                connection_name: 'Office Softphone',
                credential_type: 'sip_credential_connection',
                credential_username: 'office_softphone_01',
                registered: false,
                sip_registration_status: 'trying',
                last_registration_response: null,
                sip_registration_details: {},
              },
            },
            connection_disabled: {
              summary: 'Connection disabled',
              value: {
                connection_id: '1088210431736022026',
                connection_name: 'Disabled Connection',
                credential_type: 'sip_credential_connection',
                credential_username: 'disabled_user_01',
                registered: false,
                sip_registration_status: 'connection_disabled',
                last_registration_response: null,
                sip_registration_details: {},
              },
            },
          },
        },
      },
    },
    400: {
      description:
        'Missing or invalid query parameters. Returned when `credential_type` is unsupported, or when the identifier required for the chosen `credential_type` (`connection_id` or `username`) is missing.',
    },
    401: { description: 'Missing or invalid API key' },
    403: {
      description:
        'The connection or credential exists but is not owned by the authenticated account',
    },
    404: {
      description:
        'No connection or credential matches the supplied identifier, or it has no known registration',
    },
  },
})

