export const getSpeechToTextProvidersRoute = createRoute({
  method: 'get',
  path: '/speech-to-text/providers',
  tags: ['Speech To Text Capabilities'],
  summary: 'List supported STT providers',
  description:
    'Retrieve the canonical list of supported speech-to-text providers, models, accepted language codes, and the service types each model supports.\n\nService types:\n  * `streaming` — standalone WebSocket transcription via `/speech-to-text/transcription`.\n  * `file_based` — file-based transcription via `/ai/audio/transcriptions`.\n  * `in_call` — live call transcription via Call Control `transcription_start`.\n  * `ai_assistant` — STT configured on a Call Control AI Assistant via voice-assistant `TranscriptionConfig` (covers both live-streaming and non-streaming/batch models).\n\nUse this endpoint to discover which (provider, model) combinations are available for the surface you need, and which language codes each accepts. `auto` in a `languages` array indicates the provider performs language detection.',
  operationId: 'listSttProviders',
  request: {
    query: z.object({
      service_type: STTServiceTypeSchema.openapi({
        param: {
          name: 'service_type',
          in: 'query',
          required: false,
          description:
            'Filter to entries that support the given service type. For backward compatibility with the values that briefly shipped before the product-aligned rename, the legacy aliases `file_transcription`, `in_call_transcription`, and `ai_assistant_transcription` are silently accepted and normalized to `file_based`, `in_call`, and `ai_assistant` respectively. The response always emits the canonical (post-rename) values.',
          schema: { $ref: '#/components/schemas/STTServiceType' },
        },
      }).exactOptional(),
      provider: z
        .enum([
          'deepgram',
          'speechmatics',
          'assemblyai',
          'xai',
          'soniox',
          'parakeet',
          'humain',
          'reson8',
          'cohere',
          'azure',
          'openai',
          'google',
          'telnyx',
        ])
        .exactOptional()
        .openapi({
          param: {
            name: 'provider',
            in: 'query',
            required: false,
            description:
              'Filter to entries for a specific STT provider. The enum mirrors the providers advertised across the speech-to-text spec (including `google` and `telnyx`, which are accepted as WebSocket transcription engines). A provider that has no models currently registered for any service type will return an empty `data` array rather than an error.',
            schema: {
              type: 'string',
              enum: [
                'deepgram',
                'speechmatics',
                'assemblyai',
                'xai',
                'soniox',
                'parakeet',
                'humain',
                'reson8',
                'cohere',
                'azure',
                'openai',
                'google',
                'telnyx',
              ],
            },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'List of supported STT providers and models.',
      content: { 'application/json': { schema: STTProvidersResponseSchema } },
    },
    400: {
      description: 'Bad request — invalid filter value.',
      content: {
        'application/json': {
          schema: SpeechToTextErrorsSchema,
          example: {
            errors: [
              {
                code: '10015',
                title: 'Bad Request',
                detail: 'The request failed because it was not well-formed.',
              },
            ],
          },
        },
      },
    },
    401: { description: 'Authentication failed — missing or invalid API key.' },
    422: SpeechToTextUnprocessableEntityResponseResponse,
  },
  servers: [{ url: 'https://api.telnyx.com/v2', description: 'Telnyx API v2' }],
})

export const getSpeechToTextTranscriptionRoute = createRoute({
  method: 'get',
  path: '/speech-to-text/transcription',
  tags: ['Speech To Text over WebSockets'],
  summary: 'Speech to text over WebSocket',
  description:
    'Open a WebSocket connection to stream audio and receive transcriptions in real-time. Authentication is provided via the standard `Authorization: Bearer <API_KEY>` header.\n\nSupported engines: `Azure`, `Deepgram`, `Google`, `Telnyx`, `xAI`, `Speechmatics`, `Soniox`, `Parakeet`, `Humain`, `Reson8`, `Cohere`.\n\n**Connection flow:**\n1. Open WebSocket with query parameters specifying engine, input format, and language.\n2. Send binary audio frames (mp3, wav, linear16, or linear32 format, per `input_format`).\n3. Receive JSON transcript frames with `transcript`, `is_final`, and `confidence` fields.\n4. Close connection when done.',
  operationId: 'TranscriptionOverWs',
  request: {
    query: z.object({
      transcription_engine: TranscriptionEngineParamsSchema,
      input_format: InputFormatParamsSchema,
      sample_rate: SampleRateParamsSchema,
      language: LanguageParamsSchema,
      interim_results: InterimResultsParamsSchema,
      model: ModelParamsSchema,
      endpointing: EndpointingParamsSchema,
      redact: RedactParamsSchema,
      keyterm: KeytermParamsSchema,
      keywords: KeywordsParamsSchema,
    }),
    body: {
      description:
        'Client sends binary audio frames (mp3, wav, linear16, or linear32 format, per `input_format`) over the WebSocket. See `SttClientEvent` schema.',
      content: { 'application/octet-stream': { schema: SttClientEventSchema } },
    },
  },
  responses: {
    101: {
      description:
        'WebSocket connection established. Communication proceeds via binary audio frames (client) and JSON transcript frames (server).\n\n**Client → Server:** Binary audio data (mp3, wav, linear16, or linear32, per `input_format`).\n**Server → Client:** See `TranscriptFrame` and `SttErrorFrame` schemas.',
      content: { 'application/json': { schema: SttServerEventSchema } },
    },
    200: {
      description:
        'WebSocket upgrade successful — this response is not returned directly. See 101 for frame documentation.',
    },
    400: { description: 'Invalid parameters — engine not supported or missing required fields.' },
    401: { description: 'Authentication failed — missing or invalid Authorization header.' },
    422: SpeechToTextUnprocessableEntityResponseResponse,
  },
  servers: [{ url: 'wss://api.telnyx.com/v2', description: 'Telnyx API v2 (WebSocket)' }],
})

