export const getStorageCloudfsRoute = createRoute({
  method: 'get',
  path: '/storage/cloudfs',
  tags: ['cloudfs filesystems'],
  summary: 'List CloudFS filesystems',
  description:
    "Lists the CloudFS filesystems for the authenticated user's organization. Results use cursor-based pagination: fetch the next page by passing `meta.cursors.after` as `page[after]`, or follow the `meta.next` URL.",
  operationId: 'ListCloudfsFilesystems',
  request: {
    query: z.object({
      'page[limit]': z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1).max(250),
        )
        .default(20)
        .exactOptional()
        .openapi({
          param: {
            description:
              'The number of filesystems to return per page. Values above 250 are treated as 250.',
            name: 'page[limit]',
            in: 'query',
            schema: { type: 'integer', minimum: 1, maximum: 250, default: 20 },
            required: false,
          },
        }),
      'page[after]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              "Opaque cursor from a previous response's `meta.cursors.after`; returns the page after it. Mutually exclusive with `page[before]`.",
            name: 'page[after]',
            in: 'query',
            schema: { type: 'string' },
            required: false,
          },
        }),
      'page[before]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              "Opaque cursor from a previous response's `meta.cursors.before`; returns the page before it. Mutually exclusive with `page[after]`.",
            name: 'page[before]',
            in: 'query',
            schema: { type: 'string' },
            required: false,
          },
        }),
      'filter[name]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Return only the filesystem whose name matches exactly.',
            name: 'filter[name]',
            in: 'query',
            schema: { type: 'string' },
            required: false,
          },
        }),
      'filter[status]': z
        .enum(['provisioning', 'ready', 'needs_format', 'deleting', 'failed'])
        .exactOptional()
        .openapi({
          param: {
            description:
              'Return only filesystems with this status. Unrecognized values are ignored.',
            name: 'filter[status]',
            in: 'query',
            schema: {
              type: 'string',
              enum: ['provisioning', 'ready', 'needs_format', 'deleting', 'failed'],
            },
            required: false,
          },
        }),
      'filter[region]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Return only filesystems in this region.',
            name: 'filter[region]',
            in: 'query',
            schema: { type: 'string', example: 'us-east-1' },
            required: false,
          },
          example: 'us-east-1',
        }),
      sort: z
        .enum(['created_at', '-created_at', 'updated_at', '-updated_at', 'name', '-name'])
        .default('-created_at')
        .exactOptional()
        .openapi({
          param: {
            description:
              'Sort order for the results: a field name for ascending, or the field name prefixed with `-` for descending.',
            name: 'sort',
            in: 'query',
            schema: {
              type: 'string',
              enum: ['created_at', '-created_at', 'updated_at', '-updated_at', 'name', '-name'],
              default: '-created_at',
            },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'CloudFS filesystems retrieved successfully',
      content: { 'application/json': { schema: CloudfsFilesystemListResponseWrapperSchema } },
    },
    401: { description: 'Unauthorized', content: { 'application/json': { schema: ErrorsSchema } } },
    422: {
      description:
        'Unprocessable entity — invalid `page[limit]`, malformed or conflicting cursor, or unsupported `sort` value',
      content: { 'application/json': { schema: ErrorsSchema } },
    },
    500: {
      description: 'Internal server error',
      content: { 'application/json': { schema: GenericErrorResponseSchema } },
    },
  },
})

export const postStorageCloudfsRoute = createRoute({
  method: 'post',
  path: '/storage/cloudfs',
  tags: ['cloudfs filesystems'],
  summary: 'Create a CloudFS filesystem',
  description:
    "Creates a CloudFS filesystem. Provisioning is synchronous — typically a few seconds, up to a few minutes — and the filesystem is returned with status `ready`, together with its S3 bucket and metadata connection details. This response is the only time the filesystem's `meta_token` — and the credential-bearing `meta_url` — are returned; store them securely. If the token is lost, issue a new one with the rotate-meta-token action. Names are unique within your organization: creating with an existing name returns a `422`. Requests are idempotent: retrying with the same `Idempotency-Key` within 24 hours replays the original response instead of creating another filesystem.",
  operationId: 'CreateCloudfsFilesystem',
  request: {
    headers: z.object({
      'Idempotency-Key': z
        .string()
        .regex(/^[A-Za-z0-9_-]+$/)
        .min(1)
        .max(255)
        .openapi({
          param: {
            description:
              'Unique key that makes the request idempotent (1-255 characters: letters, numbers, `_`, and `-`). Retrying with the same key within 24 hours replays the original response (marked with an `Idempotent-Replayed: true` header) instead of repeating the action. Reusing a key with a different request returns a `422`; sending a key while the original request is still being processed returns a `409`.',
            name: 'Idempotency-Key',
            in: 'header',
            required: true,
            schema: { type: 'string', minLength: 1, maxLength: 255, pattern: '^[A-Za-z0-9_-]+$' },
          },
        }),
    }),
    body: {
      description: 'CloudFS filesystem creation request',
      content: { 'application/json': { schema: CreateCloudfsFilesystemRequestSchema } },
      required: true,
    },
  },
  responses: {
    201: {
      description:
        'CloudFS filesystem created successfully. This is the only response (besides rotate-meta-token) that includes `meta_token`.',
      content: { 'application/json': { schema: CloudfsFilesystemResponseWrapperSchema } },
      headers: z.object({ 'Idempotent-Replayed': IdempotentReplayedHeaderSchema }),
    },
    400: {
      description:
        'Bad request — malformed JSON, unknown field, or a missing or invalid `Idempotency-Key` header',
      content: { 'application/json': { schema: ErrorsSchema } },
    },
    401: { description: 'Unauthorized', content: { 'application/json': { schema: ErrorsSchema } } },
    409: {
      description: 'Conflict — a request with this `Idempotency-Key` is still being processed',
      content: { 'application/json': { schema: ErrorsSchema } },
    },
    422: {
      description:
        'Unprocessable entity — missing or invalid `name` or `region`, a filesystem with this name already exists for your organization, or the `Idempotency-Key` was already used for a different request',
      content: { 'application/json': { schema: ErrorsSchema } },
    },
    500: {
      description: 'Internal server error',
      content: { 'application/json': { schema: GenericErrorResponseSchema } },
    },
  },
})

