export const getStorageSqldbsRoute = createRoute({
  method: 'get',
  path: '/storage/sqldbs',
  tags: ['sql databases'],
  summary: 'List SQL databases',
  description:
    "Lists the SQL databases for the authenticated user's organization. Results use page-based pagination (`page[number]`/`page[size]`) and can be filtered and sorted.",
  operationId: 'ListSqlDatabases',
  request: {
    query: z.object({
      'page[number]': z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            description: 'The page number to load.',
            name: 'page[number]',
            in: 'query',
            schema: { type: 'integer', minimum: 1, default: 1 },
            required: false,
          },
        }),
      'page[size]': z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1).max(250),
        )
        .default(20)
        .exactOptional()
        .openapi({
          param: {
            description: 'The size of the page. Values above 250 are treated as 250.',
            name: 'page[size]',
            in: 'query',
            schema: { type: 'integer', minimum: 1, maximum: 250, default: 20 },
            required: false,
          },
        }),
      'filter[name]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter by exact name match.',
            name: 'filter[name]',
            in: 'query',
            schema: { type: 'string' },
            required: false,
          },
        }),
      'filter[status]': z
        .enum(['pending', 'provision_ok', 'provision_failed', 'deleting', 'delete_failed'])
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter by provisioning status.',
            name: 'filter[status]',
            in: 'query',
            schema: {
              type: 'string',
              enum: ['pending', 'provision_ok', 'provision_failed', 'deleting', 'delete_failed'],
            },
            required: false,
          },
        }),
      sort: z
        .enum(['name', '-name', 'status', '-status', 'created_at', '-created_at'])
        .default('-created_at')
        .exactOptional()
        .openapi({
          param: {
            description: 'Sort field; prefix with `-` for descending order.',
            name: 'sort',
            in: 'query',
            schema: {
              type: 'string',
              enum: ['name', '-name', 'status', '-status', 'created_at', '-created_at'],
              default: '-created_at',
            },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'SQL databases retrieved successfully',
      content: { 'application/json': { schema: SqlDatabaseListResponseWrapperSchema } },
    },
    401: { description: 'Unauthorized', content: { 'application/json': { schema: ErrorsSchema } } },
    422: {
      description: 'Validation error — an unsupported `sort` or `filter` value',
      content: { 'application/json': { schema: ErrorsSchema } },
    },
    500: {
      description: 'Internal server error',
      content: { 'application/json': { schema: GenericErrorResponseSchema } },
    },
  },
})

