export const deleteStorageSqldbsIdRoute = createRoute({
  method: 'delete',
  path: '/storage/sqldbs/{id}',
  tags: ['sql databases'],
  summary: 'Delete a SQL database',
  description:
    'Deletes a SQL database and all of the data it holds. Deletion is asynchronous and returns `202` with an empty body — the record is not removed synchronously. Poll `GET /storage/sqldbs/{id}`, which returns `404` once the database has been purged; there is no durable `deleted` state. A database still bound by a function is refused with `409` unless `force=true`.',
  operationId: 'DeleteSqlDatabase',
  request: {
    params: z.object({
      id: z
        .uuid()
        .openapi({
          param: {
            description: 'SQL database ID',
            name: 'id',
            in: 'path',
            required: true,
            schema: { type: 'string', format: 'uuid' },
          },
        }),
    }),
    query: z.object({
      force: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            description:
              'Delete the database even when functions still bind it. Their bindings stop resolving.',
            name: 'force',
            in: 'query',
            schema: { type: 'boolean', default: false },
            required: false,
          },
        }),
    }),
  },
  responses: {
    202: {
      description:
        'Accepted — deletion runs asynchronously. The body is empty; poll `GET /storage/sqldbs/{id}` until it returns `404`.',
    },
    401: { description: 'Unauthorized', content: { 'application/json': { schema: ErrorsSchema } } },
    404: {
      description: 'SQL database not found',
      content: { 'application/json': { schema: ErrorsSchema } },
    },
    409: {
      description:
        'Conflict — the database is already being deleted, or is still bound by one or more functions',
      content: { 'application/json': { schema: ErrorsSchema } },
    },
    422: {
      description: 'Validation error — `id` is not a valid identifier',
      content: { 'application/json': { schema: ErrorsSchema } },
    },
    500: {
      description: 'Internal server error',
      content: { 'application/json': { schema: GenericErrorResponseSchema } },
    },
    503: {
      description:
        'Cannot verify whether the database is still in use; retry, or pass `force=true`',
      content: { 'application/json': { schema: ErrorsSchema } },
    },
  },
})

