export const getTexmlAccountsAccountSidConferencesConferenceSidParticipantsCallSidOrParticipantLabelRoute =
  createRoute({
    method: 'get',
    path: '/texml/Accounts/{account_sid}/Conferences/{conference_sid}/Participants/{call_sid_or_participant_label}',
    tags: ['TeXML REST Commands'],
    summary: 'Get conference participant resource',
    description:
      'Returns a single conference participant resource by call SID or participant label.',
    operationId: 'GetTexmlConferenceParticipant',
    request: {
      params: z.object({
        account_sid: AccountSidParamsSchema,
        conference_sid: ConferenceSidParamsSchema,
        call_sid_or_participant_label: CallSidOrParticipantLabelParamsSchema,
      }),
    },
    responses: {
      200: {
        description: 'Participant resource.',
        content: { 'application/json': { schema: ParticipantResourceSchema } },
      },
      404: CallScriptingNotFoundResponseC75353cb83Response,
    },
  })

