export const getTunnelsRoute = createRoute({
  method: 'get',
  path: '/tunnels',
  tags: ['Tunnels'],
  summary: 'List all Tunnels',
  description:
    'Lists the tunnels on the account with their status and connected tunnel processes. Responses never include `tunnel_token`.',
  operationId: 'ListTunnels',
  request: {
    query: z
      .looseObject({})
      .transform((val) => {
        const rest: [string, unknown][] = []
        const groups = new Map<string, Record<string, unknown>>()
        const group = (name: string) => {
          const found = groups.get(name)
          if (found !== undefined) return found
          const made: Record<string, unknown> = Object.create(null)
          groups.set(name, made)
          return made
        }
        const isGroup = (item: unknown): item is Record<string, unknown> =>
          typeof item === 'object' && item !== null && !Array.isArray(item)
        const lists = new WeakSet<object>()
        const isIndex = (part: string | undefined) => part !== undefined && /^\d*$/.test(part)
        const child = (target: Record<string, unknown>, key: string, asList: boolean) => {
          const held = target[key]
          if (isGroup(held)) return held
          const made: Record<string, unknown> = Object.create(null)
          if (asList) lists.add(made)
          target[key] = made
          return made
        }
        const set = (
          root: Record<string, unknown>,
          path: readonly string[],
          item: unknown,
        ): void => {
          const work: [Record<string, unknown>, number, unknown, boolean][] = [
            [root, 0, item, false],
          ]
          for (let job = work.pop(); job !== undefined; job = work.pop()) {
            const [target, at, value, split] = job
            const head = path[at]
            if (head === undefined) continue
            const next = path[at + 1]
            if (head === '') {
              if (!split && Array.isArray(value)) {
                for (let i = value.length - 1; i >= 0; i -= 1)
                  work.push([target, at, value[i], true])
                continue
              }
              const size = Object.keys(target).length
              if (next === undefined) {
                target[String(size)] = value
                continue
              }
              const free =
                next === ''
                  ? -1
                  : Object.values(target).findIndex((held) => isGroup(held) && !(next in held))
              work.push([
                child(target, String(free < 0 ? size : free), isIndex(next)),
                at + 1,
                value,
                false,
              ])
              continue
            }
            if (next === undefined) {
              target[head] = value
              continue
            }
            work.push([child(target, head, isIndex(next)), at + 1, value, false])
          }
        }
        const settle = (root: unknown): unknown => {
          if (!isGroup(root)) return root
          const found: [Record<string, unknown>, string, Record<string, unknown>][] = []
          const queue: Record<string, unknown>[] = [root]
          for (const node of queue) {
            for (const [key, inner] of Object.entries(node)) {
              if (isGroup(inner)) {
                found.push([node, key, inner])
                queue.push(inner)
              }
            }
          }
          const finish = (group: Record<string, unknown>): unknown =>
            lists.has(group)
              ? Object.entries(group)
                  .sort((a, b) => Number(a[0]) - Number(b[0]))
                  .map(([, inner]) => inner)
              : Object.assign(Object.create(null), group)
          for (const [parent, key, group] of found.reverse()) {
            parent[key] = finish(group)
          }
          return finish(root)
        }
        const deep: string[] = ['filter', 'page']
        for (const [key, item] of Object.entries(val)) {
          const match = /^([^\[\]]+)((?:\[[^\[\]]*\])+)$/.exec(key)
          const name = match?.[1]
          const path = match?.[2]
          if (name !== undefined && path !== undefined && deep.includes(name)) {
            const parts = path.slice(1, -1).split('][')
            set(group(name), parts, item)
            continue
          }
          rest.push([key, item])
        }
        return Object.fromEntries([
          ...rest,
          ...[...groups].map(([name, held]) => [name, settle(held)] as const),
        ])
      })
      .pipe(
        z.object({
          filter: z
            .object({
              name: z
                .string()
                .exactOptional()
                .openapi({ description: 'The name of the tunnel.', example: 'chicago-dc' }),
              status: z
                .enum(['inactive', 'healthy', 'degraded'])
                .exactOptional()
                .openapi({ description: 'The status of the tunnel.', example: 'healthy' }),
            })
            .exactOptional()
            .openapi({
              param: {
                name: 'filter',
                in: 'query',
                style: 'deepObject',
                explode: true,
                description:
                  'Consolidated filter parameter (deepObject style). Originally: filter[name], filter[status]',
                schema: {
                  type: 'object',
                  properties: {
                    name: {
                      type: 'string',
                      description: 'The name of the tunnel.',
                      example: 'chicago-dc',
                    },
                    status: {
                      type: 'string',
                      enum: ['inactive', 'healthy', 'degraded'],
                      description: 'The status of the tunnel.',
                      example: 'healthy',
                    },
                  },
                },
                required: false,
              },
              required: [],
            }),
          sort: z
            .enum([
              'name',
              '-name',
              'status',
              '-status',
              'created_at',
              '-created_at',
              'updated_at',
              '-updated_at',
            ])
            .exactOptional()
            .openapi({
              param: {
                name: 'sort',
                in: 'query',
                description:
                  'Sorts the results by a field, ascending, or descending with a leading `-`. The default is `-created_at`.',
                schema: {
                  type: 'string',
                  enum: [
                    'name',
                    '-name',
                    'status',
                    '-status',
                    'created_at',
                    '-created_at',
                    'updated_at',
                    '-updated_at',
                  ],
                  example: '-created_at',
                },
                required: false,
              },
              example: '-created_at',
            }),
          page: PageCursorConsolidatedParamsSchema,
        }),
      ),
  },
  responses: {
    200: {
      description: 'Successful response.',
      content: {
        'application/json': {
          schema: z
            .object({
              data: z.array(TunnelSchema).exactOptional(),
              meta: NetappsCursorPaginationMetaSchema.exactOptional(),
            })
            .openapi({ required: [] }),
          example: {
            data: [
              {
                id: '62d438d2-8a51-4c5e-9d0c-1f6b2a7e4c39',
                record_type: 'tunnel',
                name: 'chicago-dc',
                status: 'healthy',
                connection_count: 2,
                connections: [
                  {
                    hostname: 'dc1-tunnel-a',
                    version: '0.6.0',
                    region_code: 'chicago-il',
                    connected_at: '2026-10-21T15:04:05.123456Z',
                  },
                  {
                    hostname: 'dc1-tunnel-b',
                    version: '0.6.0',
                    region_code: 'chicago-il',
                    connected_at: '2026-10-21T15:04:05.123456Z',
                  },
                ],
                created_at: '2026-10-21T15:04:05.123456Z',
              },
            ],
            meta: { cursors: {} },
          },
        },
      },
    },
    422: {
      description:
        'Unprocessable entity: a query parameter is not valid, such as an unsupported `sort` field.',
      content: {
        'application/json': {
          schema: ErrorsSchema,
          example: {
            errors: [
              {
                code: '10022',
                title: 'Unprocessable Entity',
                detail: 'unsupported sort field',
                source: { pointer: 'sort' },
              },
            ],
          },
        },
      },
    },
    default: GenericErrorResponseResponse,
  },
})

