export const getVerifiedNumbersRoute = createRoute({
  method: 'get',
  path: '/verified_numbers',
  tags: ['Verified Numbers'],
  summary: 'List all Verified Numbers',
  description: 'Gets a paginated list of Verified Numbers.',
  operationId: 'ListVerifiedNumbers',
  request: {
    query: z
      .looseObject({})
      .transform((val) => {
        const rest: [string, unknown][] = []
        const groups = new Map<string, Record<string, unknown>>()
        const group = (name: string) => {
          const found = groups.get(name)
          if (found !== undefined) return found
          const made: Record<string, unknown> = Object.create(null)
          groups.set(name, made)
          return made
        }
        const isGroup = (item: unknown): item is Record<string, unknown> =>
          typeof item === 'object' && item !== null && !Array.isArray(item)
        const lists = new WeakSet<object>()
        const isIndex = (part: string | undefined) => part !== undefined && /^\d*$/.test(part)
        const child = (target: Record<string, unknown>, key: string, asList: boolean) => {
          const held = target[key]
          if (isGroup(held)) return held
          const made: Record<string, unknown> = Object.create(null)
          if (asList) lists.add(made)
          target[key] = made
          return made
        }
        const set = (
          root: Record<string, unknown>,
          path: readonly string[],
          item: unknown,
        ): void => {
          const work: [Record<string, unknown>, number, unknown, boolean][] = [
            [root, 0, item, false],
          ]
          for (let job = work.pop(); job !== undefined; job = work.pop()) {
            const [target, at, value, split] = job
            const head = path[at]
            if (head === undefined) continue
            const next = path[at + 1]
            if (head === '') {
              if (!split && Array.isArray(value)) {
                for (let i = value.length - 1; i >= 0; i -= 1)
                  work.push([target, at, value[i], true])
                continue
              }
              const size = Object.keys(target).length
              if (next === undefined) {
                target[String(size)] = value
                continue
              }
              const free =
                next === ''
                  ? -1
                  : Object.values(target).findIndex((held) => isGroup(held) && !(next in held))
              work.push([
                child(target, String(free < 0 ? size : free), isIndex(next)),
                at + 1,
                value,
                false,
              ])
              continue
            }
            if (next === undefined) {
              target[head] = value
              continue
            }
            work.push([child(target, head, isIndex(next)), at + 1, value, false])
          }
        }
        const settle = (root: unknown): unknown => {
          if (!isGroup(root)) return root
          const found: [Record<string, unknown>, string, Record<string, unknown>][] = []
          const queue: Record<string, unknown>[] = [root]
          for (const node of queue) {
            for (const [key, inner] of Object.entries(node)) {
              if (isGroup(inner)) {
                found.push([node, key, inner])
                queue.push(inner)
              }
            }
          }
          const finish = (group: Record<string, unknown>): unknown =>
            lists.has(group)
              ? Object.entries(group)
                  .sort((a, b) => Number(a[0]) - Number(b[0]))
                  .map(([, inner]) => inner)
              : Object.assign(Object.create(null), group)
          for (const [parent, key, group] of found.reverse()) {
            parent[key] = finish(group)
          }
          return finish(root)
        }
        const deep: string[] = ['page']
        for (const [key, item] of Object.entries(val)) {
          const match = /^([^\[\]]+)((?:\[[^\[\]]*\])+)$/.exec(key)
          const name = match?.[1]
          const path = match?.[2]
          if (name !== undefined && path !== undefined && deep.includes(name)) {
            const parts = path.slice(1, -1).split('][')
            set(group(name), parts, item)
            continue
          }
          rest.push([key, item])
        }
        return Object.fromEntries([
          ...rest,
          ...[...groups].map(([name, held]) => [name, settle(held)] as const),
        ])
      })
      .pipe(
        z.object({
          page: z
            .object({
              size: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .default(25)
                .exactOptional()
                .openapi({ title: 'page[size]' }),
              number: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .default(1)
                .exactOptional()
                .openapi({ title: 'page[number]' }),
            })
            .exactOptional()
            .openapi({
              param: {
                name: 'page',
                in: 'query',
                required: false,
                style: 'deepObject',
                explode: true,
                description:
                  'Consolidated page parameter (deepObject style). Use page[size] and page[number] in the query string. Originally: page[size], page[number]',
                schema: {
                  type: 'object',
                  properties: {
                    size: { title: 'page[size]', type: 'integer', default: 25 },
                    number: { title: 'page[number]', type: 'integer', default: 1 },
                  },
                },
              },
              required: [],
            }),
        }),
      ),
  },
  responses: {
    200: {
      description: 'Expected response to a valid request.',
      content: { 'application/json': { schema: ListVerifiedNumbersResponseSchema } },
    },
    400: VerifiedNumbersGenericErrorResponseResponse,
    401: UnauthorizedRequestErrorResponseResponse,
    422: VerifiedNumbersUnprocessableEntityErrorResponseResponse,
  },
})

export const postVerifiedNumbersRoute = createRoute({
  method: 'post',
  path: '/verified_numbers',
  tags: ['Verified Numbers'],
  summary: 'Request phone number verification',
  description:
    'Initiates phone number verification procedure. Supports DTMF extension dialing for voice calls to numbers behind IVR systems.',
  operationId: 'CreateVerifiedNumber',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              phone_number: z.string().openapi({ example: '+15551234567' }),
              verification_method: z
                .enum(['sms', 'call'])
                .openapi({ description: 'Verification method.', example: 'sms' }),
              extension: z
                .string()
                .regex(/^[0-9A-D*#wW]*$/)
                .max(50)
                .nullable()
                .default(null)
                .exactOptional()
                .openapi({
                  example: 'ww243w1',
                  description:
                    "Optional DTMF extension sequence to dial after the call is answered. This parameter enables verification of phone numbers behind IVR systems that require extension dialing. Valid characters: digits 0-9, letters A-D, symbols * and #. Pauses: w = 0.5 second pause, W = 1 second pause. Maximum length: 50 characters. Only works with 'call' verification method.",
                }),
            })
            .openapi({
              title: 'Create Verified Number Request',
              required: ['phone_number', 'verification_method'],
            }),
          examples: {
            sms_verification: {
              summary: 'SMS verification',
              value: { phone_number: '+15551234567', verification_method: 'sms' },
            },
            call_verification: {
              summary: 'Call verification',
              value: { phone_number: '+15551234567', verification_method: 'call' },
            },
            call_with_extension: {
              summary: 'Call verification with DTMF extension',
              description:
                'Example for verifying a number behind an IVR system that requires extension dialing',
              value: {
                phone_number: '+15551234567',
                verification_method: 'call',
                extension: 'ww243w1',
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Expected response to a valid request.',
      content: { 'application/json': { schema: CreateVerifiedNumberResponseSchema } },
    },
    400: VerifiedNumbersGenericErrorResponseResponse,
    401: UnauthorizedRequestErrorResponseResponse,
    422: VerifiedNumbersUnprocessableEntityErrorResponseResponse,
  },
})

