export const postWebSearchResearchRoute = createRoute({
  method: 'post',
  path: '/web_search/research',
  tags: ['Research'],
  summary: 'Start research task',
  description:
    'Starts a deep research task that runs multiple searches, reads sources, and synthesizes an answer with citations.\n\n## Synchronous mode (default)\n\nWhen `background` is `false` or omitted, the request blocks until the research completes and returns the answer with citations. This can take up to 120 seconds depending on `research_effort`.\n\n## Asynchronous mode\n\nWhen `background` is `true`, the request returns immediately with a `task_id` and `status: pending`. Poll `GET /web_search/research/{task_id}` to check when the research completes and retrieve the answer.',
  operationId: 'CreateWebSearchResearch',
  request: {
    body: {
      content: {
        'application/json': {
          schema: ResearchRequestSchema,
          example: {
            query: 'Compare the performance of RAG vs fine-tuning for domain-specific QA',
            research_effort: 'standard',
            max_sources: 20,
            background: false,
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description:
        'Research response. Shape depends on `background`:\n\n- **Synchronous** (`background` false/unset): returns `answer` + `citations`.\n- **Asynchronous** (`background` true): returns `task_id` + `status`.',
      content: {
        'application/json': {
          schema: z
            .object({
              data: z
                .xor([ResearchResponseSyncSchema, ResearchResponseAsyncSchema])
                .exactOptional(),
            })
            .openapi({ required: [] }),
          examples: {
            sync: {
              summary: 'Synchronous response (background=false)',
              value: {
                data: {
                  answer: 'RAG and fine-tuning serve different purposes...',
                  citations: [
                    {
                      url: 'https://arxiv.org/abs/2401.15884',
                      title: 'Retrieval-Augmented Generation for Knowledge-Intensive NLP Tasks',
                      snippet:
                        'We show that RAG models produce more factually grounded responses...',
                    },
                  ],
                },
              },
            },
            async: {
              summary: 'Asynchronous response (background=true)',
              value: {
                data: { task_id: 'bf3026a5-dd57-44dd-b922-200041be3a4b', status: 'pending' },
              },
            },
          },
        },
      },
    },
    400: WebSearchBadRequestResponse,
    401: WebSearchUnauthorizedResponse,
    500: WebSearchInternalServerErrorResponse,
    502: WebSearchProviderErrorResponse,
    504: ProviderTimeoutResponse,
  },
})

