export const getWebhookDeliveriesRoute = createRoute({
  method: 'get',
  path: '/webhook_deliveries',
  tags: ['Webhooks'],
  summary: 'List webhook deliveries',
  description: 'Lists webhook_deliveries for the authenticated user',
  operationId: 'GetWebhookDeliveries',
  request: {
    query: z
      .looseObject({})
      .transform((val) => {
        const rest: [string, unknown][] = []
        const groups = new Map<string, Record<string, unknown>>()
        const group = (name: string) => {
          const found = groups.get(name)
          if (found !== undefined) return found
          const made: Record<string, unknown> = Object.create(null)
          groups.set(name, made)
          return made
        }
        const isGroup = (item: unknown): item is Record<string, unknown> =>
          typeof item === 'object' && item !== null && !Array.isArray(item)
        const lists = new WeakSet<object>()
        const isIndex = (part: string | undefined) => part !== undefined && /^\d*$/.test(part)
        const child = (target: Record<string, unknown>, key: string, asList: boolean) => {
          const held = target[key]
          if (isGroup(held)) return held
          const made: Record<string, unknown> = Object.create(null)
          if (asList) lists.add(made)
          target[key] = made
          return made
        }
        const set = (
          root: Record<string, unknown>,
          path: readonly string[],
          item: unknown,
        ): void => {
          const work: [Record<string, unknown>, number, unknown, boolean][] = [
            [root, 0, item, false],
          ]
          for (let job = work.pop(); job !== undefined; job = work.pop()) {
            const [target, at, value, split] = job
            const head = path[at]
            if (head === undefined) continue
            const next = path[at + 1]
            if (head === '') {
              if (!split && Array.isArray(value)) {
                for (let i = value.length - 1; i >= 0; i -= 1)
                  work.push([target, at, value[i], true])
                continue
              }
              const size = Object.keys(target).length
              if (next === undefined) {
                target[String(size)] = value
                continue
              }
              const free =
                next === ''
                  ? -1
                  : Object.values(target).findIndex((held) => isGroup(held) && !(next in held))
              work.push([
                child(target, String(free < 0 ? size : free), isIndex(next)),
                at + 1,
                value,
                false,
              ])
              continue
            }
            if (next === undefined) {
              target[head] = value
              continue
            }
            work.push([child(target, head, isIndex(next)), at + 1, value, false])
          }
        }
        const settle = (root: unknown): unknown => {
          if (!isGroup(root)) return root
          const found: [Record<string, unknown>, string, Record<string, unknown>][] = []
          const queue: Record<string, unknown>[] = [root]
          for (const node of queue) {
            for (const [key, inner] of Object.entries(node)) {
              if (isGroup(inner)) {
                found.push([node, key, inner])
                queue.push(inner)
              }
            }
          }
          const finish = (group: Record<string, unknown>): unknown =>
            lists.has(group)
              ? Object.entries(group)
                  .sort((a, b) => Number(a[0]) - Number(b[0]))
                  .map(([, inner]) => inner)
              : Object.assign(Object.create(null), group)
          for (const [parent, key, group] of found.reverse()) {
            parent[key] = finish(group)
          }
          return finish(root)
        }
        const deep: string[] = ['page', 'filter']
        for (const [key, item] of Object.entries(val)) {
          const match = /^([^\[\]]+)((?:\[[^\[\]]*\])+)$/.exec(key)
          const name = match?.[1]
          const path = match?.[2]
          if (name !== undefined && path !== undefined && deep.includes(name)) {
            const parts = path.slice(1, -1).split('][')
            set(group(name), parts, item)
            continue
          }
          rest.push([key, item])
        }
        return Object.fromEntries([
          ...rest,
          ...[...groups].map(([name, held]) => [name, settle(held)] as const),
        ])
      })
      .pipe(
        z.object({
          page: PageConsolidatedParamsSchema,
          filter: z
            .object({
              status: z
                .object({
                  eq: z
                    .enum(['delivered', 'failed'])
                    .exactOptional()
                    .openapi({
                      example: 'delivered',
                      description: 'Return only webhook_deliveries matching the given `status`',
                    }),
                })
                .exactOptional()
                .openapi({ required: [] }),
              event_type: z
                .string()
                .exactOptional()
                .openapi({
                  example: 'call_initiated,call.initiated',
                  description:
                    'Return only webhook_deliveries matching the given value of `event_type`. Accepts multiple values separated by a `,`.',
                }),
              webhook: z
                .object({
                  contains: z
                    .string()
                    .exactOptional()
                    .openapi({
                      example: 'call.initiated',
                      description:
                        'Return only webhook deliveries whose `webhook` component contains the given text',
                    }),
                })
                .exactOptional()
                .openapi({ required: [] }),
              attempts: z
                .object({
                  contains: z
                    .string()
                    .exactOptional()
                    .openapi({
                      example: 'https://fallback.example.com/webhooks',
                      description:
                        'Return only webhook_deliveries whose `attempts` component contains the given text',
                    }),
                })
                .exactOptional()
                .openapi({ required: [] }),
              started_at: z
                .object({
                  gte: z
                    .string()
                    .exactOptional()
                    .openapi({
                      example: '2019-03-29T11:10:00Z',
                      description:
                        'Return only webhook_deliveries whose delivery started later than or at given ISO 8601 datetime',
                    }),
                  lte: z
                    .string()
                    .exactOptional()
                    .openapi({
                      example: '2019-03-29T11:10:00Z',
                      description:
                        'Return only webhook_deliveries whose delivery started earlier than or at given ISO 8601 datetime',
                    }),
                })
                .exactOptional()
                .openapi({ required: [] }),
              finished_at: z
                .object({
                  gte: z
                    .string()
                    .exactOptional()
                    .openapi({
                      example: '2019-03-29T11:10:00Z',
                      description:
                        'Return only webhook_deliveries whose delivery finished later than or at given ISO 8601 datetime',
                    }),
                  lte: z
                    .string()
                    .exactOptional()
                    .openapi({
                      example: '2019-03-29T11:10:00Z',
                      description:
                        'Return only webhook_deliveries whose delivery finished earlier than or at given ISO 8601 datetime',
                    }),
                })
                .exactOptional()
                .openapi({ required: [] }),
            })
            .exactOptional()
            .openapi({
              param: {
                name: 'filter',
                in: 'query',
                style: 'deepObject',
                explode: true,
                required: false,
                description:
                  'Consolidated filter parameter (deepObject style). Originally: filter[status][eq], filter[event_type], filter[webhook][contains], filter[attempts][contains], filter[started_at][gte], filter[started_at][lte], filter[finished_at][gte], filter[finished_at][lte]',
                schema: {
                  type: 'object',
                  properties: {
                    status: {
                      type: 'object',
                      properties: {
                        eq: {
                          type: 'string',
                          enum: ['delivered', 'failed'],
                          example: 'delivered',
                          description: 'Return only webhook_deliveries matching the given `status`',
                        },
                      },
                    },
                    event_type: {
                      type: 'string',
                      example: 'call_initiated,call.initiated',
                      description:
                        'Return only webhook_deliveries matching the given value of `event_type`. Accepts multiple values separated by a `,`.',
                    },
                    webhook: {
                      type: 'object',
                      properties: {
                        contains: {
                          type: 'string',
                          example: 'call.initiated',
                          description:
                            'Return only webhook deliveries whose `webhook` component contains the given text',
                        },
                      },
                    },
                    attempts: {
                      type: 'object',
                      properties: {
                        contains: {
                          type: 'string',
                          example: 'https://fallback.example.com/webhooks',
                          description:
                            'Return only webhook_deliveries whose `attempts` component contains the given text',
                        },
                      },
                    },
                    started_at: {
                      type: 'object',
                      properties: {
                        gte: {
                          type: 'string',
                          example: '2019-03-29T11:10:00Z',
                          description:
                            'Return only webhook_deliveries whose delivery started later than or at given ISO 8601 datetime',
                        },
                        lte: {
                          type: 'string',
                          example: '2019-03-29T11:10:00Z',
                          description:
                            'Return only webhook_deliveries whose delivery started earlier than or at given ISO 8601 datetime',
                        },
                      },
                    },
                    finished_at: {
                      type: 'object',
                      properties: {
                        gte: {
                          type: 'string',
                          example: '2019-03-29T11:10:00Z',
                          description:
                            'Return only webhook_deliveries whose delivery finished later than or at given ISO 8601 datetime',
                        },
                        lte: {
                          type: 'string',
                          example: '2019-03-29T11:10:00Z',
                          description:
                            'Return only webhook_deliveries whose delivery finished earlier than or at given ISO 8601 datetime',
                        },
                      },
                    },
                  },
                },
              },
              required: [],
            }),
        }),
      ),
  },
  responses: {
    200: {
      description: 'A paginated array of webhook_delivery attempts',
      content: {
        'application/json': {
          schema: z
            .object({
              data: z.array(WebhookDeliverySchema).exactOptional(),
              meta: PaginationMetaSimpleSchema.exactOptional(),
            })
            .openapi({ required: [] }),
        },
      },
    },
    401: { description: 'Unauthorized' },
    422: { description: 'Unprocessable entity' },
  },
})

