export const postX402CreditAccountRoute = createRoute({
  method: 'post',
  path: '/x402/credit_account',
  tags: ['x402 Payment Transactions'],
  summary: 'Settle a payment',
  description:
    'Settles an x402 payment using the quote ID and a signed payment authorization. The payment signature can be provided via the `PAYMENT-SIGNATURE` header or the `payment_signature` body parameter. Settlement is idempotent — submitting the same quote ID multiple times returns the existing transaction.',
  operationId: 'settleX402Payment',
  request: {
    headers: z.object({
      'PAYMENT-SIGNATURE': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'PAYMENT-SIGNATURE',
            in: 'header',
            description:
              'Signed payment authorization for the quote. Alternative to providing `payment_signature` in the request body.',
            required: false,
            schema: { type: 'string' },
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: X402SettleRequestSchema,
          example: { id: 'quote_abc123', payment_signature: '0xabc123...' },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Payment already settled (idempotent response)',
      content: { 'application/json': { schema: X402TransactionResponseSchema } },
    },
    201: {
      description: 'Payment settled successfully',
      content: {
        'application/json': {
          schema: X402TransactionResponseSchema,
          example: {
            data: {
              id: 'de06811a-2e43-4561-af5a-7d0a26e20aaa',
              record_type: 'x402_transaction',
              amount: '50.00',
              currency: 'USD',
              status: 'settled',
              quote_id: 'quote_abc123',
              tx_hash: '0xabc123def456...',
              created_at: '2026-03-13T15:00:00Z',
            },
          },
        },
      },
    },
    400: {
      description:
        'Bad request — invalid signature, expired authorization, invalid nonce, or malformed payment payload',
      content: {
        'application/json': {
          schema: X402SettlementErrorResponseSchema,
          examples: {
            invalid_signature: {
              summary: 'Invalid payment signature',
              value: {
                errors: [
                  {
                    code: 'invalid_signature',
                    title: 'Payment Failed',
                    detail:
                      'Payment failed: the payment signature is invalid. Please sign a new payment authorization.',
                  },
                ],
              },
            },
            expired_authorization: {
              summary: 'Expired payment authorization',
              value: {
                errors: [
                  {
                    code: 'expired_authorization',
                    title: 'Payment Failed',
                    detail:
                      'Payment failed: the payment authorization has expired. Please request a new quote and try again.',
                  },
                ],
              },
            },
          },
        },
      },
    },
    401: {
      description: 'Unauthorized',
      content: {
        'application/json': {
          schema: X402TransactionsErrorResponseSchema,
          example: {
            errors: [
              {
                code: '10009',
                title: 'Authentication failed',
                detail:
                  'The required authentication headers were either invalid or not included in the request.',
              },
            ],
          },
        },
      },
    },
    403: {
      description:
        'Forbidden — x402 payments not enabled, account tier ineligible, or account suspended',
      content: {
        'application/json': {
          schema: X402TransactionsErrorResponseSchema,
          example: {
            errors: [
              {
                code: '10010',
                title: 'Authorization failed',
                detail:
                  'You do not have permission to perform the requested action on the specified resource or resources.',
              },
            ],
          },
        },
      },
    },
    422: {
      description:
        'Unprocessable entity — missing required parameters or insufficient funds/allowance',
      content: {
        'application/json': {
          schema: X402SettlementErrorResponseSchema,
          examples: {
            validation_error: {
              summary: 'Missing required parameter',
              value: {
                errors: [{ code: 'unknown', title: 'Invalid request', detail: 'id is required' }],
              },
            },
            insufficient_balance: {
              summary: 'Insufficient wallet balance',
              value: {
                errors: [
                  {
                    code: 'insufficient_balance',
                    title: 'Payment Failed',
                    detail:
                      'Payment failed: your wallet does not have enough USDC to complete this transaction. Please add funds and try again.',
                  },
                ],
              },
            },
          },
        },
      },
    },
    500: {
      description:
        'Internal server error — facilitator unavailable, transaction failed on-chain, or unknown error',
      content: {
        'application/json': {
          schema: X402SettlementErrorResponseSchema,
          example: {
            errors: [
              {
                code: 'transaction_failed',
                title: 'Payment Failed',
                detail:
                  'Payment transaction failed on-chain. Your funds have not been transferred. Please try again or contact support.',
              },
            ],
          },
        },
      },
    },
    502: {
      description: 'Bad gateway — upstream settlement service error',
      content: {
        'application/json': {
          schema: X402TransactionsErrorResponseSchema,
          example: {
            errors: [
              { code: '10007', title: 'Unexpected error', detail: 'An unexpected error occured.' },
            ],
          },
        },
      },
    },
    503: {
      description: 'Service unavailable — facilitator or settlement timeout',
      content: {
        'application/json': {
          schema: X402SettlementErrorResponseSchema,
          example: {
            errors: [
              {
                code: 'facilitator_timeout',
                title: 'Payment Failed',
                detail:
                  'Payment processing timed out. Your funds have not been transferred. Please try again.',
              },
            ],
          },
        },
      },
    },
  },
})

