export const artifactCompletedPostWebhook = {
  method: 'post',
  path: '/artifactCompleted',
  tags: ['Meeting Session Webhooks'],
  summary: 'artifact.completed',
  description:
    'Sent when an artifact finishes generating -- `summary`, `action_items`, `decisions`, `topics`, `open_questions` or `custom`. Deliveries are best effort and not guaranteed: up to 5 attempts with backoff that starts around 60 seconds and roughly doubles per retry, and a 10-second delivery timeout, so respond with a 2xx promptly. Retries can produce duplicates; deduplicate on envelope `id`.',
  operationId: 'MeetingArtifactCompletedWebhook',
  request: {
    headers: z.object({
      'X-Meeting-Bot-Signature': z
        .string()
        .openapi({
          param: {
            name: 'X-Meeting-Bot-Signature',
            in: 'header',
            required: true,
            description:
              'Signature header `t=<unix-seconds>,v1=<hex>`. Compute HMAC-SHA256 with the webhook secret over the timestamp ASCII bytes, a literal `.` byte, and the exact raw request-body bytes; hex-encode and compare `v1` in constant time. Reject timestamps outside your accepted skew. No bearer token is sent.',
            schema: { type: 'string' },
            example: 't=1784297100,v1=5e8f...a3c1',
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .strictObject({
              id: z
                .string()
                .openapi({
                  description: 'Unique event id; deduplicate deliveries on it.',
                  example: 'whdel_9f2c...',
                }),
              event: z.literal('artifact.completed').openapi({ description: 'Event type.' }),
              version: z.string().openapi({ description: 'Envelope version.', example: '1' }),
              occurred_at: z.iso
                .datetime({ offset: true })
                .openapi({ description: 'When the event occurred.' }),
              data: z
                .strictObject({
                  session_id: z
                    .string()
                    .openapi({
                      description: 'The meeting session this event belongs to.',
                      example: 'mtgsess_9b2f...',
                    }),
                  artifact_id: z
                    .string()
                    .openapi({
                      description: 'Id of the completed artifact.',
                      example: 'mtgart_4e7c...',
                    }),
                  type: z
                    .enum([
                      'summary',
                      'action_items',
                      'decisions',
                      'topics',
                      'open_questions',
                      'custom',
                    ])
                    .openapi({ description: 'Type of the completed artifact.' }),
                  content: z
                    .strictObject({
                      text: z.string().openapi({ description: 'Generated artifact text.' }),
                    })
                    .openapi({ description: 'Generated artifact content.', required: ['text'] }),
                  model_provenance: z
                    .strictObject({ model: z.string(), provider: z.string() })
                    .openapi({
                      description: 'Model that generated the artifact.',
                      required: ['model', 'provider'],
                    }),
                  prompt: z
                    .union([z.string(), z.null().nullable()])
                    .openapi({
                      description:
                        'The prompt that produced this artifact, or null for a named type. Non-null only when `type` is `custom`; the five named types always return `null`.',
                    }),
                })
                .openapi({
                  description: 'Completed artifact, including its generated content.',
                  required: [
                    'session_id',
                    'artifact_id',
                    'type',
                    'content',
                    'model_provenance',
                    'prompt',
                  ],
                }),
            })
            .openapi({ required: ['id', 'event', 'version', 'occurred_at', 'data'] }),
          example: {
            id: 'whdel_9f2c...',
            event: 'artifact.completed',
            version: '1',
            occurred_at: '2026-06-16T09:06:00Z',
            data: {
              session_id: 'mtgsess_9b2f...',
              artifact_id: 'mtgart_4e7c...',
              type: 'summary',
              content: {
                text: 'Decisions: hold pricing flat through Q3. Actions: Casey to send the summary.',
              },
              model_provenance: { model: 'example-model', provider: 'telnyx' },
              prompt: null,
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description:
        'Return any 2xx status promptly to acknowledge the delivery; non-2xx responses and timeouts are retried.',
    },
  },
  security: [],
}

